function encode(data){
    return String(this.java.createSymmetricCrypto("DES/CBC/PKCS5Padding", String("KW8Dvm2N"), String("1ae2c94b")).encryptBase64(data));
}


function change(t){
    const {java,result} = this;
    if(result.get("must_"+t) == "⭕️"){
        java.upLoginData({
            ["could_"+t]:"🟢"
        })
    }else if(result.get("must_"+t) == "🟢"){
        java.upLoginData({
            ["could_"+t]:"⭕️"
        })
    }


}

function M(e){
    const {source} = this;
    return String(source.getLoginInfoMap()[e] ?? "")
}

function getMust(){
	let n = [];
	if(this.M("must_yq") == "🟢"){
		n.push(1)
	}
	if(this.M("must_bl") == "🟢"){
		n.push(2)
	}
	if(this.M("must_no") == "🟢"){
		n.push(5)
	}
	if(this.M("must_more") == "🟢"){
		n.push(6)
	}
	if(this.M("must_bh") == "🟢"){
		n.push(3)
	}


    try{
        this.java.getThemeConfig()
    }catch{
        return encodeURIComponent(this.M("必须含有的性向【请填序号，多个用英文逗号隔开【如1,2】】"))
    }


	if(n.length == 0)return "";
	return encodeURIComponent(n.join(","));
}


function getCould(){
    let n = [];
	if(this.M("could_yq") == "🟢"){
		n.push(1)
	}
	if(this.M("could_bl") == "🟢"){
		n.push(2)
	}
	if(this.M("could_no") == "🟢"){
		n.push(5)
	}
	if(this.M("could_more") == "🟢"){
		n.push(6)
	}
	if(this.M("could_bh") == "🟢"){
		n.push(3)
	}


    try{
        this.java.getThemeConfig()
    }catch{
        return encodeURIComponent(this.M("可以含有的性向【请填序号，多个用英文逗号隔开【如1,2】】"))
    }

	if(n.length == 0)return "";
	return encodeURIComponent(n.join(","));
}

function getType(){
	let n = [];
	if(this.M("找书") == "🟢"){
		n.push(1)
	}
	if(this.M("荐书") == "🟢"){
		n.push(2)
	}

	try{
        this.java.getThemeConfig()
    }catch{
        return encodeURIComponent(this.M("书单类型【请填序号，找书1，荐书2，多个用英文逗号隔开【如1,2】】") || "1,2")
    }

	if(n.length == 0)return encodeURIComponent("1,2");
	return encodeURIComponent(n.join(","));
}

