function getBooklist(list, src){
    var html = "";
    var alllist = list.recommend_novelinfo ? list.recommend_novelinfo : list;
    if(!alllist || !alllist[0] || !alllist[0].novelid) alllist = [];
    var json = src ? JSON.parse(src) : {};
    json = json.data && json.data.booklist_desc ? json.data.booklist_desc : {};

    for(var idx=0; idx<alllist.length; idx++){
        var $ = alllist[idx];
        var novelid = $.novelid;
        var cover = ($.cover || `https://i9-static.jjwxc.net/novelimage.php?novelid=${novelid}`).replace(/http:/g,'https:');
        var cover2 = `https://i9-static.jjwxc.net/novelimage.php?novelid=${novelid}`;
        var novelname = $.novelname || "";
        var authorname = $.authorname || "";
        var novelstep_name = $.novelstep_name || $.novelstep_str || $.novelstep || "";
        var xx = $.xx;
        var novelsize = $.novelsize || "";
        var novel_review_score = $.novel_review_score || ($.fav_count_str==undefined?"":$.fav_count_str+"收藏");
        var novelstar = $.novelstar || 0;
        var starStr = "";
        for(var si=0; si<novelstar; si++){ starStr += "★"; }
        starStr = starStr || $.commentdate || "";
        var novelintroshort = $.novelintroshort || "";
        var comment = $.comment || $.commentbody || "";
        comment = replaceEmoticons(comment ? comment.replace(/\s*(.*)\n/g,'&emsp;&emsp;$1<br>').replace(/<br>(?!&emsp)/gm,'<br>&emsp;&emsp;').replace(/null/g,'') : "");
        var novelclass_str = $.novelclass_str || (`第${$.chapterid}章  打分：${$.commentmark}分  订阅率：`+($.subscription_rate_info?($.subscription_rate_info.rate||""):"")+($.subscription_rate_info&&$.subscription_rate_info.iconapp=="rate_novelallbuy"?"100%":""));
        novelclass_str = novelclass_str.replace(/订阅率：$/,'');
        var onclickOpen = json.reader_name ? ` onclick="openS('${json.reader_name}','${json.readerid}')"` : '';

        html += `
        <div class="book" data-xx="${xx}">
            <div class="bookdes" onclick="addShelf('${novelid}')">
                <div class="pic" onclick="addShelf('${novelid}')">
                    <img src="${cover}" referrerpolicy="no-referrer" onerror="if(this.src!='${cover2}')this.src='${cover2}'">
                </div>
                <div class="details" onclick="addShelf('${novelid}')">
                        <p class="bookname">${novelname}</a></p>
                        <p class="author"><a onclick="window.open('https://m.jjwxc.net#bookAuthor=${authorname}')">——${authorname}</a></p>
                    <p class="tag info">${novelsize}•${novelstep_name}${novel_review_score?"•"+novel_review_score:""} </p>
                    <p class="tag intro">${novelintroshort}</p>
                    <p class="tag other">${novelclass_str}</p>
                    <p class="tag star">${starStr}</p>
                </div>
            </div>
            ${comment ? `<div class="comment"${onclickOpen}>${comment}</div>` : ""}
        </div>`;
    }
    return replaceEmoticons(html);
}

