}

function toggleMenu() {
    document.getElementById('moreMenu').classList.toggle('show');
}

// ===== 1. 按钮点击筛选（你已有的逻辑）=====
document.querySelector('.books-box').addEventListener('click', function (e) {
  if (e.target.tagName === 'BUTTON') {
    const btn = e.target;
    btn.classList.toggle('active');

    filterBooks();
  }
});

// ===== 2. 筛选函数（按钮 & 动态 book 共用）=====
function filterBooks() {
  const activeKeys = [...document.querySelectorAll('.books-box button.active')]
    .map(b => b.dataset.key);

  let checkspan = document.querySelector(".checkspan.active");

  document.querySelectorAll('.book').forEach(book => {
    const type = book.dataset.xx;
    if (activeKeys.length === 0) {
      book.style.display = '';
    } else {
      book.style.display = activeKeys.includes(type) ? '' : 'none';
    }
  });

  if (checkspan) {
    observer.disconnect(); // ✅ 关键
    RM = { page: 0, total: 1, loading: false };
    loadReplies(1, 1).finally(() => {
      observer.observe(document.querySelector('#replyContainer'), {
        childList: true,
        subtree: true
      });
    });
  }
}

// ===== 3. 监听动态出现的 .book =====
const observer = new MutationObserver(() => {
  filterBooks();
});

observer.observe(document.querySelector('#replyContainer'), {
  childList: true,
  subtree: true
});


