            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 15px;
            padding-bottom: 10px;
            border-bottom: 1px solid #e6e6e6;
        }

        .remark-modal-title {
            font-size: 14px;
            font-weight: 600;
        }

        .remark-modal-close {
            background: none;
            border: none;
            font-size: 16px;
            cursor: pointer;
            color: #999;
            transition: color 0.3s;
        }

        .remark-modal-close:hover {
            color: #333;
        }

        .remark-modal-input {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 4px;
            font-size: 12px;
            margin-bottom: 15px;
            transition: border-color 0.3s;
        }

        .remark-modal-input:focus {
            outline: none;
            border-color: var(--btn-active-color);
        }

        .remark-modal-actions {
            display: flex;
            justify-content: flex-end;
            gap: 10px;
        }

        .remark-modal-cancel {
            background: none;
            border: 1px solid #ddd;
            padding: 10px 20px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
            transition: all 0.3s;
        }

        .remark-modal-cancel:hover {
            background-color: #f5f5f5;
        }

        .remark-modal-confirm {
            background-color: var(--btn-active-color);
            color: var(--btn-text-color);
            border: none;
            padding: 10px 20px;
            border-radius: 4px;
            cursor: pointer;
            font-size: 12px;
            transition: background-color 0.3s;
        }

        .remark-modal-confirm:hover {
            background-color: var(--btn-hover-color);
        }

        /* 响应式设计 */
        @media (max-width: 480px) {
            .container {
                max-width: 100%;
            }

            .subscribe-action {
                width: 12px;
                height: 12px;
                font-size: 10px;
            }
        }

        @media (max-width: 360px) {
            .subscribe-actions {
                gap: 3px;
            }

            .subscribe-action {
                width: 12px;
                height: 12px;
                font-size: 10px;
                padding: 4px;
            }
        }

