}, true);

/* ===== 异步请求：一次重试 ===== */
const REQ_RETRY = 1;
const REQ_RETRY_DELAY = 250;
function requestRaw(url){
 return new Promise(resolve => {
  let attempt = 0;
  function run(){
   const raw = Host.ajax(url);
   if(raw){ resolve(raw); return; }
   if(attempt++ < REQ_RETRY) setTimeout(run, REQ_RETRY_DELAY * attempt);
   else resolve(null);
  }
  run();
 });
}
async function ajaxJson(url){
 const raw = await requestRaw(url);
