/* ===== 评论 API ===== */
const CmtApi = {
 async l1(postId, blogId, offset){
  const d = await ajaxJson(
   `${API.L1}?postId=${encodeURIComponent(postId)}&blogId=${encodeURIComponent(blogId)}&offset=${offset}&dunType=1`
  );
  if(!d) return { list:[], hot:[], total:null };
  return {
   list: (d.data && d.data.list) || [],
   hot: (d.data && d.data.hotList) || [],
   total: (d.data && (d.data.total || d.data.count)) || null
  };
 },

 async l2(postId, blogId, commentId, offset){
  const d = await ajaxJson(
   `${API.L2}?postId=${encodeURIComponent(postId)}&blogId=${encodeURIComponent(blogId)}&id=${encodeURIComponent(commentId)}&offset=${offset}`
  );
  if(!d) return { list:[], nextOffset:-1 };
  return {
   list: (d.data && d.data.list) || [],
   nextOffset: (d.data && d.data.offset !== undefined) ? Number(d.data.offset) : -1
  };
 },

 /* 拉取回复（MAX 页） */
 async allL2(postId, blogId, commentId){
 const all = [];
 const seen = new Set();
 let off = 0;
 for(let k = 0; k < ALL_L2_MAX; k++){
  const r = await this.l2(postId, blogId, commentId, off);
  if(!r.list.length) break;
  for(let i = 0; i < r.list.length; i++){
   const it = r.list[i];
   if(!it || !it.id) continue;
   const id = String(it.id);
   if(seen.has(id)) continue;
   seen.add(id);
   all.push(it);
  }
  const nxt = r.nextOffset;
  if(nxt === -1) break;
  if(nxt <= off) break;
  off = nxt;
 }
 return all;
},

 async para(postId, blogId, pid, offset){
  const d = await ajaxJson(
   `${API.PARA}?postId=${encodeURIComponent(postId)}&blogId=${encodeURIComponent(blogId)}&offset=${offset}&pid=${encodeURIComponent(pid)}&imgId=&commentId=`
  );
  if(!d) return { list:[], nextOffset:-1 };
  return {
   list: (d.data && d.data.list) || [],
   nextOffset: (d.data && d.data.offset !== undefined) ? Number(d.data.offset) : -1
  };
 },

 /* 拉取热评（简化版） */
 async hot(postId, blogId){
  const d = await ajaxJson(
   `${API.HOT}?postId=${encodeURIComponent(postId)}&blogId=${encodeURIComponent(blogId)}`
  );
  if(!d) return [];
  return (d.data && d.data.list) || [];
 },

 /* 拉取段评计数 */
 async counts(postId, blogId){
  const d = await ajaxJson(
   `${API.COUNTS}?postId=${encodeURIComponent(postId)}&blogId=${encodeURIComponent(blogId)}`
  );
  if(!d) return [];
  return (d.data && d.data.list) || [];
 },

 /* 从评论链接提取 postId / blogId */
 params(){
  const a = document.querySelector('a[href*="comment.do"]');
  if(!a) return null;
  const h = a.getAttribute('href');
  let p, b;
  try{
   const url = new URL(h, location.origin);
   p = url.searchParams.get('pid');
   b = url.searchParams.get('bid');
  }catch(e){
   const g = n => {
    const m = h.match(new RegExp('[?&]' + n + '=([^&]*)'));
    return m ? decodeURIComponent(m[1]) : null;
   };
   p = g('pid');
   b = g('bid');
  }
  return p && b ? { postId:p, blogId:b } : null;
 }
};
/* ===== 评论渲染 ===== */
const CR = {
 /* 次级回复 */
 reply(r, m, isPop){
  const pb = r.publisherBlogInfo || {};
  const rb = r.replyBlogInfo || {};
  const bid = val('blogId');
  const im = r.images || [];
  const ua = String(pb.blogId||'')===String(bid)?' author':'';
  const ub = String(rb.blogId||'')===String(bid)?' author':'';
  const t = fmtTime(r.publishTime);
  const at = rb.blogNickName
   ? `<span class="cm-rp-at"> 回复 </span><span class="cm-rp-user${ub}">${rb.blogNickName}</span>` 
   : ''; 
  const like = (isPop && r.likeCount) 
   ? `<i class="fa fa-heart"></i> ${esc(r.likeCount)}` 
   : ''; 
  return `
   <div class="cm-rp" data-reply-id="${esc(r.id || '')}" data-pid="${esc(r.pid || '')}">
    <div class="cm-rp-head">
     <img class="cm-rp-ava" src="${esc(avaUrl(pb.bigAvaImg))}" alt="" onerror="this.style.display='none'"> 
     <span class="cm-rp-user${ua}">${pb.blogNickName || ''}</span>${at}
    </div>
    <div class="cm-rp-body">${replaceCMImages(Emo.render(r.content, m),im)}</div>
    <div class="cm-rp-foot sp">
     <span class="cm-like">${like}</span>
     <span class="cm-meta">${esc(t)} ${r.ipLocation || ''}</span>
    </div>
   </div>`;
 },

/* 一级评论 */
item(it, m, postId, blogId, isPop){
 const pb = it.publisherBlogInfo || {};
 const im = it.images || [];
 const ua = String(pb.blogId||'')===String(blogId)?' author':'';
 const t = fmtTime(it.publishTime);
 const q = isPop ? '' : `<span class="cm-quote" value="${esc(it.pid || '')}" data-quote="${esc(it.quote || '')}"></span>`; 
 const top = it.top === 1 ? '<span class="cm-top">置顶</span>' : '';
 const like = (isPop && it.likeCount) ? `<i class="fa fa-heart"></i> ${esc(it.likeCount)}` : ''; 

 let h = `
  <div class="cm" data-comment-id="${esc(it.id || '')}" data-l2count="${esc(it.l2Count || 0)}">
   <div class="cm-head">
    <img class="cm-ava" src="${esc(avaUrl(pb.bigAvaImg))}" alt="" onerror="this.style.display='none'"> 
    <span class="cm-user${ua}">${pb.blogNickName || ''}</span>${top}${q}
   </div>
   <div class="cm-body">${replaceCMImages(Emo.render(it.content, m),im)}</div>
   <div class="cm-foot sp">
    <span class="cm-like">${like}</span>
    <span class="cm-meta">${esc(t)} ${it.ipLocation || ''}</span>
   </div>`;
 if(it.l2Count > 0) h += '<div class="cm-rp-container"></div>';
 return h + '</div>';
},

 /* 精简评论 */
 hot(it, m){
  return `<div class="cm">
   <div class="cm-body">${Emo.render(it.content, m)}</div>
   <div class="cm-foot">${esc(it.commentHot || '')} <i class="fa fa-heart" aria-hidden="true"></i></div>
  </div>`;
 },

 list(arr, postId, blogId, isPop){
  const m = Emo.mk();
  return arr.map(it => {
   Emo.pick(it, m);
   return CR.item(it, m, postId, blogId, !!isPop);
  }).join('');
 }
};

