@js: //java.log(result);
/* ===== 日志 ===== */
var Log = {
  _on: true,
  _out(tag, msg) {
    if (!Log._on) return;
    try { java.log(`[lofter][${tag}] ${msg}`); } catch (e) {}
  },
  debug(m) { Log._out('DEBUG', m); },
  warn(m) { Log._out('WARN', m); },
  error(m) { Log._out('ERROR', m); }
};

/* ===== 环境初始化 ===== */
function initEnvironment() {
  var tipMsg = "{{$.meta.msg}}";
  if (tipMsg) java.toast(tipMsg);
  try {
    var c = String(cookie.getCookie("https://www.lofter.com"));
    var m = c.match(/(?:^|;\s*)(LOFTER-[^-]+-LOGIN-AUTH)=([^;]+)/);
    if (m) {
      var h = {};
      h[m[1]] = m[2];
      source.putLoginHeader(JSON.stringify(h));
      Log.debug(`登录头已注入：${m[1]}`);
    }
  } catch (e) { Log.warn(`读取登录 Cookie 失败：${e}`); }
}

/* ===== 工具 ===== */
function escapeHtml(s) {
  if (!s) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/* ===== 提取数据 ===== */
function getPostData() {
  var pid = '',
    bid = '';
  try {
    pid = java.getString('$..post.id') || '';
    bid = java.getString('$..post.blogId') || '';
  } catch (e) { Log.warn(`postId / blogId 提取失败：${e}`); }
  var errMsg = java.getString('$..msg') || '';
  var titleRaw = java.getString('$..post.title||$..post.longInfo.title') || ''; 
  var coName = java.getString('$..postCollection.name') || '';
  var coId = java.getString('$..postCollection.id') || '';
  var coDesc = java.getString('$..postCollection.description') || '';
  var coBlogId = java.getString('$..postCollection.blogId') || bid;
  var blogUrl = java.getString('$..blogPageUrl') || '';
  var blogName = java.getString('$..blogInfo.blogName') || '';
  var showGift = Number(java.getString('$..showGift')) || 0;

  var returnContent = [];
  try {
    var parsed = JSON.parse(src);
    var posts = parsed && parsed.response && parsed.response.posts ? parsed.response.posts : [];
    posts.forEach(p => {
      var rcs = p && p.post && p.post.returnContent ? p.post.returnContent : [];
      rcs.forEach(rc => { if (rc && rc.content) returnContent.push({ title: rc.planTypeName ? `🎈 ${rc.planTypeName}` : '', content: rc.content || '', images: rc.images || [] }); });
    });
  } catch (e) { Log.warn(`付费内容解析失败：${e}`); }

  /* 有付费回礼但未解锁 → 拉卡片 */
  if (showGift > 0 && !returnContent.length && pid && bid) {
    var si = fetchSupportInfo(pid, bid, coId);
    var rg = si && si.returnGifts && si.returnGifts[0];
    if (rg) returnContent.push({ title: '', content: buildSupportCard(rg, blogUrl), images: [] });
  }
  /* 数据删缺 */
  var deleted = /删除|不存在|下架|失效|不可见/i.test(errMsg) || (!pid && !bid && !titleRaw && !java.getString('$..post.content||$..post.longInfo.content') && !java.getString('$..blogInfo.blogNickName')); 

  return {
    postId: pid,
    blogId: bid,
    blogUrl: blogUrl,
    blogName: blogName,
    titleRaw: titleRaw,
    errMsg: errMsg, deleted: deleted,
    tagsRaw: java.getString('$..tag') || '',
    authorImg: java.getString('$..blogInfo.bigAvaImg') || '',
    authorName: java.getString('$..blogInfo.blogNickName') || '',
    photoLinks: java.getString('$..photoLinks') || '',
    publishTime: Number(java.getString('$..publishTime')) || 0,
    coId: coId,
    coBlogId: coBlogId,
    coName: coName,
    coDesc: coDesc,
    favorite: java.getString('$..postCount.favoriteCount') || '0',
    response: java.getString('$..postCount.responseCount') || '0',
    subscribe: java.getString('$..postCount.subscribeCount') || '0',
    share: java.getString('$..postCount.shareCount') || '0',
    showGift: showGift,
    embedData: java.getString('$..embed') || '',
    content: java.getString('$..post.content||$..post.longInfo.content') || '',
    returnContent: returnContent,
    imagesUrl: java.getString('$..post.firstImageUrl') || ''
  };
}

/* ===== 页面 ===== */
/* 首图组（无正文图时兜底） */
function buildFirstImageHtml(json) {
  if (!json) return '';
  try {
    var urls = JSON.parse(json);
    if (!urls.length) return '';
    var html = '<div class="iv iv--first"><div class="iv-stage">';
    for (var i = 0; i < urls.length; i++) {
      if (!urls[i]) continue;
      html += `
<div class="iv-slide ${i===0?'active':''}" data-index="${i}"><img src="${escapeHtml(urls[i])}" alt="图片" ${i>0?'loading="lazy"':''}><span class="iv-bar"><button class="iv-btn iv-zoom" type="button" tite="放大"><i class="fa fa-search-plus" aria-hidden="true"></i></button><button class="iv-btn iv-open" type="button" title="查看"><i class="fa fa-location-arrow" aria-hidden="true"></i></button><span class="iv-page">${i+1}/${urls.length}</span></span></div>`;
    }
    return html + '</div></div>';
  } catch (e) { Log.warn(`firstImageUrl 解析失败：${e}`); return ''; }
}

/* 图组 */
function buildImageHtml(json) {
  if (!json) return '';
  try {
    var ps = JSON.parse(json);
    var html = '<div class="iv"><div class="iv-stage">';
    for (var i = 0; i < ps.length; i++) {
      var u = ps[i].orign || ps[i].small || ps[i].url || '';
      if (!u) continue;
      html += `
<div class="iv-slide ${i===0?'active':''}" data-index="${i}"><img src="${escapeHtml(u)}" alt="图片" ${i>2?'loading="lazy"':''}><span class="iv-bar"><button class="iv-btn iv-zoom" type="button"title="放大"><i class="fa fa-search-plus" aria-hidden="true"></i></button><button class="iv-btn iv-open" type="button" title="查看"><i class="fa fa-location-arrow" aria-hidden="true"></i></button><span class="iv-page">${i+1}/${ps.length}</span></span></div>`;  
    }
    return html + '</div></div>';
  } catch (e) { Log.warn(`photoLinks 解析失败：${e}`); return ''; }
}

/* 视频 */
function buildVideoHtml(json) {
  if (!json || json.indexOf("originUrl") === -1) return '';
  try {
    var u = JSON.parse(json).originUrl;
    return u ? `<div class="video"><iframe src="${escapeHtml(u)}" sandbox="allow-scripts allow-same-origin" allowfullscreen></iframe></div>` : '';
  } catch (e) { Log.warn(`embed 解析失败：${e}`); return ''; }
}

/* 作者栏 */
function buildAuthorHtml(img, name) {
  var av = `<img src="${escapeHtml(img).replace(/\?.+$/,'')}?imageView&thumbnail=84x84&stripmeta=0&quality=90&type=webp&typefallback=jpg" class="post-author__avatar" onerror="this.style.display='none'">`;
  return `<div class="post-author">${av}<span class="post-author__name">${escapeHtml(name)}</span> <span class="btn btn--follow" data-action="follow" title="关注作者"><i class="fa fa-user"></i></span><span class="btn btn--article-add" data-action="article-add" title="收藏文章"><i class="fa fa-asterisk"></i></span><span class="btn btn--collection-trigger" data-action="collection-trigger" title="合集列表"><i class="fa fa-slack"></i></span></div>`;
}

/* 段落处理 */
function processParagraphs(html) {
  if (!html) return html;
  var idx = 0;

  return String(html).replace(/<p\b([^>]*)>([\s\S]*?)<\/p>/gi, (m, attrs, content) => {
    var fallbackPid = 'p_i' + idx;
    var idm = attrs.match(/\bid="([^"]*)"/i);
    var actualPid = idm ? idm[1] : fallbackPid;
    if (!idm) attrs += ` id="${fallbackPid}"`;
    idx++;

    var c = content
      .replace(/(\s*<br\s*\/?>\s*)+/gi, '<br>')
      .replace(/<[a-z]{1,10}>\s*<\/[a-z]{1,10}>\s*/gi, '')
      .replace(/\[\s+/g, '[').replace(/\s+\]/g, ']')
      .replace(/【\s+/g, '【').replace(/\s+】/g, '】')
      .replace(/〖\s+/g, '〖').replace(/\s+〗/g, '〗')
      .replace('&type=jpg', '')
      .replace(/^[　\s]+$/g, '').trim()
      .split(/(<[^>]+>)/).map(p => p[0] === '<' ? p : p.trim()).join('');

    if (/^(?:\s|　|<br>|&nbsp;|&#160;|&#xa0;)*$/i.test(c)) {
      attrs = /\bstyle\s*=/i.test(attrs) ?
        attrs.replace(/\bstyle\s*=\s*(['"])([\s\S]*?)\1/i,
          (_, q, s) => ` style=${q}${s.replace(/;\s*$/,'')};display:none;${q}`) :
        attrs.trim() + ' style="display:none"';
      return `<p ${attrs}></p>`;
    }
    if (!/^\u3000/.test(c)) c = '\u3000' + c;

    return `<p ${attrs.trim()}>${c}</p>`;
  });
}

/* 付费内容（已解锁） */
function buildUnlockHtml(list) {
  if (!list || !list.length) return '';
  return list.map(item => {
    var imgs = '';
    if (item.images && item.images.length) {
      imgs = '<div class="unlock-item__images">';
      item.images.forEach(img => {
        var u = img.orign || img.raw || img.url || '';
        if (u) imgs += `<img src="${escapeHtml(u)}" alt="回礼图片">`;
      });
      imgs += '</div>';
    }
    var title = item.title ? `<div class="unlock-item__title">${escapeHtml(item.title)}</div>` : '';
    return `<div class="unlock-item">${title}<div class="unlock-item__content">${item.content}</div>${imgs}</div>`;
  }).join('');
}

/* 付费内容（未解锁） */
function fetchSupportInfo(pid, bid, cid) {
  if (!pid || !bid) return null;
  /* 移去下述内置函数 encodeURIComponent() */
  var q = `postId=${pid}&blogId=${bid}&openFansVipPlan=0&vipFans=0${cid?`&collectionId=${cid}`:''}&scene=note&postType=1`;
  try {
    var d = JSON.parse(java.ajax(`https://api.lofter.com/v1.1/trade/gift/post/newSupportInfo?${q}`));
    if (d && d.code === 200) return d.data;
  } catch (e) { Log.warn(`newSupportInfo 拉取失败：${e}`); }
  return null;
}
function buildSupportCard(rg, url) {
  var tags = [];
  var appUrl = /^https:/.test(url) ? url.replace('https:', 'lofter:') : '';
  (rg.labels || []).forEach(l => tags.push(`<span class="support-tag">${escapeHtml(l.label)}</span>`));
  (rg.feedbacks || []).forEach(f => tags.push(`<span class="support-tag support-tag--comment">${escapeHtml(f)} <i class="fa fa-angle-right"></i></span>`));

  var plan = (rg.planType && rg.planType.name) || '';
  var badge = plan ? `<span class="support-badge">${escapeHtml(plan)}</span>` : '';
  var title = rg.title ? `<span class="support-title">${escapeHtml(rg.title)}</span>` : '<span class="support-title">惊喜衍生剧场</span>';
  var appBtn = appUrl ? `<button class="support-app-btn" type="button" onclick="java.openUrl('${escapeHtml(appUrl)}')" title="在 App 中打开">${svgLib.logo||'J'}</button>` : '';
  var header = (badge || title) ? `<div class="support-header">${badge}${title}${appBtn}</div>` : '';
  const lockCount = [
    rg.wordCount > 0 && `${rg.wordCount} 字`,
    rg.imgCount > 0 && `${rg.imgCount} 图`
  ].filter(Boolean).join(' + ');

  return `<div class="support-card">${header}` +
    (tags.length ? `<div class="support-tags">${tags.join('')}</div>` : '') +
    (rg.promotion ? `<div class="support-promotion">${escapeHtml(rg.promotion)}</div>` : '') +
    (rg.digest ? `<div class="support-digest">${escapeHtml(rg.digest).trim().replace(/\s+/g,'<br>')}...</div>` : '') +
    (lockCount ? `<div class="support-lock"><i class="fa fa-lock"></i><span>解锁余 ${lockCount}</span></div>` : '') +
    '</div>';
}

/* 合集 */
function buildCollectionHtml(name, desc) {
  if (name) name = String(name).trim();
  if (!name) return '';
  var html = `<div class="post-col"><span class="post-col__label">合集: </span><span class="post-col__info" data-action="collection-info" title="查看合集">${escapeHtml(name)}</span><span class="btn btn--import" data-action="collection-import" title="收藏合集"><i class="fa fa-bookmark" aria-hidden="true"></i></span><span class="btn btn--open" data-action="collection-open" title="打开合集"><i class="fa fa-folder" aria-hidden="true"></i></span></div>`;
  if (desc && String(desc).trim()) html += `<div><details class="post-col__details"><summary></summary><div class="post-col__desc">${escapeHtml(desc)}</div></details></div>`;
  return html;
}

/* 标签 */
function buildTagsHtml(raw) {
  if (!raw) return '';
  var parts = ['<div class="post-tags"><span class="post-tags__label">标签: </span>'];
  raw.split(',').forEach(t => { t = t.trim(); if (t) parts.push(`<span class="post-tags__item">${escapeHtml(t)}</span>`); });
  return parts.join('') + '</div>';
}

/* 计数 */
function buildCountsHtml(fav, resp, sub, share, gift) {
  return `<div class="post-counts"><span class="post-counts__item p-count-favorite">${fav}</span><span class="post-counts__item p-count-subscribe">${sub}</span><span class="post-counts__item p-count-response">${resp}</span><span class="post-counts__item p-count-share">${share}</span><span class="post-counts__item p-count-showgift">${gift}</span></div>`;
}

/* 底链  */
function buildLinksHtml(pid, bid, url) {
  var c = `https://www.lofter.com/comment.do?pid=${pid}&bid=${bid}&listlinkcolor=828d95&listcontentcolor=737373&listbordercolor=ddd&inputbordercolor=ddd`;
  return `<div class="post-links"><span>点击跳转: </span><a href="${c}">评论链接</a> <a href="javascript:void(0)" onclick="java.openUrl('${escapeHtml(url)}')">查看原网页</a> <a href="javascript:void(0)" class="article-add" data-action="article-add">收藏页面</a></div>`;
}

/* ===== 组装 HTML ===== */
function assembleHtml(pd, cm) {
  if (pd.deleted) { return `<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>作品已删除</title><link rel="stylesheet" href="//cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css"/></head><body><div class="post-deleted"><div class="post-deleted__icon"><i class="fa fa-ban"></i></div><div class="post-deleted__title">作品已删除或不可见</div><div class="post-deleted__desc">${escapeHtml(pd.errMsg||'')}</div></div></body></html>`; } 
  var cardHtml = '';
  var titleTop = pd.titleRaw != '' ? `<title>${escapeHtml(pd.titleRaw)}</title>` : '<title>LOFTER</title>';
  var titleHtml = pd.titleRaw != '' ? `<h1 class="post-title">${escapeHtml(pd.titleRaw)}</h1>` : ''; 
  var authorHtml = buildAuthorHtml(pd.authorImg, pd.authorName);
  var imagesHtml = buildImageHtml(pd.photoLinks);
  var videoHtml = buildVideoHtml(pd.embedData);
  var contentHtml = `<section class="post-content">\n  ${pd.content}\n  </section>`;
  if (imagesHtml.indexOf('<img') === -1 && videoHtml.indexOf('<iframe') === -1 && contentHtml.indexOf('<img') === -1)
    imagesHtml = buildFirstImageHtml(pd.imagesUrl);

  var unlockHtml = buildUnlockHtml(pd.returnContent);
  var tagsHtml = buildTagsHtml(pd.tagsRaw);
  var timeHtml = `<div class="post-time">𝕋𝕀𝕄𝔼 <span>${java.timeFormatUTC(pd.publishTime,'yyyy-MM-dd HH:mm:ss',8)}</span></div>`;
  var countsHtml = buildCountsHtml(pd.favorite, pd.response, pd.subscribe, pd.share, pd.showGift); 
  var collectionHtml = buildCollectionHtml(pd.coName, pd.coDesc);
  var linksHtml = buildLinksHtml(pd.postId, pd.blogId, pd.blogUrl);

  // 已将对应字体提取到本地 <link rel="stylesheet" href="//cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css"/> 
  var headHtml = `<meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
  ${titleTop}
  <link rel="preconnect" href="https://fontsapi.zeoseven.com" crossorigin />
  <link rel="stylesheet" href="https://fontsapi.zeoseven.com/442/semi-bold/result.css" onerror="this.href='https://fontsapi-storage.zeoseven.com/442/main/result.css'" />`; 

  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  ${headHtml}
</head>
<body>
  <input type="hidden" id="blogId" value="${escapeHtml(pd.blogId)}"> 
  <input type="hidden" id="postId" value="${escapeHtml(pd.postId)}"> 
  <input type="hidden" id="author-name" value="${escapeHtml(pd.authorName)}"> 
  <input type="hidden" id="author-avatar" value="${escapeHtml(pd.authorImg)}"> 
  <input type="hidden" id="article-title" value="${escapeHtml(pd.titleRaw)}"> 
  <input type="hidden" id="article-url" value="${escapeHtml(pd.blogUrl)}"> 
  <input type="hidden" id="collection-name" value="${escapeHtml(pd.coName)}"> 
  <input type="hidden" id="collection-id" value="${escapeHtml(pd.coId)}"> 
  <article class="post">
    <header class="post-header">
      ${titleHtml}
      ${authorHtml}
      ${collectionHtml}
      ${timeHtml}
    </header>
    <section class="post-media">
      ${imagesHtml}
      ${videoHtml}
    </section>
    ${contentHtml}
    <section class="unlock-section">
      ${unlockHtml}
    </section>
    <footer class="post-footer">
      ${tagsHtml}
      ${countsHtml}
    </footer>
    <section class="comments" data-mode="">
    </section>
    <nav class="post-links-container">
      ${linksHtml}
    </nav>
  </article>
</body>
<style>@font-face{font-family:'iconfont';font-display:swap;src:url("${IconFontData}") format('woff2');}</style>
</html>`;
}

function main() {
  initEnvironment();
  var pd = getPostData();
  pd.content = processParagraphs(pd.content);
  return assembleHtml(pd);
}

main();

