 const root = data.response || data.data || data;
 const info = root.blogInfo || (root.posts && root.posts[0] && root.posts[0].blogInfo) || {};
 return trimStr(info.blogNickName || info.name || '');
}

async function fetchArticleTitle(url) {
 const parsed = parseArticle(url);
 if(!parsed) return '';
 const data = await ajaxJson(`${API_BASE}/oldapi/post/detail.api?product=lofter-android-${VER.R1},${JSON.stringify({
  method:'POST','accept-encoding':'gzip, deflate',
  body:`targetblogid=${parsed.blogId}&blogdomain=${parsed.domain}.lofter.com&postid=${parsed.postId}`
 })}`);
 if(!data) return '';
 const candidatePaths = [
  ['response', 'posts', 0, 'post', 'title'],
  ['response', 'posts', 0, 'post', 'digest'],
  ['response', 'posts', 0, 'post', 'tagList', 0]
 ];
 let title = '';
 for (let i = 0; i < candidatePaths.length; i++) {
  let value = data;
  for (let j = 0; j < candidatePaths[i].length; j++) {
   if(value == null) { value = undefined; break; }
   value = value[candidatePaths[i][j]];
  }
  if(value !== undefined && value !== null && String(value).trim() !== '') {
   title = String(value);
   break;
  }
 }
 title = stripHtml(title);
 if(Array.from(title).length > 30) title = Array.from(title).slice(0, 30).join('');
 return title;
}

async function updateColCount(col) {
 const today = getToday();
 const parsed = parseColCount(col.count);
 const hasUpdate = col.update && +col.update > 0;
 if(parsed && parsed.lastDate === today && hasUpdate) return false;
 const data = await ajaxJson(`${API_BASE}/v1.1/postCollection.api?product=lofter-android-${VER.R2}&method=getCollectionDetail&offset=0&limit=1&collectionid=${encodeURIComponent(col.id)}`);
 if(!data) return false;
 const collection = (data.response && data.response.collection) || (data.data && data.data.collection);
 if(!collection) return false;
 /* 写回之前重新定位 */
 const fresh = findItem(Store.state.collections, c => String(c.id) === String(col.id));
 if(!fresh) return false;
 let changed = false;
 if(collection.postCount !== undefined && !isNaN(collection.postCount)) {
  fresh.count = `${today}/${parsed?parsed.newCount:collection.postCount}/${collection.postCount}`;
  changed = true;
 }
 const ts = Math.max(+collection.updateTime || 0, +collection.lastPublishTime || 0);
 if(ts > 0) { fresh.update = String(ts); changed = true; }
 if(changed) { Store.markDirty('collections'); Store.scheduleFlush(); }
 return changed;
}

async function loadRank(sortNo, rankType) {
 const data = await ajaxJson(`${API_BASE}/newapi/hotsearch/ranklist.json?product=lofter-android-${VER.R1}&t=0`);
 if(!data || !data.data) { Host.toast('获取榜单失败'); return; }
 const rankList = Array.isArray(data.data.rankList) ? data.data.rankList : [];
 const rank = rankList.find(r => +r.sortNo === +sortNo);
 if(!rank) { Host.toast('未找到榜单'); return; }
 Store.setUI('currentRank', {
  type: rankType, sortNo, title: rank.listName||'榜单',
  items: (Array.isArray(rank.hotLists)?rank.hotLists:[]).map(it=>({
   title: trimStr(it.title), url: it.url||'',
   blogId: it.blogId||'', postId: it.postId||'',
   postType: it.postType || '',
   img: it.img||'', icon: it.icon||'', iconInfo: it.iconInfo||null
  }))
 });
}

async function loadSubscrCols() {
 Store.reload();
 const data = await ajaxJson(`${API_BASE}/newapi/subscribeCollection/list.json?offset=0&limit=${PAGE.COLL}`);
 const list = (data && data.data && Array.isArray(data.data.guessLikeList)) ? data.data.guessLikeList : [];
 if(!list.length) { Host.toast('暂无推荐合集'); return; }
