}

/* ===== 区块 diff 渲染 ===== */
const SECTION_DEFS = [
 ['special', () => renderSpecial()],
 ['subscr', () => renderSubscrCols()],
 ['rank', () => renderRank()],
 ['tags', () => renderTags()],
 ['cols', () => renderCols()],
 ['authors', () => renderAuthors()],
 ['articles', () => renderArticles()],
 ['history', () => renderHistory()]
];
const sectionHtmlCache = {};
let sectionNodes = null;

function ensureSections() {
 if(sectionNodes) return sectionNodes;
 sectionNodes = {};
 container.innerHTML = '';
 for (let i = 0; i < SECTION_DEFS.length; i++) {
  const key = SECTION_DEFS[i][0];
  const wrap = document.createElement('div');
  wrap.className = 'section-wrap';
  wrap.dataset.section = key;
  wrap.style.display = 'contents';
  container.appendChild(wrap);
  sectionNodes[key] = wrap;
 }
 return sectionNodes;
}

function invalidateSection(key) {
 if(key) sectionHtmlCache[key] = undefined;
 else for (const k in sectionHtmlCache) sectionHtmlCache[k] = undefined;
}

function pickList(key) {
 if(key === 'tags') {
  const cleandMode = Store.getUI('showCleandTags') && Store.getUI('currentFilter') === 'tag';
  const list = cleandMode ? Store.state.cleandTags : Store.state.tags;
  return list.filter(t => cleandMode || shouldShow(isHidden(t, 'tag')));
 }
 if(key === 'cols') return Store.state.collections.filter(c => shouldShow(isHidden(c, 'col')));
 if(key === 'authors') return Store.state.authors.filter(a => {
  const hiddenState = String(a.hidden || Hidden.SHOW);
  if(hiddenState === Hidden.CLEAN) return Store.getUI('showHidden') && Store.getUI('manageMode');
  return shouldShow(isHidden(a, 'author'));
 });
 if(key === 'articles') return Store.state.articles.filter(a => shouldShow(String(a.hidden) === Hidden.HIDE));
 return [];
}

/* =====  行级渲染 ===== */
function itemAttrs(type, value) {
 return `data-item-type="${type}" data-item-value="${value}"`;
}

function buildEye(type, value, icon, title) {
 const label = title || '切换隐藏';
 return `<button type="button" class="eye-btn" aria-label="${label}" title="${label}" ${itemAttrs(type,value)}>${icon}</button>`;
}

function buildActions(type, value, opts) {
 opts = opts || {};
 const attrs = itemAttrs(type, value);
 let html = '<span class="item-actions">';
 if(opts.editable) html += `<button type="button" class="edit-btn" aria-label="修改" title="修改" ${attrs}>${svg.editor}</button>`;
 html += `<button type="button" class="del-btn" aria-label="删除" title="删除" ${attrs}>${svg.trash}</button>`;
 return html + '</span>';
}

function buildDrag(type, value) {
 return `<span class="drag-handle" role="button" tabindex="0" aria-label="拖动排序" data-item-type="${type}" data-item-value="${value}">${svg.drag}</span>`;
}

function buildItem(cfg) {
 let cls = 'item ' + cfg.itemClass;
 if(cfg.extraClass) cls += ' ' + cfg.extraClass;
 if(cfg.hidden) cls += ' hidden-item';
 let body = '';
 if(Store.getUI('manageMode') && cfg.dragType) body += buildDrag(cfg.dragType, cfg.dragValue);
 if(cfg.eye) body += cfg.eye;
 if(cfg.avatar) body += cfg.avatar;
 body += cfg.nameHtml;
 if(cfg.actions) body += cfg.actions;
 return `<div class="${cls}"${cfg.attrs||''}>${body}</div>`;
}

function buildSection(title, bodyHtml) {
 return `<div class="section"><div class="section-title">${title}</div><div class="list">${bodyHtml}</div></div>`;
}

function renderTagRow(tag) {
 const cleandMode = Store.getUI('showCleandTags') && Store.getUI('currentFilter') === 'tag';
 const isItemHidden = cleandMode ? false : isHidden(tag, 'tag');
 const isDisabled = cleandMode && Store.state.disCleandTags.indexOf(tag) !== -1;
 const type = cleandMode ? 'cleandTag' : 'tag';
 const value = escapeHtml(tag);
 let eye = '';
 if(cleandMode) eye = buildEye('cleandTag', value, isDisabled ? svg.eyeClosed : svg.eyeCleand, isDisabled ? '启用' : '禁用');
 else if(Store.getUI('showHidden')) eye = buildEye('tag', value, isItemHidden ? svg.eyeClosed : svg.eyeOpen);
 return buildItem({
  itemClass: 'tag-item',
  extraClass: cleandMode ? 'cleand-tag-item' : '',
  hidden: isItemHidden || isDisabled,
  dragType: type,
  dragValue: value,
  eye: eye,
  nameHtml: `<span class="name-text">${value}</span>`,
  actions: Store.getUI('manageMode') ? buildActions(type, value) : '',
  attrs: cleandMode ? ` data-cleand-tag="${value}"` : ` data-tag="${value}"`
 });
}

function renderColRow(col) {
 const isItemHidden = isHidden(col, 'col');
 const today = getToday();
 const parsed = parseColCount(col.count);
 const updatedToday = parsed && parsed.lastDate === today && parsed.oldCount !== parsed.newCount;
 const hasUpdate = col.update && +col.update > 0;
 const value = escapeAttr(col);
 let svgPrefix = '', nameText = col.name;
 Object.keys(MARKERS).sort((a, b) => col.name.indexOf(a) - col.name.indexOf(b)).forEach(marker => {
  let idx;
  while ((idx = nameText.indexOf(marker)) !== -1) {
   svgPrefix += MARKERS[marker];
   nameText = nameText.slice(0, idx) + nameText.slice(idx + marker.length);
  }
 });
 nameText = escapeHtml(nameText);
 let nameHtml = svgPrefix + `<span class="name-text">${nameText}</span>`;
 if(Store.getUI('manageMode')) nameHtml += ` <span class="id-text">(ID:${escapeHtml(col.id)})</span>`;
 else if(Store.getUI('showHidden') && hasUpdate) nameHtml += `<span class="id-text${updatedToday?' up':''}">${fmtUpdate(col.update)}</span>`;
 else if(col.count) {
  const displayCount = parsed ? parsed.newCount : col.count;
  nameHtml += `<span class="id-text${updatedToday?' up':''}">${displayCount}篇</span>`;
 }
 return buildItem({
  itemClass: 'col-item',
  hidden: isItemHidden,
  dragType: 'col',
  dragValue: value,
  eye: Store.getUI('showHidden') ? buildEye('col', value, isItemHidden ? svg.eyeClosed : svg.eyeOpen) : '',
  nameHtml: nameHtml,
  actions: Store.getUI('manageMode') ? buildActions('col', value, { editable: true }) : '',
  attrs: ` data-col-id="${escapeHtml(col.id)}" data-col-name="${escapeHtml(col.name)}"`
 });
}

function renderAuthorRow(author) {
 const hiddenState = String(author.hidden || Hidden.SHOW);
 const isItemHidden = isHidden(author, 'author');
 const value = escapeAttr(author);
 const showEye = Store.getUI('showHidden') || Store.getUI('manageMode');
 const eyeIcon = hiddenState === Hidden.HIDE ? svg.eyeClosed : hiddenState === Hidden.CLEAN ? svg.eyeCleand : svg.eyeOpen;
 let nameHtml = `<span class="name-text">${escapeHtml(author.name)}</span>`;
 if(Store.getUI('manageMode')) nameHtml += ` <span class="id-text">(BID:${escapeHtml(author.blogId)})</span>`;
 const showAvatar = !Store.getUI('manageMode') && author.avatar; 
 return buildItem({
  itemClass: 'author-item',
  extraClass: hiddenState === Hidden.CLEAN ? 'cleand-author-item' : '',
  hidden: isItemHidden,
  dragType: 'author',
  dragValue: value,
  eye: showEye ? buildEye('author', value, eyeIcon) : '',
  avatar: showAvatar ? `<img class="author-avatar" src="${escapeHtml(safeUrl(author.avatar))}" alt="头像">` : '', 
  nameHtml: nameHtml,
  actions: Store.getUI('manageMode') ? buildActions('author', value, { editable: true }) : '',
  attrs: ` data-author-blog-id="${escapeHtml(author.blogId)}" data-author-name="${escapeHtml(author.name)}" data-hidden="${hiddenState}"`
 });
}

function renderArticleRow(article) {
 const hiddenState = String(article.hidden || Hidden.SHOW);
 const isItemHidden = hiddenState === Hidden.HIDE;
 const value = escapeAttr(article);
 return buildItem({
  itemClass: 'article-item',
  hidden: isItemHidden,
  dragType: 'article',
  dragValue: value,
  eye: Store.getUI('showHidden') ? buildEye('article', value, isItemHidden ? svg.eyeClosed : svg.eyeOpen) : '',
  nameHtml: `<span class="name-text">${escapeHtml(article.title)}</span>`,
  actions: Store.getUI('manageMode') ? buildActions('article', value, { editable: true }) : '',
  attrs: ` data-article-url="${escapeHtml(article.url)}" data-article-title="${escapeHtml(article.title)}" data-hidden="${hiddenState}"`
 });
}

/* =====  历史记录 ===== */
function renderHistoryRow(entry) {
 const manageMode = Store.getUI('manageMode');
 const value = escapeAttr(entry);
 let body = '';
 if(manageMode) body += buildDrag('history', value);
 body += `<span class="name-text">${escapeHtml(entry.title || entry.url)}</span>`;
 if(Store.getUI('showHidden') && entry.collectionName) {
  body += `<span class="id-text">${escapeHtml(entry.collectionName)}</span>`;
 }
 if(manageMode) {
  const isFaved = Store.state.articles.some(a => a.url === entry.url);
  const label = isFaved ? '取消收藏' : '收藏到文章';
  body += `<button type="button" class="fav-btn${isFaved?' active':''}" data-fav-url="${escapeHtml(entry.url)}" aria-label="${label}" title="${label}">${isFaved?svg.star:svg.staro}</button>`;
  body += buildActions('history', value);
 }
 return `<div class="item history-item" data-history-url="${escapeHtml(entry.url)}" data-history-title="${escapeHtml(entry.title)}">${body}</div>`;
}

function renderHistory() {
 if(Store.getUI('currentFilter') !== 'history') return '';
 const list = Store.state.history || [];
 if(!list.length) return '';
 const body = list.map(entry => renderHistoryRow(entry)).join('');
 return buildSection('🕘 历史', body);
}

/* =====  收藏切换 ===== */
function toggleFav(url, btn) {
 Store.reload();
 Store.reloadHistory();
 const isFaved = Store.state.articles.some(a => a.url === url);
 if(isFaved) {
  Store.mutate('articles', l => l.filter(a => a.url !== url));
  Store.flush();
  Host.toast('已取消收藏');
 } else {
  const entry = findItem(Store.state.history, x => x.url === url);
  if(!entry) { Host.toast('历史记录不存在'); return; }
  const title = entry.title || url;
  Store.mutate('articles', l => (l.unshift({ title, url, hidden: Hidden.SHOW }), l));
  Store.flush();
  Host.toast(`已收藏「${title}」`);
 }
 invalidateSection('articles');
 const isNowFaved = Store.state.articles.some(a => a.url === url);
 if(btn) {
  btn.classList.toggle('active', isNowFaved);
  btn.innerHTML = isNowFaved ? svg.star : svg.staro;
  const label = isNowFaved ? '取消收藏' : '收藏到文章';
  btn.title = label;
  btn.setAttribute('aria-label', label);
 }
 if(Store.getUI('currentFilter') === 'article') { invalidateSection(); render(); }
}

/* =====  区块渲染 ===== */
function renderSpecial() {
 if(Store.getUI('manageMode') || Store.getUI('showHidden') || Store.getUI('currentFilter') !== 'all') return '';
 const currentRank = Store.getUI('currentRank');
 const rankButtons = RANKS.map(b => {
  const active = currentRank && currentRank.sortNo === b.sortNo && currentRank.type === b.type ? ' active' : ''; 
  return `<div class="item rank-btn${active}" role="button" tabindex="0" aria-pressed="${active?'true':'false'}" data-sortno="${b.sortNo}" data-type="${b.type}">${b.label}</div>`; 
 }).join('');
 const readmeButton = Host.getVariable() ? '' : '<div class="item readme-item">首次使用请点击此处</div>';
 const subCollections = Store.getUI('subscrCollections');
 const subActive = !!(subCollections && subCollections.length);

 return `<div class="section"><div class="section-title" style="display:none">🌱 常规</div><div class="list">${readmeButton}<div class="item random-item">随便看看</div><div class="item bookstore-item">书馆</div><div class="item subscribe-btn${subActive?' active':''}">推荐订阅</div>${rankButtons}</div></div>`;
}

function renderSubscrCols() {
 const subCollections = Store.getUI('subscrCollections');
 if(!subCollections || !subCollections.length) return '';
 if(Store.getUI('manageMode') || Store.getUI('showHidden') || Store.getUI('currentFilter') !== 'all') return '';
 const body = subCollections.filter(c => c.collectionId).map(c => {
  const name = c.name || '未命名合集';
  const info = c.postCount !== undefined ? `${c.postCount}篇` : '';
  const countHtml = info ? `<span class="id-text">${escapeHtml(info)}</span>` : '';
  return `<div class="item sub-col-item" data-id="${c.collectionId}" data-name="${escapeHtml(name)}">${escapeHtml(name)}${countHtml}</div>`;
 }).join('');
 if(!body) return '';
 return `<div class="section"><div class="section-title">📒 推荐订阅合集</div><div class="list">${body}</div></div>`;
}

function renderRank() {
 const currentRank = Store.getUI('currentRank');
 if(!currentRank) return '';
 if(Store.getUI('manageMode') || Store.getUI('showHidden') || Store.getUI('currentFilter') !== 'all') return '';
 let html = `<div class="section"><div class="section-title">🔥 ${currentRank.title}</div><div class="list">`;
 const rankType = currentRank.type;
 currentRank.items.forEach((item, idx) => {
  let displayTitle = item.title, avatarHtml = '';
  if(rankType === 'hottag') {
   displayTitle = displayTitle.replace(/^#\s*/, '');
   const icon = safeUrl(item.icon);
   if(icon) avatarHtml = `<img class="tag-avatar" src="${escapeHtml(icon)}" alt="图标">`;
  }
  if(rankType === 'hotarticle') {
   const pt = String(item.postType || '');
   const icon = pt === '2' ? svg.fileimage : pt === '4' ? svg.filevideo : svg.filenote;
   avatarHtml = `<i class="tag-avatar">${icon}</i>`;
  } else if(rankType === 'hotuser') {
   const icon = safeUrl(item.icon);
   if(icon) avatarHtml += `<img class="tag-avatar" src="${escapeHtml(icon)}" alt="图标">`;
   const avatar = safeUrl(item.img);
   if(avatar) avatarHtml += `<img class="author-avatar" src="${escapeHtml(avatar).replace(/\?.+$/,'')}?imageView&thumbnail=84x84&stripmeta=0&quality=90&type=webp&typefallback=jpg" alt="图像">`;
  } else if(rankType === 'hotword') {
   const iconInfo = item.iconInfo && safeUrl(item.iconInfo.icon);
   if(iconInfo) avatarHtml = `<img class="tag-avatar" src="${escapeHtml(iconInfo)}" alt="活动">`;
   const icon = safeUrl(item.icon);
   if(icon) avatarHtml = `<img class="tag-avatar" src="${escapeHtml(icon)}" alt="图标">`;
  }
  html += `<div class="item rank-item" data-index="${idx}">${avatarHtml}<span class="name-text">${escapeHtml(displayTitle)}</span></div>`;
 });
 return html + '</div></div>';
}

/* 四个列表区块共用：全量渲染 */
function renderListSection(key, title, visibleItems, renderRow) {
 if(!visibleItems.length) return '';
 return buildSection(title, visibleItems.map(renderRow).join(''));
}

function renderTags() {
 const currentFilter = Store.getUI('currentFilter');
 if(currentFilter !== 'all' && currentFilter !== 'tag') return '';
 if(currentFilter === 'all' && !Store.state.allType.tag) return '';
 const cleandMode = Store.getUI('showCleandTags') && currentFilter === 'tag';
 return renderListSection('tags', cleandMode ? '🎯 屏蔽' : '🏷️ 标签', pickList('tags'), renderTagRow);
}

function renderCols() {
 const currentFilter = Store.getUI('currentFilter');
 if(currentFilter !== 'all' && currentFilter !== 'col') return '';
 if(currentFilter === 'all' && !Store.state.allType.col) return '';
 return renderListSection('cols', '📖 合集', pickList('cols'), renderColRow);
}

function renderAuthors() {
 const currentFilter = Store.getUI('currentFilter');
 if(currentFilter !== 'all' && currentFilter !== 'author') return '';
 if(currentFilter === 'all' && !Store.state.allType.author) return '';
 return renderListSection('authors', '✏️ 作者', pickList('authors'), renderAuthorRow);
}

function renderArticles() {
 const currentFilter = Store.getUI('currentFilter');
 if(currentFilter !== 'all' && currentFilter !== 'article') return '';
 if(currentFilter === 'all' && !Store.state.allType.article) return '';
 return renderListSection('articles', '📑 文章', pickList('articles'), renderArticleRow);
}

/* =====  主渲染 ===== */
function render() {
 const windowY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
 const containerY = container.scrollTop;
 const nodes = ensureSections();
 let anyVisible = false;

 for (let i = 0; i < SECTION_DEFS.length; i++) {
  const key = SECTION_DEFS[i][0];
  const renderFn = SECTION_DEFS[i][1];
  const html = renderFn();
  if(html === sectionHtmlCache[key]) {
   if(html) anyVisible = true;
   continue;
  }
  sectionHtmlCache[key] = html;
  const wrap = nodes[key];
  if(wrap.innerHTML !== html) wrap.innerHTML = html;
  if(html) anyVisible = true;
 }

 let emptyEl = container.querySelector('.empty');
 if(!anyVisible) {
  if(!emptyEl) {
   emptyEl = document.createElement('div');
   emptyEl.className = 'empty';
   emptyEl.textContent = '暂无内容';
   container.appendChild(emptyEl);
  }
 } else if(emptyEl && emptyEl.parentNode) {
  emptyEl.parentNode.removeChild(emptyEl);
 }

 /*同步方案*/
 // if(container.scrollTop !== containerY) container.scrollTop = containerY;
 // if(window.pageYOffset !== windowY) window.scrollTo(0, windowY);
 /* 异步方案 */
 requestAnimationFrame(() => {
  if(container.scrollTop !== containerY) container.scrollTop = containerY;
  if(window.pageYOffset !== windowY) window.scrollTo(0, windowY);
 });
}

/* =====  隐藏与状态辅助 ===== */
function shouldShow(hiddenFlag) { return Store.getUI('showHidden') ? true : !hiddenFlag; }

function isHidden(item, type) {
 if(type === 'tag') return Store.state.hiddenTags.indexOf(item) !== -1;
 if(type === 'col') return String(item.hidden) === Hidden.HIDE || item.hidden === 1;
 if(type === 'author') {
  const stateStr = String(item.hidden == null ? Hidden.SHOW : item.hidden);
  return stateStr === Hidden.HIDE || stateStr === Hidden.CLEAN;
 }
 if(type === 'article') return String(item.hidden == null ? Hidden.SHOW : item.hidden) === Hidden.HIDE;
 return false;
}

function updateRow(rowEl, item, type) {
 if(!rowEl) return;
 let fresh = item;
 if(type === 'col') fresh = findItem(Store.state.collections, c => String(c.id) === String(item.id) && c.name === item.name) || item;
 else if(type === 'article') fresh = findItem(Store.state.articles, a => a.url === item.url && a.title === item.title) || item;
 else if(type === 'author') fresh = findItem(Store.state.authors, a => String(a.blogId) === String(item.blogId)) || item;

 let isItemHidden, eyeIcon;
 if(type === 'cleandTag') {
  const disabled = Store.state.disCleandTags.indexOf(item) !== -1;
  isItemHidden = disabled;
  eyeIcon = disabled ? svg.eyeClosed : svg.eyeCleand;
 } else if(type === 'author') {
  const hiddenState = String(fresh.hidden || Hidden.SHOW);
  isItemHidden = hiddenState === Hidden.HIDE || hiddenState === Hidden.CLEAN;
  eyeIcon = hiddenState === Hidden.HIDE ? svg.eyeClosed : hiddenState === Hidden.CLEAN ? svg.eyeCleand : svg.eyeOpen;
  rowEl.dataset.hidden = hiddenState;
  rowEl.classList.toggle('cleand-author-item', hiddenState === Hidden.CLEAN);
 } else {
  isItemHidden = isHidden(fresh, type);
  eyeIcon = isItemHidden ? svg.eyeClosed : svg.eyeOpen;
 }
 rowEl.classList.toggle('hidden-item', isItemHidden);
 const eyeBtn = rowEl.querySelector('.eye-btn');
 if(eyeBtn) eyeBtn.innerHTML = eyeIcon;
 invalidateSection(
  type === 'tag' || type === 'cleandTag' ? 'tags' :
  type === 'col' ? 'cols' :
  type === 'author' ? 'authors' :
  type === 'article' ? 'articles' : null
 );
}

/* =====  隐藏切换 ===== */
function toggleItem(item, type, rowEl) {
 const opts = { render: false };
 if(type === 'tag') {
  Store.mutate('hiddenTags', list => {
   const i = list.indexOf(item);
   i === -1 ? list.push(item) : list.splice(i, 1);
   return list;
  }, opts);
 } else if(type === 'col') {
  Store.mutate('collections', list => {
   const target = list.find(x => String(x.name) === item.name && String(x.id) === String(item.id));
   if(target) target.hidden = (String(target.hidden) === Hidden.HIDE || target.hidden === 1) ? Hidden.SHOW : Hidden.HIDE;
   return list;
  }, opts);
 } else if(type === 'author') {
  Store.mutate('authors', list => {
   const target = list.find(a => String(a.blogId) === String(item.blogId));
   if(!target) return list;
   const current = String(target.hidden || Hidden.SHOW);
   target.hidden = (Store.getUI('manageMode') && Store.getUI('showHidden')) ?
    (current === Hidden.SHOW ? Hidden.HIDE : current === Hidden.HIDE ? Hidden.CLEAN : Hidden.SHOW) :
    (current === Hidden.SHOW ? Hidden.HIDE : Hidden.SHOW);
   return list;
  }, opts);
 } else if(type === 'article') {
  Store.mutate('articles', list => {
   const target = list.find(a => a.title === item.title && a.url === item.url);
   if(target) target.hidden = String(target.hidden) === Hidden.HIDE ? Hidden.SHOW : Hidden.HIDE;
   return list;
  }, opts);
 }
 updateRow(rowEl, item, type);
}

