(function() {
    const toast = document.getElementById('cardToast');

    function showToast(msg, duration = 2000) {
        if (!toast) return;
        toast.textContent = msg;
        toast.classList.add('show');
        clearTimeout(toast._timeout);
        toast._timeout = setTimeout(() => {
            toast.classList.remove('show');
        }, duration);
    }

    window.importContent = function() {
        const processedText = document.getElementById("processedText");
        const originalText = document.getElementById("copyt");
        let url = processedText.value.trim();

        if (!url) {
            const originalUrl = originalText.value.trim();
            if (!originalUrl) {
                showToast('请输入内容');
                return;
            }
            url = purifyUrl(originalUrl);
            processedText.value = url;
            if (!url) {
                showToast('无法提取有效链接');
                return;
            }
        }

        const encodedUrl = encodeURIComponent(url);

        try {
            window.location.href = 'legado://import/Source?src=' + encodedUrl;
        } catch (error) {
            showToast('导入失败: ' + error.message);
        }
    };

    window.purify = function() {
        const cpt = document.getElementById("copyt");
        const processedText = document.getElementById("processedText");
        let url = cpt.value;
        if (!url.trim()) {
            showToast('请输入内容');
            return;
        }
        url = purifyUrl(url);
        processedText.value = url;
    };

    function purifyUrl(input) {
        let url = input;
        if (url.startsWith('data:')) {
            try { url = atob(url.match(/^[^,]+,([^\s,]+)/)[1]); } catch (e) {}
        }
        if (/^[\da-z\+\/]{2,}=*$/i.test(url)) {
            try { url = atob(url); } catch (e) {}
        }
        url = url.replace(/\[[\w\u4e00-\u9fa5]+\]|#\([\w\u4e00-\u9fa5]+\)/g, '');
        const allowedChars = /[\w\-._~:\/?#\[\]@!$&'()*+,;=%]/g;
        let purified = '';
        let match;
        while ((match = allowedChars.exec(url)) !== null) purified += match[0];
        const urlMatch = purified.match(/(https?:\/\/[^\s]+)/i);
        if (urlMatch) purified = urlMatch[0];
        return purified;
    }

    window.cleart = function() {
        document.getElementById("copyt").value = '';
        document.getElementById("processedText").value = '';
        showToast('已清空');
    };

    window.copyProcessed = function() {
        const processedText = document.getElementById("processedText");
        const text = processedText.value;
        if (!text.trim()) {
            showToast('没有可复制的内容');
            return;
        }
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(() => {
                showToast('已复制');
            }).catch(() => {
                fallbackCopy(text);
            });
        } else {
            fallbackCopy(text);
        }
    };

    function fallbackCopy(text) {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.left = '-9999px';
        document.body.appendChild(ta);
        ta.select();
        try {
            document.execCommand('copy');
            showToast('已复制');
        } catch (err) {
            showToast('复制失败');
        }
        document.body.removeChild(ta);
    }
})();

