     text-align: center;
     letter-spacing: 0.03em;
     line-height: 1.4;
     user-select: none;
     padding-bottom: 4px;
 }

 /* ========== 卡片右上角轻提示（无背景，深色文字）========== */
 .card-toast {
     position: absolute;
     top: 12px;
     right: 12px;
     color: #2c3e50;            /* 深色文字 */
