}

/* 判断是否为「分类碎片」key。
   分类网址里带 ?t=1 时，legado 的 getLoginInfoMap() 会把整行当成新字段存进来
   （key = "演员A::https://...?t"）。这些碎片必须剔除，否则回写 loginInfo 时会污染数据。 */
function _fkBadKey(k) {
    k = String(k || '');
    if (!k) return true;
    if (FKEY_UIKEYS.indexOf(k) > -1) return false;
    if (k.indexOf('::') > -1) return true;
    if (k.indexOf('/') > -1) return true;
    if (k.indexOf('?') > -1 || k.indexOf('&') > -1) return true;
    if (k.indexOf('.') > -1) return true;
    if (k.indexOf('=') > -1) return true;
    return false;
}

/* 读「自定义分类」原文：loginInfo 与源变量 fkey 两路，取「能解析出更多条目」的那份。
   注意不能简单取更长的——归一化后两条内容常常重复，取更长会得到重复来源。 */
function fkeyRaw() {
    var a = '';
    try { a = _fkVal(uinfo()[FKEY_NAME]); } catch (e) { a = ''; }
    var b = '';
    var src = _fkSrc();
    if (src) { try { b = _fkVal(src.get('fkey')); } catch (e2) { b = ''; } }
    if (!String(a).trim()) return b;
    if (!String(b).trim()) return a;
    try { return (fkeyCount(b) > fkeyCount(a)) ? b : a; } catch (e3) { return a; }
}

/* 归一化成「单条一行、用 ; 分隔」的单行串 */
function fkeyNorm(raw) {
    raw = (raw || '') + '';
    if (raw == 'undefined' || raw == 'null') raw = '';
    if (!String(raw).trim()) return '';
    var items = String(raw).split(/[\r\n,，;；|]+/);
    var out = [];
    for (var i = 0; i < items.length; i++) {
        var t = String(items[i] || '').replace(/^[\s"'“”`]+|[\s"'“”`]+$/g, '');
        if (t) out.push(t);
    }
    if (out.length < 2 && /\s/.test(raw)) {
        var t2 = String(raw).trim().split(/\s+/);
        var o2 = [];
        for (var j = 0; j < t2.length; j++) if (t2[j]) o2.push(t2[j]);
        if (o2.length > out.length) out = o2;
    }
    return out.join(';');
}

function _fkNameOf(url, i) {
    var seg = String(url).replace(/\/+$/, '').split('/').pop();
    if (!seg || /^(?:page|\d+)(?:\.html)?$/i.test(seg)) {
        var tmp = String(url).replace(/\/+$/, '').split('/');
        seg = tmp.length > 1 ? tmp[tmp.length - 2] : '';
    }
    seg = String(seg || '').replace(/\.html$/i, '');
    try { seg = decodeURIComponent(seg); } catch (e) {}
    return seg || ('分类' + (i + 1));
}

/* 把原始文本切成条目列表（不生成最终 URL） */
function fkeyItems(raw) {
    raw = (raw || '') + '';
    if (raw == 'undefined' || raw == 'null') raw = '';
    if (!String(raw).trim()) return [];
    var items = String(raw).split(/[\r\n,，;；|]+/);
    var list = [];
    for (var i = 0; i < items.length; i++) {
        var t = String(items[i] || '').replace(/^[\s"'“”`]+|[\s"'“”`]+$/g, '');
        if (t) list.push(t);
    }
    if (list.length < 2 && /\s/.test(raw)) {
        var t2 = String(raw).trim().split(/\s+/);
        var l2 = [];
        for (var j = 0; j < t2.length; j++) if (t2[j]) l2.push(t2[j]);
        if (l2.length > list.length) list = l2;
    }
    var out = [];
    for (var n = 0; n < list.length; n++) {
        var item = list[n];
        var name = '', url = '';
        var p = item.indexOf('::');
        if (p > -1) { name = item.substring(0, p).trim(); url = item.substring(p + 2).trim(); }
        else { url = item; }
        if (!/[\/\.]/.test(url)) continue;                       // 纯文字碎片，丢弃
        url = url.replace(/^\s*(?:https?:)?\/\/[^\/]+/i, '').replace(/\s+/g, '');
        if (!url) continue;
        if (url.charAt(0) != '/') url = '/' + url;
        var q = '';
        var qi = url.indexOf('?');
        if (qi > -1) { q = url.substring(qi + 1); url = url.substring(0, qi); }
        if (!name) name = _fkNameOf(url, n);
        name = String(name).replace(/[:：\r\n]/g, '').trim() || ('分类' + (n + 1));
        out.push({ name: name, url: url, q: q });
