];
const _NL = String.fromCharCode(10);

function _abs(base, p) {
    p = String(p == null ? '' : p);
    if (!p) return p;
    if (p.indexOf('http:') === 0 || p.indexOf('https:') === 0) return p;
    try { return new URL(p, base).href; } catch (e) {}
    while (p.charAt(0) === '/') p = p.substring(1);
