        sc.src = src;
        sc.onload = function () { if (!done) { done = true; clearTimeout(t); res(); } };
        sc.onerror = function () { if (!done) { done = true; clearTimeout(t); rej(new Error('加载失败')); } };
        document.head.appendChild(sc);
    });
}
async function _loadHls() {
    var errs = [];
    for (var i = 0; i < HLS_CDN.length; i++) {
        try {
            await _loadJs(HLS_CDN[i]);
            if (typeof Hls !== 'undefined') return { ok: HLS_CDN[i], errs: errs };
            errs.push(HLS_CDN[i] + ':已加载但无 Hls');
        } catch (e) { errs.push(HLS_CDN[i].replace('https://', '') + ':' + e.message); }
    }
