/* 把清单里的相对地址（含 AES key 的 URI）全部改写成绝对地址。
   实测 EXT-X-KEY 的 URI 是相对的 aavv.vv，不改的话喂 blob: 后 hls.js 解析不到，会 fragLoadError。 */
async function _absPlaylist(mu) {
    var r = await fetch(mu);
    if (!r.ok) throw new Error('清单 HTTP ' + r.status + '（无 Referer 时 CDN 返回 404）');
    var txt = await r.text();
    return txt.split(_NL).map(function (line) {
        var t = line.trim();
        if (!t) return line;
        if (t.charAt(0) === '#') {
            var k = t.indexOf('URI=');
            if (k < 0) return line;
            var q1 = t.indexOf(String.fromCharCode(34), k);
            var q2 = q1 < 0 ? -1 : t.indexOf(String.fromCharCode(34), q1 + 1);
            if (q1 < 0 || q2 <= q1) return line;
            return t.substring(0, q1 + 1) + _abs(mu, t.substring(q1 + 1, q2)) + t.substring(q2);
        }
        return _abs(mu, t);
    }).join(_NL);
