const HISTORY_KEY = 'searchHistory';
const MAX_HISTORY_ITEMS = 10;
        const ss = document.getElementById('ss');
        const historyList = document.getElementById('historyList');
        const clearHistoryBtn = document.getElementById('clearHistory');
        const searchInput = document.getElementById('searchkey');
        function performSearch(keyword) {
            if (!(keyword.length>1)) return;
            addHistoryItem(keyword);
            searchInput.value="";
            java.open("sort", JSON.stringify({ [keyword]: `data:;base64,{{java.base64Encode("/zh/fc_search/all"+"/${keyword}/"+page+".html")}},{"type":"18av"}` }));
        }
        
        ss.addEventListener('submit', function (event) {
            event.preventDefault();
            const formData = new FormData(ss);
            const key = formData.get('key');
            if (key) {
            	performSearch(key);
           } else {
           	searchInput.placeholder = "输入关键词，亲";
           searchInput.focus();}
        });
//const tt = new Intl.DateTimeFormat('zh-CN', {year: 'numeric', month: '2-digit', day: '2-digit'}).format(new Date()).replace(/\//g, '-');
const fl = {
	"中文字幕":`data:;base64,{{java.base64Encode("/zh/chinese_list/all/"+page+".html")}},{"type":"18av"}`,
		"高清无码":`data:;base64,{{java.base64Encode("/zh/uncensored_list/all/"+page+".html")}},{"type":"18av"}`,
			"随机近作":`data:;base64,{{java.base64Encode("/zh/chinese_random/all/index.html?t="+page)}},{"type":"18av"}`,
				"随机所有":`data:;base64,{{java.base64Encode("/zh/chinese_randomall/all/index.html?t="+page)}},{"type":"18av"}`,
					"国产自拍":`data:;base64,{{java.base64Encode("/zh/dt_list/all/"+page+".html")}},{"type":"18av"}`,
					"每日更新":`data:;base64,{{java.base64Encode("/zh/content_news/all/"+tkey()+".html")}},{"type":"18av"}`,
					"动画动漫":`data:;base64,{{java.base64Encode("/zh/animation_list/all/"+page+".html")}},{"type":"18av"}`,
					"随机动漫":`data:;base64,{{java.base64Encode("/zh/animation_random/all/index.html?t="+page)}},{"type":"18av"}`
	}
        function ff(n) {
        	if (n=='自选分类') {
        		(async () => {
        			const fkey = await window.run("uinfo()['自定义分类']");
        			let obj = {};
        			if (fkey.length>9) {
        			fkey.trim().split(/\s+/).forEach(x=> {
        			let [y1,y2] = x.split('::');
        			obj[y1]=`data:;base64,{{java.base64Encode("${y2.replace(/\d+\.html$/,'"+page+".html"')})}},{"type":"18av"}`});
        		java.open("sort", JSON.stringify(obj));
        		} else alert("请在登录界面填写自定义分类")
})();
        		return
        		}
        	let url = fl[n];
        	if (url) java.open("sort", JSON.stringify({ [n]: url}));
        	}

        ss.style.animation = `fadeIn 0.6s ease-out forwards`;
        document.querySelectorAll('#fl > div').forEach((child, index) => {
            child.style.animation = `fadeIn ${0.8 + index * 0.3}s ease-out forwards`;
        });

function loadHistory() {
 return JSON.parse(localStorage.getItem(HISTORY_KEY)) || [];
}
function saveHistory(history) {
localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
}
function addHistoryItem(keyword) {
            let history = loadHistory();
            history = history.filter(item => item !== keyword);
            history.unshift(keyword);
            if (history.length > MAX_HISTORY_ITEMS) {
                history = history.slice(0, MAX_HISTORY_ITEMS);
            }
            saveHistory(history);
            renderHistory();
        }
function removeHistoryItem(keyword) {
            let history = loadHistory();
            history = history.filter(item => item !== keyword);
            saveHistory(history);
            renderHistory();
        }
function clearHistory() {
            if (confirm('确定要清除所有搜索历史吗？')) {
                localStorage.removeItem(HISTORY_KEY);
                renderHistory();
            }
        }
// 显示历史
        function renderHistory() {
            const history = loadHistory();
            historyList.innerHTML = '';
            if (history.length === 0) {
                historyList.innerHTML = '<div class="no-history">暂无搜索历史</div>';
                return;
            }

            history.forEach(keyword => {
                const item = document.createElement('div');
                item.className = 'history-item';
                item.innerHTML = `${keyword}<span class="fa-times" data-keyword="${keyword}">🗑️</span>`;
                historyList.appendChild(item);

                // 点击搜索
                item.addEventListener('click', (e) => {
                    if (!e.target.classList.contains('fa-times')) {
                        searchInput.value = keyword;
                        performSearch(keyword);
                    }
                });

                // 处理删除按钮
                const deleteBtn = item.querySelector('.fa-times');
                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    removeHistoryItem(keyword);
                });
            });
        }

clearHistoryBtn.addEventListener('click',clearHistory);        
renderHistory();

