@js:
(function(){
try{

function wnEsc(t){return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function isWebnoteUrl(u){u=String(u||'');return /webnote\.cc/p/[A-Za-z0-9]+/i.test(u);}
function webnotePage(src,url){
  var u=String(url||''),sm=String(src||''),m=u.match(/webnote\.cc/p/([A-Za-z0-9]+)(?:@([^?#/]*))?/i);
  if(!m)m=sm.match(/webnote\.cc/p/([A-Za-z0-9]+)(?:@([^?#/]*))?/i);
  var id='',pwd='';
  if(m){id=m[1]||'';try{pwd=decodeURIComponent(m[2]||'')}catch(e){pwd=m[2]||''}}
  if(!id){return '<div class="card post"><h2 class="tt">云便签</h2><div class="msg">无法识别的便签地址</div></div>';}
  /* 1) rhino 端 java.ajax 预取(网络栈可用则直接内嵌正文) */
  var preTxt='';
  try{
    if(typeof java!=='undefined'&&java&&typeof java.ajax==='function'){
      var api='https://api-webnote.txttool.cn/netcut/note/info/';
      var apiBody='note_id='+id+'&note_pwd='+encodeURIComponent(pwd);
      var jr=java.ajax(api,{method:'POST',body:apiBody,headers:{
        'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',
        'Origin':'https://webnote.cc','Referer':u,
        'Accept':'application/json, text/javascript, */*; q=0.01',
        'X-Requested-With':'XMLHttpRequest'}});
      var jo=(typeof jr==='string')?JSON.parse(jr):jr;
      if(jo&&jo.status===1&&jo.data)preTxt=jo.data.note_content||'';
    }
  }catch(e){preTxt='';}
  /* 把 note_content([{title,content}]) 拼成 主楼层标题+正文 */
  function blocksToHtml(txt){
    try{
      var arr=JSON.parse(txt||'[]'),tt='',cc='',i;
      for(i=0;i<arr.length;i++){if(i===0)tt=arr[i].title||'';if(arr[i].content)cc+=(cc?'

':'')+arr[i].content;}
      return '<h2 class="tt">'+wnEsc(tt)+'</h2><div class="msg">'+wnEsc(cc)+'</div>';
    }catch(e){return '';}
  }
  var pbody=preTxt?blocksToHtml(preTxt):'';
  var css=':root{--bg:#F4F5F9;--postbg:#FFFFFF;--posttx:#2B2D42;--postbdw:1px;--postbdc:#E4E7F0;--postsh:none;--rd:14px;--fs:15px;--lh:1.65;--gap:8px;--tttx:#1F2430;--ttfs:20px;--ttfw:700;--ttlh:1.35;--ttgap:8px;--msggapt:8px;--metatx:#8A8FA8}';
  var html='<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    +'<style>'+css+'html,body{margin:0;background:var(--bg);color:var(--posttx);font-family:-apple-system,"PingFang SC","Microsoft YaHei",Roboto,sans-serif;font-size:var(--fs);line-height:var(--lh)}'
