.dec-prev img,.frdec-prev img{transform-origin:50% 50%;-webkit-user-drag:none;will-change:transform}
.zbar{display:flex;align-items:center;gap:8px;margin:10px 0 2px;font-size:12px;color:var(--metatx)}
.zbar input[type=range]{flex:1;min-width:0}
.zbar b{min-width:40px;text-align:right;color:#4A6CF7}
.zbar button{padding:3px 9px;font-size:12px;border:1px solid var(--bd);border-radius:6px;background:var(--chip);color:var(--btntx);cursor:pointer;flex:none}
.zbar button:active{opacity:.7}
.dec-tol{display:flex;align-items:center;gap:8px;margin:12px 0 6px;font-size:13px}
.dec-tol input[type=range]{flex:1}
.dec-tol b{min-width:28px;text-align:right;color:#4A6CF7}
.dec-btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.dec-btns .bt{flex:1;min-width:78px}
.imp-ic{display:inline-block;margin-left:8px;padding:3px 10px;font-size:12px;font-weight:600;color:#fff;background:#4A6CF7;border-radius:20px;cursor:pointer;vertical-align:middle;-webkit-user-select:none;user-select:none}
.imp-link{word-break:break-all}
.jmp-tx{word-break:break-all}
.jmp-ic{display:inline-block;margin-left:6px;padding:2px 9px;font-size:12px;font-weight:600;color:#fff;background:#4A6CF7;border-radius:20px;cursor:pointer;vertical-align:middle;-webkit-user-select:none;user-select:none}
.jmp-ic:active{opacity:.75}

/* 长按图片 = 复制链接(见 imgCopyInit), 需屏蔽系统"保存图片/识别"菜单以免两者冲突 */
.msg img,.atico,.avi,.lbox img{-webkit-touch-callout:none}
blockquote,.quote{padding:var(--qpad) 12px;margin:var(--qgapt) 0 var(--qgapb);border:var(--qbdw) solid var(--qbdc);
 border-radius:var(--qrd);font-size:var(--qfs);line-height:var(--qlh);color:var(--qtx);background:var(--qbg);
 text-shadow:var(--qsh)}
.quote blockquote{padding:0;margin:0;border:none;background:transparent;border-radius:0;font-size:inherit;line-height:inherit;color:inherit}
/* 论坛引用内常含 <font color=.. size=..> 与 <a>, 这些表现属性的优先级高于继承值,
   使 --qfs/--qtx 传不进去(表现为: 仅部分引用碰巧受控, 其余不受控)。
   强制改为 inherit, 让任意来源的引用文本(含"XX 发表于"元信息行)全部受引用样式控制。 */
blockquote font,.quote font{font-size:inherit!important;color:inherit!important}
blockquote a,.quote a,blockquote a font,.quote a font{color:inherit!important;font-size:inherit!important}
/* ★ 按钮行布局: v12 原文, 逐字未改。
   .row2 是 v24 新增的类名, v12 完全没有(计数 0); v36 已把全部 class="row2" 改回 class="row",
   使 HTML 结构与 v12 完全一致。教训: 已知可用的基线不要自作聪明重写。 */
/* v12 原文(逐字未改) */
/* ★ 按钮行布局: 用 table 布局(CSS2, Android 2 起全支持)。
   为什么不用 flex/grid: 实测本 App 的 WebView 对 grid 完全无效
   (v37 把 .acts 回退成 grid 后立刻变成 3 行、按钮间距 0、边框重叠),
   而 flex 容器虽生效, gap 与 flex:1 的实测结果不稳定(表现为按钮按内容宽度收缩、
   「完成」很窄且换行)。table 布局不依赖 flex / grid / gap / flex:1 / calc() /
   :nth-child / :first-child 中的任何一个。
   ★ table-layout:fixed + 不设子项宽度: 浏览器会把所有单元格【自动均分】,
     任意个数(2/3/8 个)都天然等宽, 因此完全不需要 :nth-child 之类去按数量设宽度。
   ★ display 用 !important: .bt{display:flex} 与本选择器同为 (0,1,0) 优先级,
     且它在文件更靠后, 不加 !important 会被它覆盖(按钮变回块级各占一行)。
   ★ 间隙用 border-spacing(表格原生属性, 支持极好) 而非 gap。 */
/* ★ 按钮行布局: 用 float(CSS1)。
   为什么: 实测本 App 的 WebView ① grid 完全无效(v37 把 .acts 改回 grid 后立即
   变成 3 行、按钮间距 0、边框重叠); ② 更关键的是【button 元素的布局支持有缺陷】——
   试 table 布局时 .row>*{display:table-cell!important} 居然不生效, computed 仍是
   inline-block(实测 88 vs 36 不等宽)。旧 WebKit 对 button 作为 flex/table 子项
   的支持都不完整, 按钮会退回内容宽度而非参与分配。
   故改用最古老的 float, 只依赖 float / width / margin / overflow, 支持到 CSS1:
   ★ float:left 保证横排(不依赖 flex/grid/inline-block 的空白间隙问题);
   ★ width:47% 保证等宽(不依赖 flex:1);
   ★ margin:0 1% 提供间隙(不依赖 gap);
   ★ 父容器 overflow:hidden 形成 BFC 清除浮动(不用 ::after 伪元素, 兼容性更稳)。
   ★ 总宽刻意留 2%~4% 余量: 2 列 = (47+2)x2 = 98%, 3 列 = (30+2)x3 = 96%,
     避免亚像素舍入导致最后一个被挤到下一行。 */
/* v39: 面板 .mbox 是 overflow:auto(滚动条约 15px), 而按钮总宽若占满 98% 则滚动条
   一来就超宽换行 —— 实测容器 343px x 98% = 336px, 仅剩 7px 余量, 故被挤成两行;
   正文 .acts 容器 610px、总宽 96%、余量 24px, 所以不受影响(与用户观察一致)。
   v12 用的是 flex, 子项 flex:1 会【自动收缩】吸收滚动条占用的宽度, 因此不受影响 ——
   这正是 v12 在本 App 上正常的根本原因。故 .row 恢复 v12 的 flex 写法。 */
.row,.row2{display:flex;gap:8px;margin-top:9px}
.row .bt,.row2 .bt{flex:1;min-width:0}
/* 正文 3 按钮: 30%+2% = 32%, 三个 96% */
.acts{display:block;overflow:visible;margin-top:12px}
.acts:after{content:'';display:block;clear:both}
.acts>*{float:left;width:32%;margin:0 1% 0 0;-webkit-box-sizing:border-box;box-sizing:border-box}

/* v40 兜底: 本 App 会往【可见】的按钮行注入 <font color="" size=""> 包裹层
   (诊断 [C] 实测: <font color="" size=""><button>恢复全部默认</button><button>完成</button></font>)。
   后果: font 成为 .row 的 flex item -> 被 blockify 成 block, 且自身不是 flex 容器,
   按钮的 flex:1(.row .bt 是后代选择器, 照样命中)无处生效 -> 退回内容宽度(实测 36px)。
   为何只有一行异常: 注入只作用于可见元素, 折叠分区(display:none)内的 15 个 .row 均未受影响,
   唯独底部这行在 endsec() 之后、始终可见 -> 中招。
   对策: 让 font 自身成为 flex 容器并 flex:1 撑满整行, 内部按钮继续按 .row .bt{flex:1} 等分。
   font 不存在时本规则不匹配, 行为与之前完全一致。 */
.row>font,.row2>font{display:flex;gap:8px;flex:1;min-width:0}
.acts>font{float:left;width:96%;overflow:visible}
.acts>font:after{content:'';display:block;clear:both}
.acts>font>*{float:left;width:32%;margin:0 1% 0 0;-webkit-box-sizing:border-box;box-sizing:border-box}
.bt{display:flex;align-items:center;justify-content:center;gap:4px;line-height:1;padding:var(--btnpad) 4px;
 border:var(--btnbdw) solid var(--btnbdc);border-radius:var(--btnrd);background:var(--btnbg);
 color:var(--btntx);font-size:var(--btnfs);font-weight:600;cursor:pointer;box-shadow:var(--btnsh);overflow:hidden}
.bt.pri{background-color:var(--pk);color:#fff}
/* v48: 「还原/清除」类操作要一眼可见 —— .bt 默认底色太淡, 实测看不出是个按钮 */
.bt.warn{background:#FFF1F0;color:#D4380D;border-color:#FFA39E}
.bt.warn:active{opacity:.7}
.bt:active{opacity:.7}
.tools{display:flex;gap:7px;margin-top:9px;flex-wrap:wrap;align-items:center}
.tb{padding:6px 12px;border:var(--btnbdw) solid var(--btnbdc);border-radius:calc(var(--btnrd) - 1px);
 background:var(--btnbg);
 color:var(--btntx);font-size:calc(var(--btnfs) - 1px);cursor:pointer;box-shadow:var(--btnsh)}
.tb:active{opacity:.6}
.tb.off{opacity:.4}
/* 激活态: 「正序/倒序」与「看全部」时高亮, 提示当前处于该视图且可再点一次切回 */
.tb.on{background:var(--pk);color:#fff;border-color:var(--pk)}
.ed{padding:5px 13px;border:var(--edbdw) solid var(--edbdc);border-radius:var(--edrd);
 background:var(--edbg);color:var(--edtx);font-size:var(--edfs);font-weight:600;cursor:pointer}
.ed:active{opacity:.7}
.rtt{font-size:13px;font-weight:600;padding:4px 4px 8px}
/* v54 点评框: 底色/不透明度/边框/圆角/内边距/阴影 与 点评者名·时间·内容 三段字体 全部由外观设置下发 */
.cmt{margin-top:var(--cmtgap);padding:var(--cmtpad);border:var(--cmtbdw) solid var(--cmtbdc);
 border-radius:var(--cmtrd);background:var(--cmtbg);color:var(--cmttx);
 font-size:var(--cmtfs);line-height:var(--cmtlh);box-shadow:var(--cmtsh)}
.cmt b{color:var(--cmtntx);margin-right:5px;font-weight:600}
.cmt i{font-style:normal;font-size:calc(var(--cmtfs) - 1px);color:var(--cmtttx);margin-right:5px}
.cmt .ct{margin-top:3px;color:var(--cmtctx);font-size:var(--cmtcfs);line-height:var(--cmtclh)}
.pgbar{display:flex;align-items:center;justify-content:center;gap:9px;margin:12px 0 8px}
/* ★ 分页栏内的「上一页/下一页」用 .pgbar .tb 作用域覆盖, 不改全局 .tb,
     否则会连带改掉工具栏的「倒序/只看楼主/重载」三个按钮。 */
.pgbar .tb{background:var(--pgbg);color:var(--pgtx);
 border:var(--pgbdw) solid var(--pgbdc);border-radius:var(--pgrd);font-size:var(--pgfs)}
/* 页码: 中间页数文本可点击 -> 弹出下拉选择页码
   ★ color 必须 !important: 该按钮带 .meta 类, 而 .meta 用 !important 强制了颜色。 */
.pnum{display:inline-flex;align-items:center;gap:4px;padding:6px 11px;margin:0;
 border:var(--pgbdw) solid var(--pgbdc);border-radius:var(--pgrd);
 background:var(--pgbg);color:var(--pgtx)!important;font-size:var(--pgfs);font-weight:600;
 cursor:pointer;box-shadow:var(--btnsh)}
.pnum:active{opacity:.6}
.pcar{font-style:normal;font-size:10px;opacity:.65}
/* 页码下拉选择框 */
/* 页码格子: 同样不依赖 flex(.pw 是 div, flex 失效时会退化成各占一整行) */
/* 页码格子: 5 列。v12 的 .pregrid 即 grid 且实测正常, 故同样用 grid, 不再自创 inline-block */
.pggrid{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:10px 0 4px}
.pgn{box-sizing:border-box;padding:9px 0;border:var(--pgbdw) solid var(--pgbdc);border-radius:var(--pgrd);
 background:var(--pgbg);color:var(--pgtx);font-size:var(--pgfs);font-weight:600;
 cursor:pointer;box-shadow:var(--btnsh)}
.pgn.on{background:var(--pgonbg);color:var(--pgontx);border-color:var(--pgonbg)}
.pgn:active{opacity:.6}
.pginput{width:100%!important;margin-top:6px!important;padding:11px!important;font-size:15px!important}
.dock{position:sticky;bottom:0;z-index:60;display:flex;gap:8px;align-items:center;padding:9px 10px;
 margin:10px -10px -10px;background:var(--dbg);border-top:var(--dbdw) solid var(--dbdc);border-radius:var(--drd) var(--drd) 0 0}
.slot{flex:1;padding:9px 14px;border:1px solid var(--bd);border-radius:18px;background:var(--chip);font-size:13px;color:#2B2D42;outline:none}
.slot:focus{border-color:var(--pk)}
.send{padding:9px 16px;border:none;border-radius:18px;background:var(--pk);color:#fff;font-size:13px;font-weight:600;cursor:pointer}
.send:active{opacity:.7}
.menu{position:absolute;right:10px;top:44px;background:#fff;border:1px solid var(--bd);border-radius:10px;padding:4px 0;z-index:20;min-width:120px}
.menu button{display:block;width:100%;text-align:left;padding:9px 14px;background:none;border:none;font-size:13px;color:#4E5364;cursor:pointer}
.menu button:active{background:var(--chip)}
.modal{display:none;position:fixed;left:0;top:0;right:0;bottom:0;background:rgba(43,45,66,.45);z-index:99;align-items:center;justify-content:center;padding:16px}
.modal.on{display:flex}
.mbox{width:100%;max-width:390px;max-height:90vh;overflow:auto;padding:16px;border-radius:14px;background:var(--mbg);color:var(--mtx)}
.mbox h3{font-size:16px;margin-bottom:10px;color:#2B2D42}
.mbox h4{font-size:12px;font-weight:600;color:#5A5F73;margin:12px 0 6px}
.mbox input[type=text]{width:100%;padding:9px 11px;border:1px solid var(--bd);border-radius:10px;background:var(--chip);font-size:13px;color:#2B2D42;outline:none;margin-top:6px}
.mbox textarea{width:100%;padding:10px;border:1px solid var(--bd);border-radius:10px;background:var(--chip);font-size:13px;resize:vertical;outline:none;color:#2B2D42}
.hint{font-size:var(--hintfs);color:var(--hinttx);margin:7px 0;line-height:var(--hintlh);letter-spacing:var(--hintls);text-shadow:var(--hintsh)}
/* ★ 按钮行一律用 flex-wrap(不用 grid): 
   1) 兼容性: 部分阅读 App(尤其修改版/旧版)的 WebView 不支持 display:grid,
      一旦失效容器退化成 block, 配合 .bt{width:100%} 会让每个按钮各占满一整行 -> 上下堆叠。
   2) 自动流动: flex:1 1 auto 让按钮按内容宽度比例分配同一行剩余空间,
      短按钮(如"完成")不会被强行拉成半行而在右侧留出大片空白;
      一行挤不下时自动换行, 不会溢出行宽。 */
/* 折叠分区 */
.sec{border:1px solid var(--bd);border-radius:11px;margin-bottom:9px;overflow:hidden}
.sech{display:flex;align-items:center;justify-content:space-between;padding:10px 12px;background:var(--sechbg);cursor:pointer}
.sech b{font-size:13px;color:var(--hdtx)}
.sech span{font-size:13px;color:var(--sub)}
.secb{padding:10px 12px}
/* 附件(非图片: txt/pdf/epub/json/zip…): 图标+文件名+大小/下载次数, 点击下载 */
.atts{display:flex;flex-direction:column;gap:7px;margin:10px 0 2px}
.att{display:flex;align-items:center;gap:10px;padding:9px 11px;
 border:var(--btnbdw) solid var(--btnbdc);border-radius:var(--rd);
 background:var(--chip);color:var(--btntx);text-decoration:none;box-shadow:var(--btnsh)}
.att:active{opacity:.7}
.atico{width:26px;height:26px;flex:none;object-fit:contain;border-radius:5px;
 background:var(--mbg);display:flex;align-items:center;justify-content:center;font-size:16px}
.atinfo{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}
.atnm{font-size:13px;font-weight:600;color:var(--mtx);
 overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.atmeta{font-size:11px;color:var(--sub)}
.atdl{flex:none;font-size:15px;color:var(--pk);opacity:.85}
/* 分类 */
.catadd{display:flex;gap:6px;margin:6px 0}
.catadd input{flex:1;margin-top:0!important}
.cat{margin:8px 0;border:1px solid var(--bd);border-radius:9px;overflow:hidden}
.cath{display:flex;align-items:center;gap:7px;padding:7px 10px;background:var(--catbg);cursor:pointer}
.cath b{font-size:12px;color:var(--hdtx);flex:1}
.cnt{font-size:11px;color:var(--sub)}
.cdel{margin-left:6px;padding:2px 8px;border:1px solid var(--bd);border-radius:6px;background:#fff;color:#E5484D;font-size:11px;cursor:pointer}
.arw{cursor:pointer;font-size:12px}
/* v12 原样 */
.pregrid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;padding:8px}
.pw{position:relative;aspect-ratio:1;box-sizing:border-box;border:2px solid var(--bd);border-radius:9px;overflow:hidden;background:var(--chip)}
.pw.sel{border-color:var(--pk)}
.pv{width:100%;height:100%;object-fit:cover;cursor:pointer;display:block;-webkit-touch-callout:none}
.del{position:absolute;right:0;top:0;width:20px;height:20px;border:none;background:var(--pk);color:#fff;font-size:13px;line-height:1;cursor:pointer;border-radius:0 0 0 6px}
.fprev{display:flex;align-items:center;gap:10px;margin:9px 0;padding:9px;border:1px dashed var(--bd);border-radius:10px;background:var(--chip)}
.fprev span{font-size:11px;color:var(--sub);flex:none}
#fabPrev{background-repeat:no-repeat;display:flex;align-items:center;justify-content:center;font-size:19px;flex:none;overflow:hidden;border:1px solid var(--bd)}
#fabPrevEmo{font-weight:400}
.msw{padding:6px 11px;border:1px solid var(--bd);border-radius:9px;background:#fff;color:#5A5F73;font-size:12px;cursor:pointer;flex:1}
.msw.on{background:var(--pk);color:#fff;border-color:var(--pk)}
/* v58 选中问 AI */
.aisel{position:absolute;z-index:9999;padding:7px 12px;font-size:13px;cursor:pointer;
 border:1px solid var(--dbdc);border-radius:16px;background:var(--mbg);color:var(--tx);
 box-shadow:0 2px 10px rgba(0,0,0,.25)}
.aiq{max-height:22vh;overflow:auto;padding:8px 10px;margin-bottom:8px;
 border-left:3px solid var(--pk);background:var(--sechbg);color:var(--sub);font-size:13px}
.aia{max-height:46vh;overflow:auto;font-size:14px;line-height:1.7}
.aia.wait{color:var(--sub)}
.aia.err{color:#e33}
.aia pre{overflow:auto;padding:8px;border-radius:6px;background:var(--sechbg)}
.aia code{padding:1px 4px;border-radius:4px;background:var(--sechbg);font-size:13px}
.aia h3,.aia h4{margin:8px 0 4px}
.aia li{margin-left:16px}
.srow{display:flex;align-items:center;gap:8px;margin:8px 0}
.srow label{font-size:12px;color:var(--lbtx);width:78px;flex:none}
.srow input[type=range]{flex:1;min-width:0}
.srow input[type=color]{width:36px;height:26px;border:1px solid var(--bd);border-radius:7px;padding:0;background:none;cursor:pointer}
/* PS 风格取色器 */
.cpk{display:flex;align-items:center;gap:8px;padding:5px 10px;border:1px solid var(--bd);border-radius:9px;background:#fff;cursor:pointer;flex:1;min-width:0}
.cpk:active{opacity:.7}
.csw{width:24px;height:24px;border-radius:6px;border:1px solid var(--bd);flex:none;display:block;background:#fff}
.chex{font-size:11px;color:var(--lbtx);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#cp{z-index:150}
.cprev{display:flex;gap:12px;margin-bottom:12px}
.cpv{flex:1;text-align:center}
.cpv i{display:block;height:42px;border-radius:10px;border:1px solid var(--bd)}
.cpv span{font-size:11px;color:var(--sub)}
.svbox{position:relative;width:100%;height:175px;border-radius:11px;border:1px solid var(--bd);cursor:crosshair;margin-bottom:12px;touch-action:none;overflow:hidden}
.svcur{position:absolute;width:17px;height:17px;border-radius:50%;border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.5);transform:translate(-50%,-50%);pointer-events:none}
.huebar{position:relative;width:100%;height:20px;border-radius:10px;border:1px solid var(--bd);margin-bottom:12px;cursor:pointer;touch-action:none;
 background:linear-gradient(to right,#f00 0%,#ff0 17%,#0f0 33%,#0ff 50%,#00f 67%,#f0f 83%,#f00 100%)}
.huecur{position:absolute;top:50%;width:15px;height:24px;border-radius:5px;border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.5);transform:translate(-50%,-50%);pointer-events:none}
.rgbrow{display:flex;align-items:center;gap:6px;margin:7px 0}
.rgbrow label{font-size:12px;color:var(--lbtx);width:28px;flex:none}
.rgbrow input{flex:1;min-width:0;padding:7px 9px;border:1px solid var(--bd);border-radius:8px;background:#fff;font-size:12px;color:#2B2D42;outline:none}
/* 颜色预设: 8 列, 与 v12 的 grid 风格一致 */
