    var d=s.match(/<p class="mtxt">([\s\S]*?)<\/p>/);
    return d?d[1].replace(/<[^>]*>/g,'').trim():'';
  }
  var o=[];
  var u=s.match(/class="mmc"[^>]*>([\s\S]*?)<\/a>/);
  if(u)o.push(u[1].replace(/<[^>]*>/g,'').trim());
  var m=s.match(/<span class="mtime">([\s\S]*?)<\/span>/);
  if(m)o.push(m[1].replace(/<[^>]*>/g,'').trim());
  var f=s.match(/<div class="threadlist_foot cl">([\s\S]*?)<\/div>/);
  if(f){
    var r=/<\/i>(\d+)<\/li>/g,x,v=[];
    while((x=r.exec(f[1])))v.push(x[1]);
    if(v[0])o.push('\ud83d\udc41'+v[0]);
    if(v[1])o.push('\ud83d\udcac'+v[1]);
  }
  /* v52: 最后发表作者+时间(电脑版独有, 由 ruleArticles 预先合并进 data-last) */
