shouldOverrideUrlLoading:
(function(){
  try{
    var u=String(url||'');
    var m1=u.indexOf('mod=viewthread')>=0,m2=u.indexOf('mod=forumdisplay')>=0;
    /* 双保险：接管原生 Discuz 编辑页，自建可提交编辑 UI，避免标题缺失触发“请输入标题或内容” */
    if(u.indexOf('mod=post')>=0 && u.indexOf('action=edit')>=0){
      if(typeof java!=='undefined'&&java&&typeof java.open==='function'){ java.open('rss',u); return true; }
      return false;
    }
    /* webnote.cc 加密便签(/p/<id>@<pwd>) -> 走书源详情页渲染, 由 ruleContent 特判取正文进主楼层 */
    if(/webnote\.cc\/p\/[A-Za-z0-9]+/i.test(u)){
      if(typeof java!=='undefined'&&java&&typeof java.open==='function'){ java.open('rss',u); return true; }
      return false;
    }
    if(m1||m2){
      /* RssJsExtensions.open() 内部有多个【静默失败】分支:
         activityRef.get() 为 null / getSource() 为 null(弱引用被回收) /
         source 不是 RssSource —— 都会直接 return@launch, 不提示也不跳转。
         若这里仍无条件 return true 拦截掉导航, 点卡片就完全没反应。
         所以先确认 java.open 可用; 不可用则放行, 让 WebView 裸跳原网页,
         至少还能看到内容, 而不是点了毫无动静。 */
      if(typeof java!=='undefined'&&java&&typeof java.open==='function'){
        java.open('rss',u);
        return true;
      }
      return false;
    }
    /* v53: 附件图片链接(mod=attachment) -> 用内置图片查看器打开, 不再裸跳原网页 */
    if(u.indexOf('mod=attachment')>=0){
      if(typeof java!=='undefined'&&java&&typeof java.showPhoto==='function'){
        java.showPhoto(u);
        return true;
      }
      return false;
    }
  }catch(e){}
  return false;
})()

