/* 按保存的 fid 顺序重排; 列表里没有的新分类追加到末尾 */
function catOrderByFids(base,fids){
  var byFid={},i;
  for(i=0;i<base.length;i++)byFid[base[i].fid]=base[i];
  var out=[],seen={};
  for(i=0;i<fids.length;i++){var f=fids[i];if(byFid[f]&&!seen[f]){out.push(byFid[f]);seen[f]=1;}}
  for(i=0;i<base.length;i++){if(!seen[base[i].fid])out.push(base[i]);}
  return out;
}
/* 默认顺序: 应用(fid=10) 紧挨在 求书(fid=3) 之后 */
function catDefaultOrderOf(base){
  var list=base.slice(),iq=-1,ia=-1,i;
  for(i=0;i<list.length;i++){if(list[i].fid==='3')iq=i;if(list[i].fid==='10')ia=i;}
  if(iq<0||ia<0)return list;
  if(ia===iq+1)return list;
  var app=list.splice(ia,1)[0];
  var q=iq;if(ia<iq)q=iq-1;     /* 若应用原在求书之前, 移除后求书下标-1 */
  list.splice(q+1,0,app);
  return list;
}
/* 启动时解析: 有保存顺序用保存, 否则用默认(应用在求书后) */
function catResolve(){
  CATS=CATS_M.slice();
  var s=pget(KCATS);
  if(s){try{var a=JSON.parse(s);if(Array.isArray(a)&&a.length)CATS=catOrderByFids(CATS_M.slice(),a);}catch(e){}}
  else CATS=catDefaultOrderOf(CATS_M.slice());
  CATWORK=catFidOrder();
