function tx(s){return String(s==null?'':s).replace(/<[^>]*>/g,'').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/\s+/g,' ').trim();}
function ee(s){return String(s==null?'':s).replace(/&amp;/g,'&');}
function abs(u){u=ee(String(u||''));return /^https?:\/\//i.test(u)?u:(ORI+u.replace(/^\/+/,''));}
function hex2rgba(h,a){
  h=String(h||'').replace('#','');
  if(h.length===3)h=h.split('').map(function(c){return c+c;}).join('');
  var n=parseInt(h,16);if(isNaN(n))return 'transparent';
  return 'rgba('+((n>>16)&255)+','+((n>>8)&255)+','+(n&255)+','+a+')';
}
