/* ---------------- 存储: java.put 优先(随书源导出), localStorage 兜底 ---------------- */
var MEM={};
function pput(k,v){v=String(v);
  /* 两层都写: java.put 仅随书源导出用, localStorage 才是跨重进真正持久的层 */
  try{if(window.java&&window.java.put){window.java.put(k,v);}}catch(e){}
  try{localStorage.setItem(k,v);}catch(e2){}
  MEM[k]=v;}
function pget(k){
  /* 优先读 localStorage(跨重进持久); 其次 java(导出); 最后内存兜底 */
  try{var v2=localStorage.getItem(k);if(v2)return v2;}catch(e2){}
  try{if(window.java&&window.java.get){var v=window.java.get(k);if(v)return v;}}catch(e){}
  return MEM[k]||'';}
function jload(k,d){try{var s=pget(k);return s?JSON.parse(s):d;}catch(e){return d;}}
