/* v58: 半截 HTML 校验 + 自动重试。
   ★ 根因: 请求偶尔被中断(网络抖动 / CDN / WebView 超时), 拿到【半截】HTML。
     列表页里置顶帖永远排在最前面, 所以半截 HTML 解析出来往往只剩一个置顶帖 ——
     表现就是「不管点哪个分类或筛选, 都只显示同一个帖子」, 而且不报错。
     实测把正常页面截断到 15% 解析, 得到的正是 1 张卡片(置顶帖「给网站取名」)。
   ★ 判据: 正常页面一定以 </html> 收尾; 没有就是被截断了。
     >512 字符才判, 避免把 404/错误短页面也算成截断而白重试。 */
/* 半截判据(放宽松): 只要出现 </html> 或 </body> 任一闭标签就认为完整。
   只认 </html> 太严: 有些响应只到 </body>(或末尾被 CDN 截断一点点),
   会被误判成半截 -> 白白重试 3 次, 列表反而卡在「加载中」更久。 */
function isTrunc(t){
  if(!t||t.length<=512)return false;
  if(/<\/html\s*>/i.test(t))return false;
  if(/<\/body\s*>/i.test(t))return false;
  return true;
}
function fb(u,res,rej){
  fetch(u,{credentials:'include'}).then(function(r){return r.text();}).then(function(t){res(String(t||''));},rej);
}
function fetchOnce(u){
  return new Promise(function(res,rej){
    if(window.ajaxAwait){
      try{window.ajaxAwait(u).then(function(t){res(String(t||''));},function(){fb(u,res,rej);});return;}catch(e){}
    }
    /* 门户页是 loadDataWithBaseURL 加载的, 主框架 URL 形如 data:text/html;,
       而 ReadRssActivity.shouldInterceptRequest 对 data:text/html; 直接放行、
       不注入 JS_INJECTION —— 所以门户页里【没有 ajaxAwait】, 只能退回 fetch。
       但 addJavascriptInterface 注入的 java 一直可用, java.ajax 比 fetch 可靠:
       它走 APP 自己的网络栈(带 Cookie / UA), 不受页面 CORS 限制。 */
    if(typeof java!=='undefined'&&java&&typeof java.ajax==='function'){
      try{
        var jt=java.ajax(u);
        if(jt&&String(jt).length>0){res(String(jt));return;}
      }catch(e){}
    }
    fb(u,res,rej);   /* 最后才用 fetch */
  });
}
/* 最多尝试 3 次: 半截 或 直接失败 都重试; 仍不行才交回上层报错,
   不再静默把半截页面显示成「只有一帖」。 */
function getHtml(u){
  return new Promise(function(res,rej){
    var n=0;
    function go(){
      fetchOnce(u).then(function(t){
        if(isTrunc(t)&&n<2){n++;go();return;}
        res(t);
      },function(e){
        if(n<2){n++;go();return;}
        rej(e);
      });
    }
    go();
  });
}

