var LMC={};
/* ===== v63 置顶帖详情: Discuz 移动接口 JSON 透传 =====
   接口: api/mobile/index.php?version=4&module=forumdisplay&fid=X&page=N
   Variables.forum_threadlist[] 里每个主题自带:
     author / views / replies / lastposter / lastpost / message(楼主正文) / reply[](最后几条回复)
   一次请求就能补齐置顶帖需要的全部字段, 同时替代原来那次「电脑版 mobile=no」HTML 请求。 */
var TPM={},LASTPC='';
function apiUrl(u){
  u=ee(String(u||''));
  if(u.indexOf('mod=forumdisplay')<0)return '';
  var fid=(u.match(/fid=(\d+)/)||[])[1]||'';
  if(!fid)return '';
  var pg=(u.match(/[?&]page=(\d+)/)||[])[1]||'1';
  return ORI+'api/mobile/index.php?version=4&module=forumdisplay&fid='+fid+'&page='+pg;
}
function parseApi(t){
  var lm={},tp={};
  try{
    var j=JSON.parse(String(t||'{}'));
    var tl=(((j||{}).Variables||{}).forum_threadlist)||[];
    for(var i=0;i<tl.length;i++){
      var o=tl[i]||{},id=String(o.tid||'');
      if(!id)continue;
      var dd={au:tx(o.author||''),at:tx(o.dateline||''),vw:tx(o.views||''),rp:tx(o.replies||''),
              lpA:tx(o.lastposter||''),lpT:tx(o.lastpost||''),sum:tx(o.message||''),
              lastAu:'',lastTx:''};
      var r=o.reply;
      if(r&&r.length){var Lz=r[r.length-1]||{};dd.lastAu=tx(Lz.author||'');dd.lastTx=tx(Lz.message||'');}
      if(!dd.lastAu)dd.lastAu=dd.lpA;
      if(!dd.lastTx)dd.lastTx=dd.sum;
      tp[id]=dd;
      if(dd.lpA)lm[id]=dd.lpA+(dd.lpT?(' '+dd.lpT):'');
    }
  }catch(e){}
  return {lm:lm,tp:tp};
}
/* 优先走移动接口 JSON; 不是板块列表(如搜索页)或接口失败时, 退回原来的电脑版 HTML 解析 */
function fetchDesk(u){
  var pc=String(u).replace(/mobile=2/,'mobile=no');LASTPC=pc;
  if(LMC[pc]&&TPM[pc])return Promise.resolve(LMC[pc]);
  var au=apiUrl(u);
  if(au){
    /* JSON 里没有 </html>, 不能用 getHtml(会被 isTrunc 误判成半截而重试 3 次) */
    return fetchOnce(au).then(function(t){
      var r=parseApi(t),n=0,k;
      for(k in r.tp){if(r.tp.hasOwnProperty(k))n++;}
      if(!n)throw new Error('emptyApi');
      LMC[pc]=r.lm;TPM[pc]=r.tp;return r.lm;
    })['catch'](function(){return fetchDeskOld(u,pc);});
  }
  return fetchDeskOld(u,pc);
}
function fetchDeskOld(u,pc){
  return getHtml(pc).then(function(h){
    var m=parseLast(h);LMC[pc]=m;try{TPM[pc]=parseTop(h);}catch(e){TPM[pc]={};}return m;
  })['catch'](function(){return {};});
}
function parseTop(h){
  var map={},re=/<tbody id="(?:normalthread|stickthread)_(\d+)"[\s\S]*?<\/tbody>/g,m;
  while((m=re.exec(h))!==null){
    var blk=m[0],dd={},pr=blk.split(/<td class="by">/);
    if(pr.length>=2){
      var au=pr[1].match(/<cite>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/);
      if(au)dd.au=tx(au[1]);
      var at=pr[1].match(/<em>[\s\S]*?>([\s\S]*?)<\/em>/)||pr[1].match(/<em>([\s\S]*?)<\/em>/);
      if(at)dd.at=tx(at[1]);
    }
    if(pr.length>=3){
      var lz=pr[pr.length-1];
      var la=lz.match(/<cite>[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/);
      var lt=lz.match(/<em>[\s\S]*?>([\s\S]*?)<\/em>/)||lz.match(/<em>([\s\S]*?)<\/em>/);
