  if(m)return m[2]+'-'+m[3]+(m[4]?(' '+m[4]):'');
  var m2=s.match(/(\d{1,2})[-/.](\d{1,2})(?:\D+(\d{1,2}:\d{2}))?/);
  if(m2)return m2[1]+'-'+m2[2]+(m2[3]?(' '+m2[3]):'');
