/* ★ 关键: 首屏渲染完 + 空闲后, 才去取「最后发表」。
   这样既不占用首屏带宽, 也不阻塞任何已有元素的渲染与图片解码。 */
function scheduleLast(u,seq){
  /* v63: 这唯一一次请求现在同时供「最后发表」和「置顶帖详情」使用。
     关掉「最后发表」时, 只有页面上确实存在置顶卡才发, 避免白白多一个请求。 */
  if(!ST.lpOn){
    try{ if(!document.querySelector('#res .tpc'))return; }catch(e){}
  }
  defer(function(){
    if(seq!==loadSeq)return;                 /* 已被更新的请求取代 */
    fetchDesk(u).then(function(lm){
      if(seq!==loadSeq)return;
      defer(function(){
        try{if(ST.lpOn)fillLast(lm||{});}catch(e){}
        try{fillTop();}catch(e){}
      });                                    /* 回填同样让位给主线程 */
    })['catch'](function(){});
  });
}

