/* ---------------- 图片行布局: 行宽/图宽/间距 -> 一行几张 ---------------- */
function layoutImgs(){
  var gs=document.querySelectorAll('.igs');
  var ws=[],i;
  /* v56 先批量读再批量写: 原来「读-写-读-写」交替, 每个元素都触发一次强制重排 */
  for(i=0;i<gs.length;i++)ws.push(gs[i].clientWidth);
  for(i=0;i<gs.length;i++)layoutOne(gs[i],ws[i]);
}
function layoutOne(g,cw){
    if(!cw)return;
    var gap=ST.igGap,maxN=ST.igMax||9;
    var n=parseInt(g.getAttribute('data-n'),10)||0;
    if(n>maxN)n=maxN;
    /* 一行几张 = 100 ÷ 单图宽度%(33% -> 3 张, 25% -> 4 张); 再受「最多显示张数」与实际图片数限制 */
    var n0=Math.max(1,Math.round(100/(ST.igW||100)));
    var cnt=Math.min(n0,n,maxN);
    if(cnt<1)cnt=1;
    var iw=Math.floor((cw-gap*(cnt-1))/cnt);
    /* 图片不够铺满一行时按「单图宽度」左对齐, 不把少数几张拉伸成超大图 */
    var want=Math.max(20,Math.round(cw*(ST.igW||100)/100));
    if(n<n0)iw=Math.min(iw,want);
    g.style.height=ST.igRowH+'px';
    var its=g.children;
    for(var j=0;j<its.length;j++){
      if(j<cnt){its[j].style.display='';its[j].style.width=iw+'px';its[j].style.height=ST.igRowH+'px';}
      else its[j].style.display='none';
  }
}
/* ---------------- 综合信息自适应: 先缩间距, 再缩字号, 最后省略 ---------------- */
function fitOne(el){
  el.style.letterSpacing='';el.style.fontSize='';
  var avail=el.clientWidth;
  if(!avail)return;
  var base=ST.mtFs,ls=ST.mtLs,minFs=Math.min(ST.mtMinFs,base);
  el.style.fontSize=base+'px';el.style.letterSpacing=ls+'px';
  if(el.scrollWidth<=avail+1)return;
  if(!ST.mtAuto){el.style.letterSpacing='0px';return;}
  /* v56 二分代替线性递减: 原来每 0.5px 一档最坏 ~20 轮「写样式->读scrollWidth」,
     每轮都强制重排; 20 个条目就是上百次。二分后每阶段最多 4 轮。 */
  var lo,hi,mid;
  /* 阶段一: 压缩字距 */
  lo=ls;hi=-1;                       /* 假定 hi 一定放不下 */
  if(binFit(el,hi,'ls')){el.style.letterSpacing=hi+'px';return;}
  for(var k=0;k<4&&(hi-lo)>0.4;k++){
    mid=Math.round((lo+hi)/2*2)/2;   /* 取到 0.5 的倍数 */
    if(binFit(el,mid,'ls'))lo=mid; else hi=mid;
  }
  el.style.letterSpacing=lo+'px';
  if(binFit(el,lo,'ls'))return;
  /* 阶段二: 字距已到极限仍放不下, 再缩字号 */
  el.style.letterSpacing='-1px';
  lo=minFs;hi=base;                  /* 假定 hi 一定放不下 */
  for(var k2=0;k2<4&&(hi-lo)>0.4;k2++){
    var fm=Math.round((lo+hi)/2*2)/2;
    if(binFit(el,fm,'fs'))lo=fm; else hi=fm;
  }
  el.style.fontSize=lo+'px';
}
function binFit(el,v,mode){
  if(mode==='ls')el.style.letterSpacing=v+'px';
  else el.style.fontSize=v+'px';
  return el.scrollWidth<=el.clientWidth+1;
}
function fitMeta(){
  var ms=document.querySelectorAll('.mt[data-fit="1"]');
  for(var i=0;i<ms.length;i++)fitOne(ms[i]);
}
/* v58: 外框层是在渲染列表时插进 .avw 的, 但切换「启用 / 换图 / 叠放次序」时
   不该为了看效果再去重新拉一次列表 —— 直接在现有 DOM 上补齐或移除。 */
