var TODAY_MAP={};
function parseToday(h){
  var map={}, fids=[], re=/fid=(\d+)/g, m;
  while((m=re.exec(h))!==null) fids.push({fid:m[1], pos:m.index});
  var pats=[
    /<em[^>]*title="\u4eca\u65e5"[^>]*>\s*\((\d+)\)\s*<\/em>/i,
    /<span[^>]*class="mnum"[^>]*>\u4eca\u65e5\s*(\d+)/i,
