function loadUrl(u,append){
  loading=true;
  var el=document.getElementById('res');
  if(!append)showLoading('加载中…');
  else el.setAttribute('data-append','1');
  var fid=fidOf(u);
  var seq=++loadSeq;
  /* v59: 首屏只发列表这一个请求(手机版)。
     「最后发表」需要的电脑版请求推迟到本页渲染完、主线程空闲之后再发(见 scheduleLast),
     因此既不占用首屏带宽, 也不会拖慢任何已有元素的显示。 */
  var pList=getHtml(u);
  pList.then(function(h){
    if(seq!==loadSeq)return;   /* 已被更新的请求取代, 丢弃旧结果 */
    SUBS=parseSub(h);
    POSTURL=parsePost(h,fid);
    /* 二级导航当前项: 优先用页面自带的 mon 标记, 否则沿用当前索引 */
    var ai=-1;
    for(var i=0;i<SUBS.length;i++){if(SUBS[i].on){ai=i;break;}}
    if(ai>=0)curSub=ai;
    renderSubs();
    var r=parseList(h,{});
    var ann=append?'':parseAnnounce(h);
    var body=(r.count?r.html:'<div class="emp">该分类暂无帖子</div>');
    if(ann)body=ann+body;
    if(append)el.innerHTML+=body; else el.innerHTML=body;
    curNext=nextUrl(h);
    if(curNext)el.innerHTML+='<div class="pg"><a href="javascript:loadMore()">加载更多</a></div>';
    el.setAttribute('data-append','0');
    loading=false;
    lastLoadAt=(new Date()).getTime();
    relayout();
    scheduleLast(u,seq);   /* v59: 渲染完 + 空闲后, 才异步补「最后发表」 */
  })['catch'](function(e){
    if(seq!==loadSeq)return;
    loading=false;
    lastLoadAt=(new Date()).getTime();
    el.setAttribute('data-append','0');
    el.innerHTML='<div class="emp">加载失败：'+esc(e)+'</div>';
  });
}
/* 让位给首屏: 优先 requestIdleCallback; 老 WebView 没有就退化为两帧后执行 */
function defer(fn){
  try{
    if(typeof window.requestIdleCallback==='function'){window.requestIdleCallback(fn,{timeout:1500});return;}
  }catch(e){}
  setTimeout(fn,120);
}
