var LP3C={};                       /* 按 tid 缓存已加载的回复, 避免重复请求 */
function lpPt(e){if(e.touches&&e.touches[0])return{x:e.touches[0].clientX,y:e.touches[0].clientY};return{x:e.clientX||0,y:e.clientY||0};}
function lpFindCard(t){
  while(t&&t!==document){
    if(t.classList&&t.classList.contains('itw')&&t.getAttribute('data-tid'))return t;
    t=t.parentNode;
  }
  return null;
}
function lpDown(e){
  var c=lpFindCard(e.target);
  lpCard=c;lpMoved=false;
  if(!c){if(lpTimer){clearTimeout(lpTimer);lpTimer=null;}return;}
  var p=lpPt(e);lpSX=p.x;lpSY=p.y;
  if(lpTimer)clearTimeout(lpTimer);
  lpTimer=setTimeout(function(){lpFire(c);},480);
}
function lpMove(e){
  if(!lpTimer)return;
  var p=lpPt(e);
  if(Math.abs(p.x-lpSX)>10||Math.abs(p.y-lpSY)>10){clearTimeout(lpTimer);lpTimer=null;}
}
function lpUp(){if(lpTimer){clearTimeout(lpTimer);lpTimer=null;}}
function lpFire(c){
  lpTimer=null;
  c._lp=1;                                  /* 武装: 抑制随后冒出的 click 导航 */
  setTimeout(function(){if(c._lp===1)c._lp=0;},420);
  lpToggle(c);
}
function lpClick(e){
