}
function lpBtn(e,btn){
  /* 卡片右上角 ▾ 按钮: 展开/折叠最近3条回复。
     按钮在 <a class="it"> 之外, 但仍要拦住默认与冒泡, 避免误触卡片导航。 */
  if(e){if(e.preventDefault)e.preventDefault();if(e.stopPropagation)e.stopPropagation();}
  var w=btn&&btn.parentNode;
  while(w&&!(w.classList&&w.classList.contains('itw')))w=w.parentNode;
  if(!w)return;
  var on=lpToggle(w);
  if(btn)btn.className=on?'lpb on':'lpb';
