function lpToggle(c){
  var tid=c.getAttribute('data-tid');if(!tid)return false;
  /* fixed26: 回复区挂到卡片容器 .it 内部(而非外层 .itw), 使其真正显示在卡片里 */
  var host=c.querySelector('.it')||c;
  var box=c.querySelector('.lp3');
  if(box&&box.classList.contains('open')){box.classList.remove('open');box.innerHTML='';return false;}
  if(!box){
    box=document.createElement('div');box.className='lp3';
    /* box 在 <a> 内: 点它不能触发帖子导航 */
    box.onclick=function(e){if(e){if(e.preventDefault)e.preventDefault();if(e.stopPropagation)e.stopPropagation();}};
    host.appendChild(box);
  }
  box.classList.add('open');
  if(LP3C[tid]){box.innerHTML=lp3Html(LP3C[tid]);return true;}
  box.innerHTML='<div class="lp3ld">加载最近回复…</div>';
  fetchReplies(tid).then(function(arr){
    LP3C[tid]=arr;
    if(box.classList.contains('open'))box.innerHTML=lp3Html(arr);
  })['catch'](function(){
    if(box.classList.contains('open'))box.innerHTML='<div class="lp3ld">加载失败</div>';
  });
  return true;
}
function lp3Html(arr){
  if(!arr||!arr.length)return '<div class="lp3ld">暂无回复</div>';
  var h='<div class="lp3hd">最近回复</div>',i;
  for(i=0;i<arr.length;i++){
    var r=arr[i];
    h+='<div class="lp3it">'
      +'<div class="lp3au">'+esc(r.au||'')+'<span class="lp3tm">'+esc(r.tm||'')+'</span></div>'
      +'<div class="lp3tx">'+esc(r.tx||'')+'</div>'
      +'</div>';
  }
  return h;
}
function lp3Take(arr){return arr.length>3?arr.slice(0,3):arr;}
function stripQuote(s){
  return String(s||'')
    .replace(/<div class="quote">[\s\S]*?<\/div>/g,'')
    .replace(/<blockquote[\s\S]*?<\/blockquote>/g,'')
    .replace(/<ignore_js_op>[\s\S]*?<\/ignore_js_op>/g,'');
}
function snip(s,n){s=String(s||'');return s.length>n?s.slice(0,n)+'…':s;}
function balDivMatch(p,mi){
  /* 从 <div class="message"> 起, 按 <div / </div> 配平, 取到消息块的闭合 </div>
     (消息体内含 <div class="quote"> 等嵌套, 非贪婪正则会提前截止) */
  var depth=0,i=mi,n=p.length;
  while(i<n){
    if(p.substr(i,4)==='<div'){depth++;i+=4;continue;}
    if(p.substr(i,6)==='</div>'){depth--;i+=6;if(depth===0)return p.slice(mi,i);continue;}
    i++;
  }
  return p.slice(mi);
}
function parseReplies(h){
  var arr=[];
  try{
    var seg=String(h||'');
    var parts=seg.split(/<div class="plc cl" id="pid\d+">/),i;
    for(i=1;i<parts.length;i++){
      var p=parts[i];
      var cut=p.indexOf('<div class="threadlist_foot');
      if(cut>=0)p=p.slice(0,cut);
      var mt=p.match(/<li class="mtit">([\s\S]*?)<\/li>/);
      if(mt&&/楼主/.test(mt[1]))continue;          /* 跳过楼主主楼 */
      var au=p.match(/<li class="mtit">[\s\S]*?<a[^>]*>([\s\S]*?)<\/a>/);
      var tm=p.match(/<li class="mtime">([\s\S]*?)<\/li>/);
      var mi=p.indexOf('<div class="message">');
      var author=au?tx(au[1]):'';
      var time=tm?tx(tm[1]):'';
      var content=mi>=0?tx(stripQuote(balDivMatch(p,mi))):'';
      content=snip(content,80);
      arr.push({au:author,tm:time,tx:content});
    }
  }catch(e){}
  return arr;
}
function fetchReplies(tid){
  var u=ORI+'forum.php?mod=viewthread&tid='+encodeURIComponent(tid)+'&ordertype=1&mobile=2';
  return getHtml(u).then(function(h){return lp3Take(parseReplies(h));});
}
