/* v58 下拉到底自动加载下一页。
   ★ 难点: 切分类/二级导航时内容被整块替换, 页面高度骤降, 若此时滚动位置仍很深,
     会立刻命中「到底部」判定, 把新分类的第 2 页也自动加载掉。
     已有的 scrollTo(0,0) 是异步生效的, 单靠它拦不住。
   ★ 做法: 只有检测到【用户向下滑动】才解除封锁(nextArmed)。
     页面骤降只会让 scrollY 变小, 不会让它变大, 因此不会误解锁。 */
var nextArmed=false,lastY=0,nextMute=0;
function resetNext(){                            /* 切换分类/导航/搜索后调用 */
  nextArmed=false;lastY=0;nextMute=(new Date()).getTime();
}
window.addEventListener('scroll',function(){
  if(!ST.autoNext)return;                        /* 关掉则只能手动点「加载更多」 */
  if(loading||!curNext)return;
  var now=(new Date()).getTime();
  if(now-lastLoadAt<1200)return;                 /* 刚加载完的保护期, 防止连环触发 */
  if(now-nextMute<600)return;                    /* 等 scrollTo(0,0) 真正生效 */
  var y=window.pageYOffset;
  if(y>lastY+4)nextArmed=true;                   /* 只认向下滑动 */
  lastY=y;
  if(!nextArmed)return;
  var d=document.documentElement;
  if(d.scrollHeight-(y+d.clientHeight)<300)loadMore();
});
window.addEventListener('resize',function(){relayout();});
