function syncStyle(){
  for(var k in PDEF){
    var d=PDEF[k],t=d[0],id='s'+k;
    if(t==='r'){setV(id,ST[k]);sv(id,ST[k]);}
    else if(t==='c')setSw(id,ST[k]);
    else if(t==='t')setV(id,ST[k]);
    else if(t==='s')setV(id,ST[k]);
    else if(t==='b'){
      var a=document.getElementById(id+'0'),b=document.getElementById(id+'1');
      if(a)a.className='msw'+(ST[k]?'':' on');
      if(b)b.className='msw'+(ST[k]?' on':'');
    }
  }
}
