    o+='<span class="pvwrap'+((typeof PVS!="undefined"&&PVS.bg===BGL[i].u)?' pick':'')+'"><img class="pv" src="'+esc(BGL[i].u)+'" data-k="bg" onclick="try{pvSelEl(this)}catch(e){};useBG(\''+i+'\')" onerror="this.style.opacity=.25" ontouchstart="pvLP(event,this)" ontouchend="pvClr()" ontouchcancel="pvClr()" onmousedown="pvLP(event,this)" onmouseup="pvClr()" onmouseleave="pvClr()" oncontextmenu="pvCpImg(this);return false;">'
      +'<b class="pvx" onclick="delBG('+i+')">×</b></span>';
  }
  if(!o)o='<div class="hint">还没有保存过背景图。</div>';
  o+='<div class="row"><button class="bt" onclick="restoreDef(\'bg\')">↺ 恢复默认背景图</button></div>';
