function useBG(i){var it=BGL[i];if(!it)return;BG=it.u;pput(KBG,BG);applyBG();refreshPanel();tip('✔ 已应用背景图','ok');}
function delBG(i){
  if(!BGL[i])return;
  if(!confirm('确定删除这张背景图？'))return;
  if(BG===BGL[i].u){BG='';pput(KBG,'');applyBG();}
  BGL.splice(i,1);jsave(KBGL,BGL);refreshPanel();tip('✔ 已删除');
}
function addBG(){
  var v=(document.getElementById('bi')||{}).value||'';
  v=v.trim();
  if(!v){tip('✘ 请输入背景图片地址');return;}
  var u=toFile(v),sel=document.getElementById('bcat');
  var cat=sel?sel.value:'默认';
  var ex=null;
  for(var i=0;i<BGL.length;i++){if(BGL[i].u===u)ex=BGL[i];}
