/* ===== v61 头像框/背景图 云同步(webnote.cc「按名称」剪贴板) =====
   读取: POST /netcut/note/info/  note_name=<名称>
   保存: POST /netcut/note/save/  note_name & note_id & note_token & note_content
   ★ 每次保存都会生成新的 note_id/token, 追加前必须先 info 取最新 id/token。
   ★★ 通道顺序(实测结论, 别再调回去):
     1) fetch —— 接口校验 TLS 指纹, OkHttp/Java 原生指纹会被判「服务器负载过高」;
        而它 CORS 头回声 Origin(Origin:xxx -> ACAO:xxx + ACAC:true), WebView 内 fetch 可用。
     2) postAwait / ajaxAwait(url,{"method":"POST"...}) / java.ajax —— 仅作兜底。
        注意 ajaxAwait 只收 1 个参数(url), POST 要走 postAwait 或 AnalyzeUrl 的 url,{} 选项串。
     每条通道都必须返回 JSON 且 status===1 才算成功, 否则换下一条, 并透出服务端 error。 */
var WNAPI='https://api-webnote.txttool.cn/netcut/note/';
var WNNM={fr:'头像框',bg:'背景图片'};
function wnOk(t){try{var o=JSON.parse(t);return !!(o&&o.status===1&&o.data);}catch(e){return false;}}
function wnErr(t){
  try{var o=JSON.parse(t);if(o&&o.status!==1)return String(o.error||('status='+o.status));}catch(e){}
  t=String(t||'');
  return t?('响应异常: '+t.slice(0,50)):'空响应';
}
function wnChan(u,body,h){
  var c=[];
  /* 1) 浏览器内核 fetch(推荐通道) */
  c.push(function(){return new Promise(function(res,rej){
    try{fetch(u,{method:'POST',body:body,headers:h,mode:'cors',credentials:'omit'})
          .then(function(r){return r.text();})
          .then(function(t){res(String(t||''));},rej);}
    catch(e){rej(e);}
  });});
  /* 2) postAwait(url, body, headersJSON) */
  c.push(function(){return Promise.resolve(postAwait(u,body,JSON.stringify(h)))
    .then(function(a){return String(a==null?'':a);});});
  /* 3) ajaxAwait 走 Legado AnalyzeUrl 的 url,{选项} 语法做原生 POST */
  c.push(function(){return Promise.resolve(ajaxAwait(u+','+JSON.stringify({method:'POST',body:body,headers:h})))
    .then(function(a){return String(a==null?'':a);});});
  /* 4) java.ajax(url, 选项JSON) / java.ajax(url) 兜底 */
  c.push(function(){return Promise.resolve(java.ajax(u,JSON.stringify({method:'POST',body:body,headers:h})))
    .then(function(a){return String(a==null?'':a);});});
  return c;
}
function wnRun(c,i,last){
  if(i>=c.length)return Promise.reject(new Error(last||('无可用网络通道')));
  return Promise.resolve().then(function(){return c[i]();}).then(function(t){
    t=String(t==null?'':t);
    if(wnOk(t))return t;
    return wnRun(c,i+1,wnErr(t));
  },function(e){
    var m=(e&&e.message)?String(e.message).slice(0,50):'异常';
    /* 通道不可用(java/postAwait 未定义)时不要覆盖上一次的真实错误(如"服务器负载过高") */
    if(last&&/is not defined|not a function/.test(m))return wnRun(c,i+1,last);
    return wnRun(c,i+1,m);
  });
}
function wnReq(p,body){
  var u=WNAPI+p+'/';
  var h={'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',
         'X-Requested-With':'XMLHttpRequest',
         'Accept':'application/json, text/javascript, */*; q=0.01'};
  return new Promise(function(res,rej){
    var done=false,tm=null;
    try{tm=setTimeout(function(){if(done)return;done=true;rej(new Error('请求超时(20秒)'));},20000);}catch(e){}
    function fin(f,a){if(done)return;done=true;try{tm&&clearTimeout(tm);}catch(e){}f(a);}
    wnRun(wnChan(u,body,h),0,'').then(function(t){fin(res,t);},function(e){fin(rej,e);});
  });
}
function wnData(txt){
  var o=null;
  try{o=JSON.parse(txt);}catch(e){throw new Error('响应不是JSON: '+String(txt||'').slice(0,40));}
  if(o&&o.status===1&&o.data)return o.data;
  throw new Error(String((o&&o.error)||('status='+(o&&o.status))));
}
/* note_content 是 JSON 数组字符串: [{"title":..,"content":..}] -> 拼成纯文本 */
function wnText(nc){
  if(!nc)return '';
  try{
    var a=JSON.parse(nc);
    if(a&&a.length){
      var s='';
      for(var i=0;i<a.length;i++)s+=(a[i].title||'')+(a[i].content||'');
      return s;
    }
  }catch(e){}
  return String(nc);
}
function wnPack(txt){return JSON.stringify([{title:'',content:txt}]);}
/* ===== fixed34 首页更新公告 =====
