function annEsc(t){return String(t==null?'':t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function annHash(s){s=String(s||'');var h=5381,i;for(i=0;i<s.length;i++){h=(((h<<5)+h)^s.charCodeAt(i))>>>0;}return h.toString(36)+'_'+s.length;}
function annIsJson(u){return /^https?:\/\/[^\s"'<>]+\.json(\?[^#\s]*)?(#\S*)?$/i.test(u);}
function annLink(u){
