function annRender(txt){
  var raw=String(txt==null?'':txt),re=/https?:\/\/[A-Za-z0-9\-._~:\/?#\[\]@!$&'()*+,;=%]+/gi,out='',last=0,m;
  while((m=re.exec(raw))){
    var u=m[0],tail='',mt=u.match(/[.,;:!?)\]}'"]+$/);
    if(mt){tail=mt[0];u=u.slice(0,u.length-tail.length);}
    out+=annEsc(raw.slice(last,m.index))+annLink(u)+annEsc(tail);
    last=m.index+m[0].length;
  }
  return out+annEsc(raw.slice(last));
}
function annReq(){
  var u=WNAPI+'info/';
