/* 正文 -> 图片链接数组: 从任意文本里提取 http(s)/file 链接(支持紧跟中文无分隔符的情况), 并去重 */
function wnUrls(txt){
  var out=[],seen={};
  var re=/(?:https?:\/\/|file:\/\/)[^\s,，;；|、<>"'）)】\]。]+/gi;
  var m;
  while((m=re.exec(String(txt||'')))!==null){
    var u=m[0].replace(/[,，;；|、.。]+$/,'');
    if(!u)continue;
    if(seen[u])continue;
    seen[u]=1;out.push(u);
  }
  return out;
}
/* 复制文本: execCommand('copy') 优先, navigator.clipboard 兜底 */
function cpTxt(t){
  t=String(t==null?'':t);
  if(!t)return;
  try{
    var ta=document.createElement('textarea');
    ta.value=t;ta.setAttribute('readonly','');
    ta.style.position='fixed';ta.style.left='-9999px';ta.style.opacity='0';
    document.body.appendChild(ta);
    ta.focus();ta.select();
    try{ta.setSelectionRange(0,999999);}catch(e){}
    var ok=false;try{ok=document.execCommand('copy');}catch(e){}
    try{document.body.removeChild(ta);}catch(e){}
    if(ok)return;
  }catch(e){}
  try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t);}}catch(e){}
}
