/* 解包: 脏数据一律过滤; id 缺失或重复的自动补一个, 保证侧边栏 / 容器不打架 */
function mineUnpack(a){
  var out=[],seen={},i;
  for(i=0;i<(a&&a.length?a.length:0);i++){
    var o=a[i];
    if(!o||typeof o!=='object')continue;
    var id=String(o.id||'')||('m'+Date.now()+'_'+i);
    if(seen[id])continue;
    seen[id]=1;
    out.push({id:id,n:String(o.n||'')||'未命名',txt:String(o.txt==null?'':o.txt),
      k:'mine',img:o.img?1:0,btn:o.btn?1:0});
