/* ---- 取色器(HSV) ---- */
var CP={key:'',h:0,s:0,v:1,hex:'#FFFFFF'};
var CP_PRESET=['#FFFFFF','#F1F2F7','#E4E7F0','#8A8FA8','#5A5F73','#2B2D42','#000000','#FF6B9D','#E5484D','#F2A33C','#16A34A','#22A7C2','#7C6BD9','#A855F7','#FDF4DE','#C3A875'];
function h2r(hex){
  hex=String(hex||'').replace('#','');
  if(hex.length===3)hex=hex.split('').map(function(c){return c+c;}).join('');
  var n=parseInt(hex,16);
  if(isNaN(n))return {r:255,g:255,b:255};
  return {r:(n>>16)&255,g:(n>>8)&255,b:n&255};
}
function r2h(r,g,b){
  function c(x){x=Math.round(Math.min(255,Math.max(0,x))).toString(16);return x.length<2?'0'+x:x;}
  return '#'+c(r)+c(g)+c(b);
}
function rgb2hsv(r,g,b){
  r/=255;g/=255;b/=255;
  var mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn,h=0;
  if(d){
    if(mx===r)h=((g-b)/d+(g<b?6:0));
    else if(mx===g)h=((b-r)/d+2);
    else h=((r-g)/d+4);
    h*=60;
  }
  return {h:h,s:(mx?d/mx:0),v:mx};
}
function hsv2rgb(h,s,v){
  h=((h%360)+360)%360;
  var c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c,r=0,g=0,b=0;
  if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}
  else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}
  return {r:(r+m)*255,g:(g+m)*255,b:(b+m)*255};
}
function cpSync(noHex){
  var rgb=hsv2rgb(CP.h,CP.s,CP.v);
