/* ---- 悬浮按钮拖动 ---- */
var _fb=null,_fx=0,_fy=0,_fblk=0,_fmov=0;
function fabInit(){
  var f=document.getElementById('fab');
  if(!f)return;
  /* 长按拖动前先关掉一切"选中/菜单/原生拖拽", 否则会选中按钮里的图案 */
  try{
    f.style.webkitUserSelect='none';f.style.webkitTouchCallout='none';
    f.style.touchAction='none';f.style.webkitUserDrag='none';
    f.setAttribute('unselectable','on');f.setAttribute('draggable','false');
  }catch(_e){}
  function noSel(e){if(e&&e.preventDefault)e.preventDefault();return false;}
  f.addEventListener('contextmenu',noSel,false);
  f.addEventListener('selectstart',noSel,false);
  f.addEventListener('dragstart',noSel,false);
  function down(e){
    try{var _s=window.getSelection();if(_s&&_s.removeAllRanges)_s.removeAllRanges();}catch(_e){}
    var p=pt(e);_fx=p.clientX;_fy=p.clientY;_fblk=0;_fmov=0;
    if(e&&e.type==='mousedown'&&e.preventDefault)e.preventDefault();
    _fb=setTimeout(function(){_fb=null;_fblk=1;tip('拖动中，松手保存位置');},500);
  }
  function move(e){
    if(_fb){if(Math.abs(pt(e).clientX-_fx)>12||Math.abs(pt(e).clientY-_fy)>12){clearTimeout(_fb);_fb=null;}return;}
    if(!_fblk)return;
    try{var _g=window.getSelection();if(_g&&!_g.isCollapsed&&_g.removeAllRanges)_g.removeAllRanges();}catch(_e){}
    var p=pt(e);
    _fmov=1;
    ST.fabX=Math.max(0,Math.min(320,ST.fabX-(p.clientX-_fx)));
    ST.fabY=Math.max(0,Math.min(640,ST.fabY-(p.clientY-_fy)));
    _fx=p.clientX;_fy=p.clientY;
    var r=document.documentElement.style;
    r.setProperty('--fabx',Math.round(ST.fabX)+'px');
    r.setProperty('--faby',Math.round(ST.fabY)+'px');
    if(e.preventDefault)e.preventDefault();
  }
  function up(){
    if(_fb){clearTimeout(_fb);_fb=null;}
    if(_fblk&&_fmov){saveST();tip('✔ 位置已保存');}
    _fblk=0;_fmov=0;
  }
  f.addEventListener('touchstart',down,false);
  f.addEventListener('touchmove',move,false);
  f.addEventListener('touchend',up,false);
  f.addEventListener('mousedown',down,false);
  document.addEventListener('mousemove',move,false);
  document.addEventListener('mouseup',up,false);
  /* 拖动后吞掉 click, 避免松手就打开面板 */
  f.addEventListener('click',function(e){
    if(_fblk||_fmov){if(e.preventDefault)e.preventDefault();if(e.stopPropagation)e.stopPropagation();_fmov=0;}
  },true);
}

