function xsShelfUpd(it,el){
  var u=/^https?:\/\//i.test(it.u)?it.u:XS_ORI+it.u;
  xsGet(u).then(function(h){
    /* id.list@tag.dd.0@tag.a@text : #list 下首个 <dd> 内的 <a> 文本 */
    var ddM=/<div id="list"[\s\S]*?<dd>\s*<a[^>]*>([\s\S]*?)<\/a>/i.exec(h);
    var ddTxt=ddM?tx(ddM[1]):'';
