/* ---- 铃铛长按拖动定位(左上角, left/top) ---- */
var _bb=null,_bx=0,_by=0,_bblk=0,_bmov=0;
function bellInit(){
  var b=document.getElementById('bellFab');
  if(!b)return;
  try{
    b.style.webkitUserSelect='none';b.style.webkitTouchCallout='none';
    b.style.touchAction='none';b.style.webkitUserDrag='none';
    b.setAttribute('unselectable','on');b.setAttribute('draggable','false');
  }catch(_e){}
  function noSel(e){if(e&&e.preventDefault)e.preventDefault();return false;}
  b.addEventListener('contextmenu',noSel,false);
  b.addEventListener('selectstart',noSel,false);
  b.addEventListener('dragstart',noSel,false);
  function down(e){
    try{var _s=window.getSelection();if(_s&&_s.removeAllRanges)_s.removeAllRanges();}catch(_e){}
    var p=pt(e);_bx=p.clientX;_by=p.clientY;_bblk=0;_bmov=0;
    if(e&&e.type==='mousedown'&&e.preventDefault)e.preventDefault();
    _bb=setTimeout(function(){_bb=null;_bblk=1;tip('拖动中，松手保存位置');},500);
  }
  function move(e){
    if(_bb){if(Math.abs(pt(e).clientX-_bx)>12||Math.abs(pt(e).clientY-_by)>12){clearTimeout(_bb);_bb=null;}return;}
    if(!_bblk)return;
    try{var _g=window.getSelection();if(_g&&!_g.isCollapsed&&_g.removeAllRanges)_g.removeAllRanges();}catch(_e){}
    var p=pt(e);
    _bmov=1;
    /* 铃铛是 left/top 定位: 向右拖 => bellX 增大(+), 向下拖 => bellY 增大(+) */
    ST.bellX=Math.max(0,Math.min(320,ST.bellX+(p.clientX-_bx)));
    ST.bellY=Math.max(0,Math.min(640,ST.bellY+(p.clientY-_by)));
    _bx=p.clientX;_by=p.clientY;
    var r=document.documentElement.style;
    r.setProperty('--bellx',Math.round(ST.bellX)+'px');
    r.setProperty('--bella',Math.round(ST.bellY)+'px');
    if(e.preventDefault)e.preventDefault();
  }
  function up(){
    if(_bb){clearTimeout(_bb);_bb=null;}
    if(_bblk&&_bmov){saveST();tip('✔ 位置已保存');}
    _bblk=0;_bmov=0;
  }
  b.addEventListener('touchstart',down,false);
  b.addEventListener('touchmove',move,false);
  b.addEventListener('touchend',up,false);
  b.addEventListener('mousedown',down,false);
  document.addEventListener('mousemove',move,false);
  document.addEventListener('mouseup',up,false);
  /* 拖动后吞掉 click, 避免松手就打开通知面板 */
  b.addEventListener('click',function(e){
    if(_bblk||_bmov){if(e.preventDefault)e.preventDefault();if(e.stopPropagation)e.stopPropagation();_bmov=0;}
  },true);
}

