function fetchNovelGbk(url){
    return new Promise(function(resolve){
        try{
            var p=ajaxAwait(url);

            if(p&&typeof p.then==="function"){
                p.then(function(html){
                    if(typeof html==="string"){
                        resolve(html);
                    }else{
                        resolve(String(html||""));
                    }
                }).catch(function(err){
                    console.log("千白羽论坛LOG: ajaxAwait error: "+err);
                    resolve("");
                });
            }else{
                resolve(typeof p==="string"?p:String(p||""));
            }
        }catch(e){
            console.log("千白羽论坛LOG: ajaxAwait exception: "+e);
            resolve("");
        }
    });
}
function cleanNovelHtml(html){
  var m=html.match(/<div[^>]*id=["']content["'][^>]*>([\s\S]*?)<\/div>/i);
  if(!m)return '未能提取正文内容';
  var t=m[1]
    .replace(/<br\s*\/?>/gi,'\n')
    .replace(/<[^>]+>/g,'')
    .replace(/&nbsp;/g,' ')
    .replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&')
    .replace(/\n\s*\n/g,'\n\n')
    .trim();
  return t||'正文为空';
}
function showNovelModal(title,content){
  var ov=document.createElement('div');
  ov.className='novel-modal-overlay';
  ov.innerHTML='<div class="novel-modal"><div class="novel-modal-header"><span>'+title.replace(/</g,'&lt;')+'</span><span class="novel-modal-close">&times;</span></div><div class="novel-modal-body">'+content+'</div></div>';
  document.body.appendChild(ov);
  ov.querySelector('.novel-modal-close').onclick=function(){ov.remove();};
  ov.onclick=function(e){if(e.target===ov)ov.remove();};
}
function initNovelButtons(){
  var processed={};

  function addButton(href,title,parent,oldNode){
    if(!href||!title)return;

    href=String(href).trim();
    title=String(title).replace(/^\s+|\s+$/g,'');

    if(!/xiaoxiaoshuo8/i.test(href))return;
    if(!/\.html(?:[?#].*)?$/i.test(href))return;

    var key=href+'|'+title;
    if(processed[key])return;
    processed[key]=1;

    var btn=document.createElement('button');
    btn.className='novel-read-btn';
    btn.textContent='\uD83D\uDCD6 '+title;
    btn.setAttribute('data-novel-url',href);

    btn.onclick=(function(h,t){
      return function(e){
        if(e){
          if(e.preventDefault)e.preventDefault();
          if(e.stopPropagation)e.stopPropagation();
        }

        showNovelModal(t,'<div class="novel-loading">加载中...</div>');

        fetchNovelGbk(h).then(function(raw){
          var text=cleanNovelHtml(raw);
          var body=document.querySelector('.novel-modal-body');
          if(body)body.textContent=text;
        });
      };
    })(href,title);

    if(oldNode&&oldNode.parentNode){
      oldNode.parentNode.replaceChild(btn,oldNode);
    }else if(parent){
      parent.appendChild(btn);
    }
  }

  /* ① 处理页面中真正存在的 <a> */
  var links=document.querySelectorAll('a[href]');
  for(var i=0;i<links.length;i++){
    var a=links[i];
    var href=a.getAttribute('href')||a.href||'';
    var title=(a.textContent||'').trim();

    addButton(href,title,a.parentNode,a);
  }

  /* ② 处理正文文本里被转义/嵌套的 <a> */
  var walker=document.createTreeWalker(
    document.body,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );

  var nodes=[];
  var node;

  while(node=walker.nextNode()){
    if(node.parentNode&&node.parentNode.closest&&
       node.parentNode.closest('.novel-read-btn'))continue;

    var txt=node.nodeValue||'';

    if(!/xiaoxiaoshuo8/i.test(txt))continue;
    if(!/\.html/i.test(txt))continue;
    if(!/<a\b/i.test(txt)&&!/&lt;\s*a\b/i.test(txt))continue;

    nodes.push(node);
  }

  for(var ni=0;ni<nodes.length;ni++){
    var textNode=nodes[ni];
    var raw=textNode.nodeValue||'';

    /*
     * 同时支持：
     * <a href="...">章节</a>
     * &lt;a href="..."&gt;章节&lt;/a&gt;
     */
    var decoded=raw
      .replace(/&lt;/gi,'<')
      .replace(/&gt;/gi,'>')
      .replace(/&quot;/gi,'"')
      .replace(/&#39;/gi,"'")
      .replace(/&amp;/gi,'&');

    var re=/<a\b[^>]*\bhref\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
    var matches=[];
    var m;

    while(m=re.exec(decoded)){
      var href=m[1];
      var title=m[2]
        .replace(/<[^>]+>/g,'')
        .replace(/&nbsp;/gi,' ')
        .trim();

      if(!/xiaoxiaoshuo8/i.test(href))continue;
      if(!/\.html(?:[?#].*)?$/i.test(href))continue;
      if(!title)continue;

      matches.push({
        href:href,
        title:title
      });
    }

    if(!matches.length)continue;

    var frag=document.createDocumentFragment();

    for(var mi=0;mi<matches.length;mi++){
      var item=matches[mi];

      var btn=document.createElement('button');
      btn.className='novel-read-btn';
      btn.textContent='\uD83D\uDCD6 '+item.title;
      btn.setAttribute('data-novel-url',item.href);

      btn.onclick=(function(h,t){
        return function(e){
          if(e){
            if(e.preventDefault)e.preventDefault();
            if(e.stopPropagation)e.stopPropagation();
          }

          showNovelModal(t,'<div class="novel-loading">加载中...</div>');

          fetchNovelGbk(h).then(function(raw){
            var content=cleanNovelHtml(raw);
            var body=document.querySelector('.novel-modal-body');
            if(body)body.textContent=content;
          });
        };
      })(item.href,item.title);

      frag.appendChild(btn);
      frag.appendChild(document.createElement('br'));
    }

    if(textNode.parentNode){
      textNode.parentNode.replaceChild(frag,textNode);
    }
  }
}

