/* GBK: ① 显式 charset 让 legado 网络栈解码 ② 取 hex 原始字节 + bytesToStr(gbk) 兜底 */
function x8Gbk(u){
  var s='';
  try{s=x8Ajax(u+',{"charset":"gbk"}');}catch(e){s='';}
  if(s&&s.indexOf('<item')>=0&&s.indexOf(String.fromCharCode(65533))<0)return s;
  try{
    var hex=x8Ajax(u+',{"type":"hex"}');
    if(hex&&/^[0-9a-fA-F]{16,}$/.test(hex.slice(0,32))){
      var t=String(java.bytesToStr(java.hexDecodeToByteArray(hex),'gbk'));
      if(t&&t.indexOf('<item')>=0)return t;
    }
  }catch(e2){}
  return s;
}
function x8RssParse(x){
  var out=[],re=/<item[\s>][\s\S]*?<\/item>/gi,m;
  while((m=re.exec(String(x==null?'':x)))!==null){
    var s=m[0];
    var g=function(tag){
      var r=new RegExp('<'+tag+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\/'+tag+'>','i');
      var mm=r.exec(s);
      return mm?mm[1]:'';
    };
    var enc=/<enclosure[^>]*\burl\s*=\s*["']([^"']+)["']/i.exec(s);
    out.push({
      title:tx(g('title')),
      link:tx(g('link')),
      desc:tx(String(g('description')).replace(/^\s*<!\[CDATA\[/,'').replace(/\]\]>\s*$/,'')),
      cat:tx(g('category')),
      auth:tx(g('author')),
      pd:tx(g('pubDate')),
      img:enc?String(enc[1]).replace(/^\s+|\s+$/g,''):''
    });
  }
  return out;
}
function x8RssGo(it){
