    var raw='';
    try{raw=x8Gbk(it.u);}catch(e){raw='';}
    if(!raw){x8PaneBody('<div class="x8err">RSS 加载失败，请检查网络后重试。</div>');return;}
    x8List=x8RssParse(raw);
    if(!x8List.length){x8PaneBody('<div class="x8err">未能解析到条目（可能被拦截）。</div>');return;}
    /* 每条带上 Referer: 52pojie 附件图片防盗链, 无 Referer 一律 403 */
    for(var z=0;z<x8List.length;z++)x8List[z].ref=it.ref||'';
    X8PC[it.id]={kind:'rss',list:x8List};   /* fixed37: 缓存, 再进这个按钮不再重新请求 */
    x8RssPaint();
  },40);
}
