var X8B64='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function x8HexB64(hex){
  var n=hex.length>>1,out=[],i=0;
  while(i<n){
    var b0=parseInt(hex.substr(i*2,2),16);if(isNaN(b0))b0=0;
    var b1=(i+1<n)?parseInt(hex.substr((i+1)*2,2),16):-1;if(isNaN(b1))b1=-1;
    var b2=(i+2<n)?parseInt(hex.substr((i+2)*2,2),16):-1;if(isNaN(b2))b2=-1;
    out.push(X8B64.charAt(b0>>2));
    out.push(X8B64.charAt(((b0&3)<<4)|((b1<0?0:b1)>>4)));
    out.push(b1<0?'=':X8B64.charAt((((b1&15)<<2)|((b2<0?0:b2)>>6))));
    out.push(b2<0?'=':X8B64.charAt(b2&63));
    i+=3;
  }
  return out.join('');
}
function x8ImgMime(u){
  var m=/\.(png|jpe?g|gif|webp|bmp|svg|avif|ico)(?:[?#]|$)/i.exec(String(u||''));
  if(!m)return 'image/jpeg';
  var e=m[1].toLowerCase();
  if(e==='jpg')e='jpeg';
