/* ---------------- 网址导航: webview 渲染取 DOM -> 链接列表 ---------------- */
function x8Abs(h,b){
  h=String(h==null?'':h).replace(/^\s+|\s+$/g,'');
  if(/^https?:\/\//i.test(h))return h;
  if(/^\/\//.test(h))return 'https:'+h;
  var m=/^(https?:\/\/[^\/]+)/i.exec(String(b||''));
  var org=m?m[1]:'';
  if(!org)return '';
  if(h.charAt(0)==='/')return org+h;
  h=h.replace(/^\.\//,'').replace(/^(\.\.\/)+/,'');
  return org+'/'+h;
}
function x8NavLinks(html){
  var out=[],seen={},re=/<a\b[^>]*\bhref\s*=\s*["']([^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi,m;
