/* fixed45: 「我的」容器的两个开关（url显示为图片 / url显示为按钮）原来只认带协议前缀的
   https?://… ，于是 www.foo.com、foo.com/a.png 这类没写前缀的网址既显示不了图片也出不了按钮。
   现在：① 先把原文里已有的 https?://… 抠出来（保持原样，记下位置）；
        ② 把它们抹成空格，再补扫一遍「裸域名」（www.* 或已知 TLD）；
        ③ 命中后统一补上 https://；最后按出现位置排序（保持原文顺序）。
   两个开关都吃 x8MineCache，而 x8MineCache 只由本函数产出 —— 所以改这一处就同时覆盖两个功能。
   ★裸域名扫描要防「误吞片段」：ftp://x.cn/f 里的 x.cn、mailto:a@b.com 里的 b.com
     都不是独立网址。用「前一个字符守卫」处理（前字符是 [A-Za-z0-9._%+-@/] 就跳过），
     这样 scheme://… 内部与邮箱内部都不会被切出来，而 www.qq.com 这类正常裸域名前面总是
     空格/中文/（/：等分隔符，不受影响。 */
function x8MineAbs(u){
  u=String(u==null?'':u).replace(/^\s+|\s+$/g,'');
  if(!u)return '';
  return /^[a-z][a-z0-9+.\-]*:\/\//i.test(u)?u:'https://'+u;
}
function x8Urls(t){
  var s=String(t==null?'':t),acc=[],seen={},out=[],m,i,u,
      re=/https?:\/\/[A-Za-z0-9\-._~:\/?#\[\]@!$&'()*+,;=%]+/g,
      re2=/(?:[A-Za-z0-9](?:[A-Za-z0-9\-]*[A-Za-z0-9])?\.)+(?:com|cn|net|org|io|me|tv|cc|xyz|top|info|biz|app|dev|pro|site|online|club|fun|shop|wang|xin|ltd|vip|art|edu|gov|mil|int|co|ai|im|fm|gg|la|us|uk|jp|kr|hk|tw|mo|link|cloud|tech|store|life|live|world|space|press|wiki|blog|news|media|design|group|one|run|red|work|plus|tools|page|games|game)(?![A-Za-z0-9\-])(?::\d+)?(?:[\/?#][A-Za-z0-9\-._~:\/?#\[\]@!$&'()*+,;=%]*)?/gi,
      pre=/[A-Za-z0-9._%+\-@\/]/;
  function clean(x){
    x=String(x==null?'':x).replace(/[.,;:!?)\]}'"]+$/,'');
    return x?x8MineAbs(x):'';
  }
  re.lastIndex=0;
  while((m=re.exec(s))!==null){u=clean(m[0]);if(u)acc.push([m.index,u]);}
  var rest=s.replace(re,function(x){return x.replace(/[^\s]/g,' ');});
  re2.lastIndex=0;
  while((m=re2.exec(rest))!==null){
    if(m.index>0&&pre.test(rest.charAt(m.index-1)))continue;
    u=clean(m[0]);if(u)acc.push([m.index,u]);
  }
  acc.sort(function(a,b){return a[0]-b[0];});
  for(i=0;i<acc.length;i++){u=acc[i][1];if(seen[u])continue;seen[u]=1;out.push(u);}
  return out;
}
function x8IsImg(u){return /\.(png|jpe?g|gif|webp|bmp|svg|avif|ico)(?:[?#]|$)/i.test(u)||/^data:image\//i.test(u);}
