/* ---------------- 小说正文容器: 双阅读模式 + 临时全透明 ---------------- */
var X8DOC={mode:'scroll',pg:0,pgn:1,h:0,timer:0,lh:0,bound:0};
var X8DPAD=6;   /* 翻页模式上下留白(放在 wrap 的 padding 上, 保证正文网格与页网格从 0 对齐) */
function x8Mode(){return ST.x8Mode==='page'?'page':'scroll';}
/* 容器基础高度: 由面板的 x8DocH(vh) 换算成像素 */
function x8DocBase(){
  var vh=0;
  try{vh=(window&&window.innerHeight)||0;}catch(e){}
  if(!vh){try{vh=document.documentElement.clientHeight||0;}catch(e1){}}
  if(!vh)vh=600;
  var pct=(ST.x8DocH==null?76:ST.x8DocH);
  if(!(pct>0))pct=76;
  return Math.max(160,Math.round(vh*pct/100));
