/* 量一行有多高(拿正文实际字体/行高量, 量完即删) */
function x8LineH(cg){
  var host=(cg&&cg.firstChild&&cg.firstChild.appendChild)?cg.firstChild:cg;
  if(!host||!host.appendChild)return 0;
  var d=null,h=0;
  try{
    d=document.createElement('div');
    d.style.cssText='position:absolute;left:0;top:0;visibility:hidden;white-space:nowrap;line-height:inherit;font:inherit;margin:0;padding:0;border:0;';
    d.textContent='M';
    host.appendChild(d);
    h=d.offsetHeight||0;
  }catch(e){h=0;}
  try{if(d&&d.parentNode&&d.parentNode.removeChild)d.parentNode.removeChild(d);}catch(e2){}
