  /* ★ fixed37: 先记下滑动模式下用户滚了多远。容器由 overflow-y:auto 改成 overflow:hidden 后,
     scrollTop 会被浏览器保留 -> 页面等于整体上移且再也滚不回顶部(「无法翻页回正文顶部」的根因)。 */
  var S=0;
  try{S=wrap.scrollTop||0;}catch(e0){}
  X8DOC.mode=pg?'page':'scroll';
  wrap.className='x8docbd'+(pg?' pg':'');
  try{wrap.scrollTop=0;wrap.scrollLeft=0;}catch(e1){}
  if(pg){
    /* ★ 页高取「行高的整数倍」, 并且把上下留白放到 wrap 的 padding 上(内层 padding 顶部为 0),
       这样正文的行网格与页网格都从 0 开始, 每页正好装整数行, 不会出现半行被容器切掉。 */
    var base=x8DocBase();
    var lh=x8LineH(cg);
    X8DOC.lh=lh;
    var h=base;
    if(lh>1){
      var lines=Math.floor(base/lh);
