    try{wrap.style.height=(h+X8DPAD*2)+'px';}catch(e2){}
    X8DOC.pgn=Math.max(1,Math.ceil((cg.scrollHeight||0)/h));
  }else{
    X8DOC.h=0;X8DOC.pgn=1;
    try{wrap.style.height='';}catch(e3){}
  }
  if(isNew)X8DOC.pg=0;
  else if(pg&&!wasPg&&S>0){X8DOC.pg=Math.floor(S/Math.max(1,X8DOC.h));}
  if(X8DOC.pg>X8DOC.pgn-1)X8DOC.pg=X8DOC.pgn-1;
  if(X8DOC.pg<0)X8DOC.pg=0;
  if(pg)inner.style.transform='translateY(-'+(X8DOC.pg*X8DOC.h)+'px)';
  else inner.style.transform='';
  if(!pg&&wasPg&&oldH>0&&oldPg>0){try{wrap.scrollTop=oldPg*oldH;}catch(e4){}}   /* fixed37: 位置衔接 */
  var m0=document.getElementById('x8m0'),m1=document.getElementById('x8m1');
  if(m0)m0.className='x8bb'+(pg?'':' on');
  if(m1)m1.className='x8bb'+(pg?' on':'');
  x8PgBar();
  if(!isNew)return;
  wrap.setAttribute('data-x8b','1');
  if(X8DOC.bound!==1){
    X8DOC.bound=1;
    try{if(window&&window.addEventListener)window.addEventListener('resize',function(){
      try{if(x8Mode()==='page')x8DocInit();}catch(_r){}
    },false);}catch(_b){}
  }
  /* 滑动阅读: 滚动过程中容器临时全透明(松手 220ms 后恢复) */
  wrap.addEventListener('scroll',function(){
    x8DocTrans(true);
    if(X8DOC.timer)clearTimeout(X8DOC.timer);
    X8DOC.timer=setTimeout(function(){x8DocTrans(false);},220);
  },false);
  /* 翻页模式: 左右滑动翻页, 翻页过程中容器临时全透明 */
  var sx=0,sy=0,st=0;
  function pt(e){
    var t=(e.touches&&e.touches[0])||(e.changedTouches&&e.changedTouches[0])||e||{};
    return {x:t.clientX||0,y:t.clientY||0};
  }
  wrap.addEventListener('touchstart',function(e){var q=pt(e);sx=q.x;sy=q.y;st=Date.now();},false);
  wrap.addEventListener('touchmove',function(e){
    if(X8DOC.mode!=='page')return;
    var q=pt(e);
    if(Math.abs(q.x-sx)>Math.abs(q.y-sy)&&Math.abs(q.x-sx)>8){
      if(e.cancelable&&e.preventDefault)e.preventDefault();
    }
  },false);
  wrap.addEventListener('touchend',function(e){
    if(X8DOC.mode!=='page')return;
    var q=pt(e),dx=q.x-sx;
    if(Math.abs(dx)>36)x8PgStep(dx<0?1:-1);
  },false);
}

/* ---------------- fixed36: 容器内链接/点击一律走内置浏览器 ----------------
   书源首页自身是 WebView: 点 <a> / window.open / location.href 造成的页面级导航会被 Legado
   当书源内链接管 -> 渲染详情页。这里在捕获阶段拦掉容器内所有 <a> 的默认导航, 统一转 x8Open。 */
var X8TRAP=0,X8TROOT='x8side,x8pane,x8nav,x8pbd,x8phd,x8doc,x8docbd,x8ifw,x8mpv,x8ann,x8annb';
function x8InScope(n){
  var d=0,ids=','+X8TROOT.split(',').join(',')+',';
  while(n&&d<20){
    try{
      var id=String(n.id==null?'':n.id),cn=String(n.className==null?'':n.className);
      if(id&&ids.indexOf(','+id+',')>=0)return true;
      if(cn&&(cn.indexOf('x8side')>=0||cn.indexOf('x8pane')>=0||cn.indexOf('x8nav')>=0
        ||cn.indexOf('x8doc')>=0||cn.indexOf('x8me')>=0||cn.indexOf('x8rss')>=0
        ||cn.indexOf('x8nlist')>=0||cn.indexOf('x8mpv')>=0))return true;
    }catch(e){}
    n=n.parentNode;d++;
  }
  return false;
}
function x8AnchorOf(n){
  var d=0;
  while(n&&d<20){
    try{if(n.tagName&&String(n.tagName).toUpperCase()==='A')return n;}catch(e){}
    n=n.parentNode;d++;
  }
  return null;
}
function x8Base(){
  if(x8Cur&&x8Cur.u)return String(x8Cur.u);
  try{if(typeof location!=='undefined'&&location.href)return String(location.href);}catch(e){}
  return '';
}
function x8TrapClick(e){
  var t=e&&(e.target||e.srcElement);
  if(!t)return true;
  var a=x8AnchorOf(t);
  if(!a)return true;
  if(!x8InScope(a))return true;              /* 容器外(如书源自己的列表)不动 */
  var href='';
  try{href=String(a.getAttribute('href')||a.href||'');}catch(e1){href='';}
  try{if(e.preventDefault)e.preventDefault();}catch(e2){}
  try{if(e.stopPropagation)e.stopPropagation();}catch(e3){}
  try{if(e.returnValue!==undefined)e.returnValue=false;}catch(e4){}
  href=href.replace(/^\s+|\s+$/g,'');
  if(!href||/^(javascript:|#|mailto:|tel:|sms:|data:|blob:|about:)/i.test(href))return false;
  var ti='';
  try{ti=String(a.textContent==null?'':a.textContent).replace(/\s+/g,' ');}catch(e5){ti='';}
  x8Open(x8Abs(href,x8Base()),ti);
  return false;
}
function x8TrapInit(){
  if(X8TRAP)return;
  X8TRAP=1;
  try{document.addEventListener('click',x8TrapClick,true);}catch(e){}
  /* 覆盖 window.open: 第三方脚本的 window.open 也收口到内置浏览器, 不让首页 WebView 导航 */
  try{
    if(typeof window!=='undefined'&&window&&typeof window.open==='function'){
      window.__x8open=window.open;
      window.open=function(u){try{x8Open(u,'');}catch(e){}return null;};
    }
  }catch(e2){}
}

/* ---------------- fixed37: 详情页章节目录右侧「大滑块」快速定位 ----------------
   按住滑块(或点轨道)上下拖动 -> 目录列表跟着滚; 拖动时在滑块左侧显示当前章节名气泡。
   只用 touch 事件(touch-action:none 保证拖动不会连带滚动页面), 顺带支持鼠标拖动。 */
var X8SS={list:null,track:null,thumb:null,tip:null,rows:[],drag:0,off:0,mouse:0};
var x8SlideNames=[];
function x8SlideRows(){
  X8SS.rows=[];
  var list=X8SS.list;
  if(!list)return;
  var ns=null;
  try{ns=list.getElementsByClassName?list.getElementsByClassName('xschap'):null;}catch(e){ns=null;}
  if(ns&&ns.length){
    for(var i=0;i<ns.length;i++)X8SS.rows.push({t:String(ns[i].textContent==null?'':ns[i].textContent)});
    return;
  }
  var nm=x8SlideNames||[];
  for(var j=0;j<nm.length;j++)X8SS.rows.push({t:String(nm[j]==null?'':nm[j])});
}
function x8SlideSync(){
  var list=X8SS.list,track=X8SS.track,thumb=X8SS.thumb;
  if(!list||!track||!thumb)return;
  var viewH=list.clientHeight||0,allH=list.scrollHeight||0,trH=track.clientHeight||0;
  if(trH<=0)return;
  var th=trH;
  if(allH>viewH&&viewH>0)th=Math.round(trH*viewH/allH);
  if(th<34)th=34;
  if(th>trH)th=trH;
  thumb.style.height=th+'px';
  var maxPos=trH-th,maxScr=Math.max(0,allH-viewH);
  var ratio=maxScr>0?(list.scrollTop||0)/maxScr:0;
  if(ratio<0)ratio=0;
  if(ratio>1)ratio=1;
  thumb.style.top=Math.round(ratio*(maxPos>0?maxPos:0))+'px';
  track.className=(allH<=viewH+2)?'x8ssl off':'x8ssl';
}
function x8SlideTip(ratio){
  var tip=X8SS.tip;
  if(!tip)return;
  var rows=X8SS.rows||[];
  if(!rows.length){tip.textContent='';return;}
  var i=Math.round(ratio*(rows.length-1));
  if(i<0)i=0;
  if(i>rows.length-1)i=rows.length-1;
  tip.textContent=rows[i].t||'';
}
function x8SlideTo(y){
  var list=X8SS.list,track=X8SS.track,thumb=X8SS.thumb;
  if(!list||!track||!thumb)return;
  var tr=null;
  try{tr=track.getBoundingClientRect();}catch(e){tr=null;}
  if(!tr)return;
  var trH=tr.height||track.clientHeight||0;
  var thumbH=thumb.offsetHeight||0;
  var maxPos=trH-thumbH;
  if(maxPos<1)maxPos=1;
  var pos=(y||0)-(tr.top||0)-X8SS.off;
  if(pos<0)pos=0;
  if(pos>maxPos)pos=maxPos;
  var ratio=pos/maxPos;
  var maxScr=Math.max(0,(list.scrollHeight||0)-(list.clientHeight||0));
  list.scrollTop=Math.round(ratio*maxScr);
  x8SlideTip(ratio);
}
function x8SlidePoint(e){
  var t=(e&&e.touches&&e.touches[0])||(e&&e.changedTouches&&e.changedTouches[0])||e||{};
  return {y:(t.clientY==null?0:t.clientY)};
}
function x8SlideDown(e){
  var track=X8SS.track,thumb=X8SS.thumb;
  if(!track||!thumb)return;
  var q=x8SlidePoint(e);
  var tr=null,thr=null;
  try{tr=track.getBoundingClientRect();}catch(e1){}
  try{thr=thumb.getBoundingClientRect();}catch(e2){}
  X8SS.drag=1;
  if(tr&&thr&&q.y>=(thr.top||0)&&q.y<=(thr.bottom||0)){
    X8SS.off=q.y-(thr.top||0);          /* 按在滑块身上 -> 保持抓握点, 不跳 */
  }else{
    X8SS.off=Math.round((thumb.offsetHeight||0)/2);   /* 按在轨道上 -> 滑块中心跟过来 */
  }
  if(thumb.className.indexOf('on')<0)thumb.className='x8sst on';
  if(e&&e.cancelable&&e.preventDefault)e.preventDefault();
  x8SlideTo(q.y);
}
function x8SlideMove(e){
  if(!X8SS.drag)return;
  if(e&&e.cancelable&&e.preventDefault)e.preventDefault();
  x8SlideTo(x8SlidePoint(e).y);
}
function x8SlideUp(){
  X8SS.drag=0;
  var thumb=X8SS.thumb;
  if(thumb)thumb.className='x8sst';
}
function x8SlideInit(){
  var list=document.getElementById('xsrules'),track=document.getElementById('x8ssl'),
      thumb=document.getElementById('x8sst'),tip=document.getElementById('x8sstip');
  if(!list||!track||!thumb)return;
  X8SS.list=list;X8SS.track=track;X8SS.thumb=thumb;X8SS.tip=tip;
  X8SS.drag=0;X8SS.off=0;X8SS.mouse=0;
  x8SlideRows();
  try{
    track.addEventListener('touchstart',x8SlideDown,{passive:false});
    track.addEventListener('touchmove',x8SlideMove,{passive:false});
    track.addEventListener('touchend',x8SlideUp,false);
    track.addEventListener('touchcancel',x8SlideUp,false);
    track.addEventListener('mousedown',function(e){
      X8SS.mouse=1;x8SlideDown(e);
      if(e&&e.preventDefault)e.preventDefault();
    },false);
    list.addEventListener('scroll',function(){try{x8SlideSync();}catch(e){}},false);
    if(window&&window.addEventListener){
      window.addEventListener('mousemove',function(e){if(X8SS.mouse)x8SlideMove(e);},false);
      window.addEventListener('mouseup',function(){if(X8SS.mouse){X8SS.mouse=0;x8SlideUp();}},false);
      window.addEventListener('resize',function(){try{x8SlideSync();}catch(e){}},false);
    }
  }catch(_sb){}
  setTimeout(function(){try{x8SlideSync();}catch(e){}},40);
  try{x8SlideSync();}catch(e2){}
}

/* ===== fixed38: 推荐阅读里的「免费资讯 / 留言」(webnote 云便签) =====
   免费资讯: 只读。https://webnote.cc/p/e17d64cd356df1c6 (note_id=e17d64cd356df1c6, 无密码)
             取法与「更新公告」完全一致: POST WNAPI+'info/'  body=note_id&note_pwd=
             头带 Origin:https://webnote.cc + Referer。正文用 x8Rich() 渲染(转义 + 链接转「一键跳转」+ 图片缩略图 + .json 一键导入)。
   留言:     可读可写。https://webnote.cc/留言 按 **note_name** 存取:
             读 wnGet('留言'); 写 wnPut('留言',note_id,note_token,wnPack(文本));
             失败再 wnRetry('留言',文本)。与「上传到背景图片云」同一套接口。
   ★两者都进文章容器, 沿用 fixed37 的「缓存命中直接渲染 + 迟到结果作废」。 */
var X8NFID='e17d64cd356df1c6';
var X8NMSG='\u7559\u8a00';                 /* 留言便签的 note_name */
var X8NMSU='https://webnote.cc/%E7%95%99%E8%A8%80';
/* 按 note_id 取便签(与 annReq 同通道, 只是 id / Referer 可变) */
function x8nReq(id){
  var u=WNAPI+'info/';
  var h={'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',
         'Origin':'https://webnote.cc','Referer':'https://webnote.cc/p/'+id,
         'X-Requested-With':'XMLHttpRequest',
         'Accept':'application/json, text/javascript, */*; q=0.01'};
  var body='note_id='+encodeURIComponent(id)+'&note_pwd=';
  return new Promise(function(res,rej){
    var done=false,tm=null;
    try{tm=setTimeout(function(){if(done)return;done=true;rej(new Error('请求超时(20秒)'));},20000);}catch(e){}
    function fin(f,a){if(done)return;done=true;try{tm&&clearTimeout(tm);}catch(e){}f(a);}
    wnRun(wnChan(u,body,h),0,'').then(function(t){fin(res,t);},function(e){fin(rej,e);});
  });
}
function x8Nid(it){return String((it&&it.nid)||X8NFID);}
function x8Nnm(it){return String((it&&it.nm)||X8NMSG);}
