/* ===== fixed39: 文章容器统一文本渲染 =====
   ★核心约定(用户要求): 侧边栏文章容器里的链接**一律不渲染成 <a>**。
   在 WebView 里点 <a> 就是一次页面级导航, 会被书源当内链去渲染详情页 —— 所以改成
   「纯文本 + 一键跳转按钮」, 出口统一收口到内置浏览器(java.startBrowser)。
   · 图片链接 -> 缩略图, 点缩略图就地放大(全屏遮罩 #x8lb)
   · .json 链接 -> 额外附「⤓ 一键导入」
   仅供 note(免费资讯) 与 text(纯文本容器) 使用; 导航列表另有 x8NavList, RSS 另有 x8RssItem。 */
function x8Rich(txt){
  var raw=String(txt==null?'':txt),re=/https?:\/\/[A-Za-z0-9\-._~:\/?#\[\]@!$&'()*+,;=%]+/gi,out='',last=0,m;
  while((m=re.exec(raw))!==null){
    var u=m[0],tail='',mt=u.match(/[.,;:!?)\]}'"]+$/);
    if(mt){tail=mt[0];u=u.slice(0,u.length-tail.length);}
    out+=annEsc(raw.slice(last,m.index))+x8Link(u)+annEsc(tail);
    last=m.index+m[0].length;
  }
  return out+annEsc(raw.slice(last));
}
/* 单条链接 -> 「纯文本 / 缩略图」 + 一键跳转按钮 (+ .json 一键导入)。
   URL 只放进 data-u(HTML 转义), onclick 用 this 取 —— 不用把它拼进 JS 字符串字面量。 */
function x8Link(u){
  var e=String(u||'');if(!e)return '';
  var o='';
  if(x8IsImg(e))o+='<span class="x8iw"><img class="x8th" src="'+annEsc(e)+'" data-u="'+annEsc(e)
    +'" alt="预览图" onclick="x8ZoomEl(this)"></span>';
  else o+='<span class="x8lt">'+annEsc(e)+'</span>';
  o+='<button class="x8bb x8jump" data-u="'+annEsc(e)+'" onclick="x8LnkOpen(this)">一键跳转</button>';
  if(annIsJson(e))o+='<span class="animp" data-u="'+annEsc(e)+'" onclick="annImp(this)">\u2913 一键导入</span>';
  return o;
}
