function createPushRss(x,oname,ogroup,f,color){
    let msgBox =  document.createElement('div');
    msgBox.className = "msg-item";
    msgBox.innerHTML = `
                       <div class="img">
                                  ${/^http|data:/.test(x.sourceIcon)?"<img src=\""+x.sourceIcon+"\">":x.sourceName.match(/[\u4e00-\u9fa5a-zA-Z.]/)[0] }
                         </div>
                     <div class="msg-name">
                             <p class="name">
                             ${oname===x.sourceName?"":"<span>"+oname+ " => </span>"}
                             ${x.sourceName}
                             <span style="color:${color};float:right">&emsp;${f}</span>
                             <span style="color:black;float:right">
                             ${ogroup===x.sourceGroup?"":"<span>"+(ogroup?ogroup:"未分组")+ " => </span>"}
                             ${x.sourceGroup?""+x.sourceGroup+"":"未分组"}
                             </span>
                             </p>
                      <p class="rssurl">${x.sourceUrl}</p>
                </div>
                       `;
                       if(f==="已同步" || f === "已删除")
document.querySelector('.pushrss-info').insertAdjacentElement('afterbegin', msgBox);
                       if(f==="未同步")
         document.querySelector(".pushrss-info").appendChild(msgBox)
}


function pushRss(rssUrl,f){
    let getRssUrl = rssUrl+"/getRssSources";
    let delRssUrl = rssUrl+"/deleteRssSources";
    let saveRssUrl = rssUrl+"/saveRssSource";

    ajaxAwait(getRssUrl,500)
         .then(r=>{
          if(/^java.net.ConnectException: Failed|^java.net.S/.test(r)){
              document.querySelector(".pushrss-info").innerHTML = `<div class="error">
              请检查是否打开web服务<br>
              请检查网址是否错误
              </div>`;
              java.longToast("\n请检查是否打开web服务\n请检查网址是否错误")
              return
          }

          let delwebs = [];
          document.querySelector(".pushrss-info").classList.remove("hide");
          document.querySelector(".pushrss-edit").classList.add("hide");
          let rssData = JSON.parse(r).data;
          rssData.forEach(x=>{
              let findweb = webs.find(web=>web.url === x.sourceUrl);
              if(!findweb){
                  if(f === 1){
                      delwebs.push(x);
                      createPushRss(x,x.sourceName,x.sourceGroup,"已删除","red");
                  }else{
                      createPushRss(x,x.sourceName,x.sourceGroup,"未同步","blue");
                  }
              }else{
                  let oname = x.sourceName;
                  let ogroup = x.sourceGroup;
                  if(f===2){
                      if(findweb.sort??""){
                          x.customOrder = findweb.sort
                      }
                  }else{
                  let oname = x.sourceName;
                  let ogroup = x.sourceGroup;
                  x.sourceName = findweb.name.replace(/\\n/g,'\n');
                  x.sourceGroup = findweb.group[0]==="-1"?"":findweb.group.join(",").replace(/,$/g,'');
                  x.sourceIcon = findweb.icon.length>5?findweb.icon:"";
                 }
                 fetch(saveRssUrl, {
                     method: "POST",
                     headers: {
                         "Content-Type": "application/json"
                        },
                        body: JSON.stringify(x)
                   })
                   .then(res =>{
                       createPushRss(x,oname,ogroup,"已同步","green")
                   })
                   .catch(error => {
                       java.toast("出现错误")
                   });
              }
          });
          if(f ==1){
              fetch(delRssUrl, {
                     method: "POST",
                     headers: {
                         "Content-Type": "application/json"
                        },
                        body: JSON.stringify(delwebs)
                   })
                   .then(res =>{
                       java.toast("已同步完成")
                   })
                   .catch(error => {
                       java.toast("出现错误")
                   });
          };

          java.toast("已同步完成")
       })
       .catch(e=>{
           console.log(e)
             	 document.querySelector(".pushrss-info").innerHTML = `<div class="error">
              请检查是否打开web服务<br>
              请检查网址是否错误
              </div>`;
              java.longToast("\n请检查是否打开web服务\n请检查网址是否错误")
        });
}


