    let checkbox = item.querySelector(".editgroup-order input[type='checkbox']");
    let isChecked = checkbox?.checked ?? true; 

    if (isChecked) {
        selectedGroupIds.push(newId);
    }

    if (seenIds.has(newId)) continue;
    seenIds.add(newId);
    if (oldId && !isSpecialGroup && oldId !== newId) {
        idMap.set(oldId, newId);
    }
    let originalGroup = groups.find(g => g.id === oldId);
    let sValue = originalGroup ? originalGroup.s : 1; 
    if (!isEditWeb && !isSpecialGroup) {
        sValue = isChecked ? 1 : 0;
