    let group = originalGroup || { id: newId, name: jname, s: sValue };
    group.id = newId;
    group.name = jname;
    if (!isEditWeb && !isSpecialGroup) {
        group.s = sValue;
    } else if (!originalGroup) {
        group.s = sValue;
    }

    newGroups.push(group)
}

