function saveRss(){
    const selectitem = document.querySelectorAll(
  '.rsslist-item input[type="checkbox"]:checked:not([disabled])') ?? [];
  if(selectitem.length==0){
      java.toast("暂无可添加的订阅源");
      return;
  }

  selectitem.forEach((x,i)=>{
      x.disabled = true;
      x.closest('.rsslist-item').classList.add("select");
      let web = {};
      let index = x.name;
      let r = rssData[index];
      web.name = r.sourceName;
      web.url = r.sourceUrl
      web.icon = r.sourceIcon;
      web.group =(r.sourceGroup?r.sourceGroup.split(","):"") || ["-1"];
      web.group.forEach(groupItem => {
          if (!groups.some(group => group.id === groupItem)) {
              groups.push({
                  id: groupItem,
                  s: 1,
                  name: groupItem!=="-1"?groupItem:"未分组"
                 });
              }
          });
         webs.push(web);
    });

    if (!groups.some(x => x.f == 1)) {
        const uncategorized = groups.find(x => x.id == "-2");
        if (uncategorized) {
            uncategorized.f = 1;
        } 
     }

     getRssData.webs = webs;
     getRssData.groups = groups;
     source.putVariable(JSON.stringify(getRssData));
     upGroups();
     java.toast("添加成功");
}

function upGroups(){
     getRssData = JSON.parse(source.getVariable() || "{}");
     groups = getRssData.groups ??  [{id:"-2",name:"全部",s:1},{id:"-1",name:"未分组",s:1}];
     webs = getRssData.webs ?? [];
     let groupHtml = "";
     let f = groups.find(x=> x.f===1 && x.s === 1);
     groups.forEach((x,i)=>{
         if(x.s===1){
             groupHtml+=`
         <div class="group${f?(x.f===1?" active":""):(i==0?" active":"")}" data-id="${x.id}">${x.name}</div>
         `
         }
     });
     document.querySelector('.groups-box').innerHTML = groupHtml;
     initAllEvents()
}

function waitForElement(selector, callback, timeout = 1000) {
    const startTime = Date.now();
    const checkElement = () => {
        const element = document.querySelector(selector);
        if (element) {
            callback(element);
        } else if (Date.now() - startTime < timeout) {
            setTimeout(checkElement, 100);
        } else {
            callback(null);
        }
    };
    checkElement();
}

function getWebs(id){
    let filterWebs;
    if(id==="-2"){
        filterWebs = webs.map(web => ({ ...web })).sort((a, b) => a.sort - b.sort);
    }else{
        filterWebs = webs.filter(x => x.group.some(item => item === id));
    }

    let websHtml = "";
    document.querySelector(".webs-box").innerHTML = "";
    if(filterWebs.length==0){
        websHtml = `
        <div style="margin-top:200px">
               暂无订阅源
        </div>
        `;
    }

    filterWebs.forEach(x => {
    const webBox = document.createElement('div');
    webBox.className = 'web-box';
    webBox.setAttribute('data-url', x.url);
    if(isEditWeb)webBox.classList.add("editwebBox");
    const iconBox = document.createElement('div');
    iconBox.className = 'web-icon-box';
    const iconInner = document.createElement('div');
    let icon = x.icon.trim();
    if (/^http|data:/.test(icon)) {
        const img = document.createElement('img');
        img.src = icon;
        iconInner.appendChild(img);
    } else {
        const iconDiv = document.createElement('div');
        const iconText = x.name.trim().match(/[\u4e00-\u9fa5a-zA-Z.]/)[0];
        iconDiv.textContent = iconText;
        iconInner.appendChild(iconDiv);
    }
    if(isEditWeb){
        const sBox = document.createElement('div');
        sBox.className = "s-box";
        sBox.innerHTML = "📝"
        webBox.appendChild(sBox);
    }

    iconBox.appendChild(iconInner);
    const nameBox = document.createElement('div');
    nameBox.className = 'web-name';
    nameBox.innerHTML = x.name.replace(/\n/g, '<br>');     
    webBox.appendChild(iconBox);
    webBox.appendChild(nameBox);
    document.querySelector(".webs-box").appendChild(webBox);
    initSortable();
});
}

