};

document.addEventListener('change', e => {
    if (e.target.matches('.rsslist-item input[type="checkbox"]:not([disabled])')) {
        updateSelectAllState();
    }
});

document.addEventListener('click', e => {
    if (e.target.closest('.rsslist-item')) {
        const item = e.target.closest('.rsslist-item');
        const checkbox = item.querySelector('input[type="checkbox"]');
        if (checkbox && !e.target.matches('input[type="checkbox"]') && !checkbox.disabled) {
            checkbox.checked = !checkbox.checked;
            checkbox.dispatchEvent(new Event('change', { bubbles: true }));
        }
    }
});

function updateSelectAllState() {
    const visibleCheckboxes = document.querySelectorAll('.rsslist-item:not([style*="display: none"]) input[type="checkbox"]:not([disabled])');

    if (visibleCheckboxes.length === 0) {
        document.querySelector('.rsslist-check input').checked = false;
        return;
    }

    const allChecked = Array.from(visibleCheckboxes).every(cb => cb.checked);
    document.querySelector('.rsslist-check input').checked = allChecked;
}


