function initSwipeGesture() {
    const swipeArea = document.querySelector('.webs-c');
    if (!swipeArea) {
        console.error('找不到滑动手势区域');
        return;
    }

    let touchStartTime = 0;
    let isPotentialSwipe = true;
    let startX = 0;
    let startY = 0;
    let lastX = 0;
    let lastY = 0;
    const VERTICAL_THRESHOLD = 200; 
    const LONG_PRESS_TIME = 200; // 长按时间阈值（毫秒）

    swipeArea.addEventListener('touchstart', function(e) {
        touchStartTime = Date.now();
        swipeStartX = e.touches[0].clientX;
        startX = e.touches[0].clientX;
        startY = e.touches[0].clientY;
        lastX = startX;
        lastY = startY;
        isSwiping = true;
        isPotentialSwipe = true;
    }, { passive: true });

    swipeArea.addEventListener('touchmove', function(e) {
        if (!isSwiping || !isPotentialSwipe) return;
        const currentX = e.touches[0].clientX;
        const currentY = e.touches[0].clientY;
        const verticalDiff = Math.abs(currentY - startY);
        if (verticalDiff > VERTICAL_THRESHOLD) {
            isPotentialSwipe = false;
        }

        lastX = currentX;
        lastY = currentY;
    }, { passive: true });

    swipeArea.addEventListener('touchend', function(e) {
        if (!isSwiping || !isPotentialSwipe) {
            isSwiping = false;
            isPotentialSwipe = true;
            return;
        }

        const touchDuration = Date.now() - touchStartTime;
        const endX = e.changedTouches[0].clientX;
        const diffX = endX - swipeStartX;
        if (touchDuration > LONG_PRESS_TIME) {
            isSwiping = false;
            isPotentialSwipe = true;
            return;
        }

        if (Math.abs(diffX) > 40) {
            const activeGroup = document.querySelector('.group.active');
            if (activeGroup) {
                const groups = Array.from(document.querySelectorAll('.group'));
                const currentIndex = groups.indexOf(activeGroup);

                if (diffX > 0 && currentIndex > 0) {
                    groups[currentIndex - 1].click();
                } else if (diffX < 0 && currentIndex < groups.length - 1) {
                    groups[currentIndex + 1].click();
                }
            }
        }

        isSwiping = false;
        isPotentialSwipe = true;
    }, { passive: true });
}


function initSortable() {
    if (sortableInstance) {
        sortableInstance.destroy();
    }

    sortableInstance = new Sortable(document.querySelector('.webs-box'), {
        animation: 150,
        fallbackOnBody: false,   
        fallbackClass: "sortable-fallback",
        fallbackTolerance: 0,   
        ghostClass: "sortable-ghost",
        dragClass: "sortable-drag",
        chosenClass: "sortable-chosen",
        dataIdAttr: 'data-url',
        delay: 100,

        onEnd: function(evt) {
    const activeGroup = document.querySelector('.group.active');
    if (!activeGroup) return;

    const groupId = activeGroup.getAttribute('data-id');
    const container = evt.to;
    const items = Array.from(container.children);

    if (groupId === '-2') {
    const sortedDataIds = items.map(item => item.getAttribute('data-url'));
    sortedDataIds.forEach((dataId, sortIndex) => {
        const web = webs.find(w => w.url.toString() === dataId);
        if (web) {
            web.sort = sortIndex; 
           }
          });
}else {
        const sortedDataUrls = items.map(item => item.getAttribute('data-url'));
        const currentGroupWebs = webs.filter(web => web.group === groupId);
        if (currentGroupWebs.length === 0) {
            return;
        }
        const urlToWebMap = {};
        currentGroupWebs.forEach(web => {
            urlToWebMap[web.url] = web;
        });
        const reorderedCurrentGroupWebs = [];
        sortedDataUrls.forEach(dataUrl => {
            if (urlToWebMap[dataUrl]) {
                reorderedCurrentGroupWebs.push(urlToWebMap[dataUrl]);
            }
        });
        webs = webs.filter(web => web.group !== groupId);
        reorderedCurrentGroupWebs.forEach(web => {
            webs.push(web);
        });
    }

    getRssData.webs = webs;
    source.putVariable(JSON.stringify(getRssData));
}


    });
}


