const readTheme = JSON.parse(java.getThemeConfig());

// 默认颜色值
const defaultColors = {
    backgroundColor: readTheme["backgroundColor"].replace(/#../,'#') || '#f8f9fa',
    accentColor: readTheme["accentColor"].replace(/#../,'#') || '#367ECE',
    iconBgColor: 'none',
    iconTextColor: readTheme["accentColor"].replace(/#../,'#') || '#367ECE',
    topColor: readTheme["primaryColor"].replace(/#../,'#') || '#ffffff'
};

let currentColors = getRssData.theme ?? { ...defaultColors };

function updateColorDisplay(type, value) {
            const previewElement = document.getElementById(`${type}Preview`);
            if (previewElement) {
                previewElement.style.backgroundColor = value;
            }
            const valueElement = document.getElementById(`${type}Value`);
            if (valueElement) {
                valueElement.textContent = value;
            }
            currentColors[type] = value;
            if(value !== "none")
            document.getElementById(`${type}Input`).value = value;
}

function applyColorsToPage() {
            let textColor = getTextColor(currentColors.accentColor);
            let bgTextColor = getTextColor(currentColors.backgroundColor);
         document.documentElement.style.setProperty('--text-color', textColor);
            document.documentElement.style.setProperty('--bg-text-color', bgTextColor);
            document.documentElement.style.setProperty('--icon-text-color', currentColors.iconTextColor);
            document.documentElement.style.setProperty('--icon-bg-color', currentColors.iconBgColor);
            document.documentElement.style.setProperty('--bg-color', currentColors.backgroundColor);
            document.documentElement.style.setProperty('--active-color', currentColors.accentColor);
            document.documentElement.style.setProperty('--top-color', currentColors.topColor);
            getRssData.theme = currentColors;
            source.putVariable(JSON.stringify(getRssData))
}

function resetColors() {
            updateColorDisplay('backgroundColor', defaultColors.backgroundColor);
            updateColorDisplay('accentColor', defaultColors.accentColor);
            updateColorDisplay('iconBgColor', defaultColors.iconBgColor);
            updateColorDisplay('iconTextColor', defaultColors.iconTextColor);
            updateColorDisplay('topColor', defaultColors.topColor);
            currentColors = { ...defaultColors };
            java.toast('颜色已重置为默认值');
}

function initializeColors() {
            updateColorDisplay('backgroundColor', currentColors.backgroundColor);
            updateColorDisplay('accentColor', currentColors.accentColor);
            updateColorDisplay('iconBgColor', currentColors.iconBgColor);
            updateColorDisplay('iconTextColor', currentColors.iconTextColor);
            updateColorDisplay('topColor', currentColors.topColor);
            applyColorsToPage();
}

resetBtn.addEventListener('click', resetColors);
