// 元素映射
const colorElements = {
    backgroundColorValue: 'backgroundColor',
    accentColorValue: 'accentColor',
    iconBgColorValue: 'iconBgColor',
    iconTextColorValue: 'iconTextColor',
    topColorValue: 'topColor'
};

// 为每个元素添加监听
Object.entries(colorElements).forEach(([elementId, type]) => {
    const element = document.getElementById(elementId);
    if (!element) return;

    let originalValue = element.textContent;

    element.addEventListener('input', function() {
        const text = this.textContent.replace(/[\n\r]/g, '').substring(0, 7);
        this.textContent = text;
    });

    element.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') {
        e.preventDefault();
        this.blur();
    }
});

    element.addEventListener('blur', function() {
        const text = this.textContent.trim();
        const isValid = /^#[0-9a-fA-F]{6}$|none/.test(text);

        if (isValid) {
            updateColorDisplay(type, text);
            originalValue = text;
        } else {
            this.textContent = originalValue;
        }
    });
});




initializeColors();
document.addEventListener('DOMContentLoaded', initAllEvents);

