}

.video-container {
    position: fixed;
    top: 15px;
    width: 100%;
    height: 56.25vw;
    z-index: 200;
}

#player {
    position: relative;
    width: 100%;
}

:root {
    color-scheme: only light;
    --plyr-color-main: #00aaff;/* 播放器主要颜色 */
    --plyr-control-color: #fff;/* 播放器控件图标颜色 */
    --plyr-control-background: transparent;/* 播放器控件背景颜色 */
    --plyr-video-background: transparent;/* 视频背景颜色 */
    --plyr-range-fill-background: #0099ee;/* 进度条已填充部分的颜色 */
    --plyr-range-thumb-background: #fff;/* 进度条滑块的颜色 */
}

.plyr {
    height: 100% !important;
    width: 100% !important;
    object-fit: cover;
}

.plyr__video-wrapper * {
    touch-action: none !important;
}

.plyr__video-wrapper video {
    touch-action: none !important;
}

.plyr__controls {
    touch-action: none !important;
}

.plyr__control--overlaid {
    background: transparent;
    border: 0;
    border-radius: 100%;
    color: #fff;
    left: calc(50% - 25px);
    top: calc(50% - 45px);
    transform: none;
    width: 60px;
    height: 48px;
    padding: 0;
    z-index: 2;
}

.plyr__control--overlaid svg {
    width: 50px;
    height: 50px;
    left: calc(50% - 25px);
    top: calc(50% - 10px);
    transform: none;
    fill: #fff;/* 大播放器控件图标颜色 */
    filter: 
        drop-shadow(0 0 20px rgba(0, 0, 0, 0.3))
        drop-shadow(0 0 30px rgba(0, 0, 0, 0.1));
}

.plyr__control--overlaid.hidden {
    display: none !important;
    opacity: 0 !important;
    pointer-events: none !important;
}

.plyr--video .plyr__control.plyr__tab-focus,.plyr--video .plyr__control:hover,.plyr--video .plyr__control[aria-expanded=true] {
    background: transparent;/* 播放器控件悬停/点击背景颜色 */
    color: #00aaff;/* 播放器控件悬停/点击图标颜色 */
}

.plyr__controls .plyr__controls__item {
    margin-left: auto;
    margin: calc(var(--plyr-control-spacing,10px)/4);
}

.plyr__time--duration {
    display: inline-block !important;
}

.plyr__time+.plyr__time:before {
    margin-right: 8px !important;
}

@media (max-width: 640px) {
    .plyr__captions {
        margin-bottom:-8px
    }

    .plyr__progress__container {
        margin-right: 5px
    }

    .plyr__time {
        position: absolute;
        bottom: 29px;
    }

    .plyr__time--current {
        left: 106px
    }

    .plyr__time+.plyr__time:before {
        content: ""!important
    }

    .plyr__time--duration {
        right: 110px;
    }

    .plyr__volume {
        width: auto;
        max-width: 32px!important;
        min-width: 32px!important
    }

    input[id^=plyr-volume-] {
        display: none!important;
    }

    .plyr--airplay-supported [data-plyr=airplay],.plyr--captions-enabled [data-plyr=captions],.plyr--pip-supported [data-plyr=pip] {
        display: none!important;
    }
}

