function decodeImage(data, keyBytes) {
  var out = new Packages.java.io.ByteArrayOutputStream()
  var byte
  var count = 0
  var keyLength = keyBytes.length
  while ((byte = data.read()) != -1) {
    if (count < 100) {
      out.write(byte ^ keyBytes[count % keyLength])
      count++
    } else {
      out.write(byte)
    }
  }
  return out.toByteArray()
}
function toByteArray(input) {
  var out = new Packages.java.io.ByteArrayOutputStream();
  var buffer = java.strToBytes('\0'.repeat(4096));
  var bytesRead;
  while ((bytesRead = input.read(buffer)) != -1) {
    out.write(buffer, 0, bytesRead);
  }
  return out.toByteArray();
}
var keyStr = "2019ysapp7527"
var keyBytes = java.strToBytes(keyStr, "UTF-8")
var excludeKeywords = ['yximgs', 'Uploads'];
var shouldExclude = excludeKeywords.some(function(keyword) {
  return src.indexOf(keyword) !== -1;
});
if (shouldExclude) {
  toByteArray(result)
} else {
  decodeImage(result, keyBytes)
}

