ruleContent:
@js:
var doc = org.jsoup.Jsoup.parse(result);
var myImgs = [];

// 1. 严格锁定正文 ID，彻底避开 Related Posts 等外部组件
var contentHtml = "";
var mainBox = doc.getElementById("brxe-qoenez");
if (mainBox) {
    contentHtml = mainBox.html();
} else {
    contentHtml = doc.select(".brxe-post-content").html();
}

if (contentHtml) {
    // 2. 在限定范围内扫描高清图片链接
    var regex = /https?:\/\/qikzj\.com\/wp-content\/uploads\/[^"'\s<>]*?\.(?:jpg|jpeg|png|webp|gif)/gi;
    var matches;
    while ((matches = regex.exec(contentHtml)) !== null) {
        var s = matches[0];
        // 过滤 Logo 和头像
        if (s.indexOf("logo") === -1 && s.indexOf("avatar") === -1) {
            // 还原高清原图路径，去掉尺寸和缩放后缀
            var cleanUrl = s.replace(/-\d+x\d+\./i, ".").replace(/-scaled\./i, ".");
            if (myImgs.indexOf(cleanUrl) === -1) {
                myImgs.push(cleanUrl);
            }
        }
    }
}

var displayTitle = (typeof title !== 'undefined' && title) ? title : "QikZ Visuals";

var h = "<!DOCTYPE html><html><head><style>body{margin:0;background:#050505;color:#eee;font-family:sans-serif;padding-bottom:100px} .top{background:#111;color:#888;text-align:center;padding:15px;font-size:10px;text-transform:uppercase;letter-spacing:3px;border-bottom:1px solid #222} .header{padding:40px 25px;text-align:center} .img-list{padding:0 10px} .img-box{position:relative;margin-bottom:18px;background:#000;border-radius:2px;overflow:hidden;box-shadow:0 10px 30px rgba(0,0,0,0.5)} .img-box img{width:100%;display:block;height:auto} .img-num{position:absolute;bottom:10px;right:15px;background:rgba(0,0,0,0.6);color:#fff;padding:2px 8px;border-radius:2px;font-size:10px;font-family:monospace;font-weight:bold}</style></head><body>";
h += "<div class='top'>HD VISUAL SHOWCASE</div>";
h += "<div class='header'><h1 style='font-size:20px;margin:0;font-weight:300;color:#fff;line-height:1.4'>" + displayTitle + "</h1></div>";
h += "<div class='img-list'>";
for(var k=0; k<myImgs.length; k++){
    h += "<div class='img-box'><img src='" + myImgs[k] + "'><span class='img-num'>" + (k+1) + " / " + myImgs.length + "</span></div>";
}
h += "</div><p style='text-align:center;color:#333;font-size:10px;margin-top:60px;letter-spacing:2px'>QIKZ PHOTOGRAPHY GALLERY</p></body></html>";
result = h;

