getPage = (result) => {
if (result.match(/<!DOCTYPE html>/)){
return result;
}
result = result.match(/<script>(.*?)<\/script>.*/)[1];
result = result.replace('document.write(', '').replace(')', '');
result = 'let doc = ' + result;
eval(result);
return doc;
}

