                padding: 20px;
            }
            .info-container p {
                margin: 10px 0;
                color: #555;
            }
            .info-container p span {
                font-weight: bold;
                color: #000;
            }
            .nav-container {
                display: flex;
                justify-content: space-between;
                align-items: center;
                padding: 15px 20px;
