                    if (input.type === 'text') {
                        // 简单计算 1+1 作为测试
                        input.value = '2';
                        input.dispatchEvent(new Event('input'));
                        console.log('已尝试填写验证码');
                        break;
                    }
                }
            }
        }
    }, 2000);
})();

