function onMatch() {
    var lanzurl =  document.getElementById("textSour").value.match(/.*(http.*?)(#|\s|提取码|密码|$)/)[1];
    var mima = document.getElementById("textSour").value.match(/(#|提取码|密码)/)? document.getElementById("textSour").value.match(/[\s\S]*(码[\s：:]*|#)(.*?)(\,.*|\s*$)/)[2]: document.getElementById("textPattern").value;

var textMatchResult = set+"?type=down&url="+ lanzurl + "&pwd=" + mima;

document.getElementById("textMatchResult").value = textMatchResult;
return textMatchResult;
}

