		$$$.i=i
		return put($$$);
}


//确定启用接口
function yes(){
		i = $$$.i
		if(i==undefined){
			return login('【接口启用提示】\n\n\n　　启用失败，没有选中接口');
			}
		else{
		delete $$$.i;
		if(i==$$$.ci0){
				login('【接口启用提示】\n\n\n　　正在使用此接口，无需启用');
				return put($$$);
			}

		login('【接口启用提示】\n\n\n　　启用成功，已选择序号'+name(i)+'为当前接口\n\n\n\n\n　　退出/成功登录后  -  右上角设置  -  刷新分类即可');
