function getUrls(){
try{
		urllist = []
		I = JSON.parse(java.ajax(api)).class.map($=>{
				turl = url+"&t="+$.type_id;
				urllist.push(turl);
				return $.type_name+"::"+turl;
			}).join('\n').split('\n');
		x = 0
		java.toast('Yes  get Urls\n　Urls is now being verified')
		return verifyUrls()
	}
catch(e){//ajax失败会重新请求两次
