} else if(hours<7){
hours="凌晨 "+hours;
} else if(hours<12){
hours="上午 "+hours;
} else if(hours<13){
hours="正午 "+hours;
} else if(hours<19){
hours="下午 "+[hours-12];
} else if(hours<22){
hours="晚上 "+[hours-12];
} else if(hours<24){
hours="半夜 "+[hours-12];
}

if(day<1){
day="星期天";
} else if(day<2){
day="星期一";
} else if(day<3){
day="星期二";
} else if(day<4){
day="星期三";
} else if(day<5){
day="星期四";
} else if(day<6){
day="星期五";
} else if(day<7){
day="星期六";
}

if(minutes<10){
