@js:

jsBaseUrls=[
"https://raw.githubusercontent.com/Xwite/decodeObfuscator/main/", 

"https://raw.githubusercontents.com/Xwite/decodeObfuscator/main/", 
  "https://cdn.jsdelivr.net/gh/Xwite/decodeObfuscator@main/"];

urls=["plugins/common.js",
"plugins/cocomanhua.js",
"tools/babel_asttool.js",
"tools/config.js",
"tools/decode.js",
"tools/decodeOb.js",
"tools/usefulPlugins.js",
];

function batchFetch(urls){for(url of urls){c=java.ajax(url);if(!c.includes("Exception"))return url}java.toast("js文件下载失败");}


//自动测试链接可用
!source.getVariable() && (jsBaseUrl = batchFetch(jsBaseUrls),jsBaseUrl) &&
source.setVariable(jsBaseUrl);

jsBaseUrl = source.getVariable()

String.prototype.toAbsUrl=function(){
	return /^\.\/|^http|^content|^\/sdcard|^\/storage/.test(this) ? this : jsBaseUrl.concat(this)
}

//解决跨域js加载问题
function loadJS(urls){

	return jsBaseUrl && urls.map(url=>script(java.importScript(url.toAbsUrl())))
	.join("\n") || ""
	}

function script(content){
	return `<script>${content}</script>`
	}

title = "本地ast解密";


`
<html><head>
<title>${title}</title>
${loadJS(urls)}
</head><body>
<h3>解密目标</h3><div id="source" class="textarea" contenteditable="true" onclick=copy(this)>https://www.cocomanga.com/js/custom.js</div><h3>解密结果</h3><div id="result" hidden class="textarea" contenteditable="false" onclick=copy(this)></div><h3>密钥</h3><div id="cocoKeys" hidden class="textarea" contenteditable="false" onclick=copy(this)></div></br><div class="button" hidden id="getJS" onclick=getJS($("#source").innerText)>获取js😄</div><div class="button" onclick=getKeys()>点我解密😄</div>
<div class="button" onclick="updateSource(keys)">点我更新书源😄</div>
<div class="button" onclick="auto()">一键更新书源😄</div>
</body><script>

;function Toast(msg,duration){duration=isNaN(duration)?1000:duration;var m=document.createElement('div');m.innerText=msg;m.style.cssText="font-family:siyuan;max-width:60%;min-width: 150px;padding:0 14px;height: 40px;color: rgb(255, 255, 255);line-height: 40px;text-align: center;border-radius: 4px;position: fixed;top: 50%;left: 50%;transform: translate(-50%, -50%);z-index: 999999;background: rgba(0, 0, 0,.7);font-size: 16px;";document.body.appendChild(m);setTimeout(function(){var d=0.5;m.style.webkitTransition='-webkit-transform '+d+'s ease-in, opacity '+d+'s ease-in';m.style.opacity='0';setTimeout(function(){document.body.removeChild(m);},d*1000);},duration);}
function copy(tar) {
	let data=typeof tar=="string"?tar:tar.innerText;
	navigator.clipboard &&
	navigator.clipboard
	.writeText(data)
	.then(_=>Toast("复制成功"))
	.catch(_=>oldCopy(data)) ||
	oldCopy(data)
}
function oldCopy(str) {
    if (str != "") {
        let input = document.createElement("input");
        input.id = "copy";
        input.value = String(str);
        document.body.appendChild(input);
        input.select();
        try {
            let success = document.execCommand("copy"),
            msg = success ? "复制成功!" : "复制失败!";
            Toast(msg);
        } catch (e) {
            Toast("浏览器暂不支持复制")
        }
        document.body.removeChild(input);
    } else {
        //Toast("内容为空")
    }
}
var $=e=>document.querySelector(e);function HttpGetJson(url){return fetch(url).then(res=>res.json()).catch(err=>alert("阅读web服务异常，请重试"));}function HttpGetText(url){return fetch(url).then(res=>res.text()).catch(err=>alert(err));};var port;function updateSource(keys){port=port||window.prompt("打开阅读web服务并输入端口号","1124");let b="http://127.0.0.1:"+port;HttpGetJson(b+"/getBookSource?url=https://www.cocomanga.com").then(data=>replaceKeys(data.data,keys)).then(source=>location.href="legado://import/bookSource?src="+encodeURIComponent(JSON.stringify(source)));}function replaceKeys(source,keys){source.ruleContent.content=source.ruleContent.content.replace(/local_keys=.*/,"local_keys="+keys+';');return source;}function getJS(e){$("#source").hidden=!1,$("#result").hidden=!0,$("#cocoKeys").hidden=!0;if(!/js$/.test(e)){alert("不是js文件");}else{return HttpGetText(e).then(js=>$("#source").innerText=js);}}function getKeys(){try{alert("开始解密，请等待"),$("#result").innerText=decode($("#source").innerText,[common,cocomanhua]),globalThis.keys&&($("#cocoKeys").hidden=!1,$("#cocoKeys").innerText=globalThis.keys),$("#result").hidden=!1,$("#source").hidden=!0;return new Promise(resolve=>resolve(globalThis.keys));}catch(e){alert(e);}}function auto(){getJS($('#source').innerText).then(_=>getKeys()).then(keys=>updateSource(keys));}window.onload=()=>{typeof parser=="undefined"&&alert("ast加载失败，返回列表，手动删除源变量后重试");!location.href.match(/cocomanga.com/)&&($("#getJS").remove(),$("#source").innerText="复制要解密的js")||(port=window.prompt("打开阅读web服务并输入端口号","1124"),port&&auto());};
</script></html>
`

