@js:id='{{$.index}}'
if(id.match(/^h/)){
id=String(id).replace('','')
url='legado://import/auto?src='+id
result=`<title>{{$.text}}</title>
<iframe src="${url}" hidden></iframe>
<br><h3>{{$.text}}</h3>
<h5>导入不成功？多导入几次试试<br>提示没有浏览器，升级阅读3.0到最新版<br>格式不对，提示英文，使用电信网络/魔法上网<br>如果导入后不会用，请关注微信公众号<br>阅读加油<br>有食用教程滴</h5>
<h6><b>
↓资源链接，点击复制
<a href="${url}">一键导入</a>
<textarea id="copy" onclick="copy()">${id}</textarea>
{{$.intro}}
</b></h6><style>
a{float:right;text-decoration:none}
h3,h5{text-align:center}
h6{margin:0 2;position:sticky;top:30%}
textarea{width:100%;border-radius:5px}
</style><script>
function copy(){
	document.getElementById('copy').select()
	document.execCommand('copy')
	alert("链接复制成功👉请粘贴到对应导入地方导入")
}
</script>`}

